_eff_words_cache = None


def _eff_words():
    global _eff_words_cache
    if _eff_words_cache is None:
        import base64
        import zlib
        _eff_words_cache = zlib.decompress(
            base64.b85decode(_EFF_WORDLIST_B85)).decode().split("\n")
        assert len(_eff_words_cache) == 7776
    return _eff_words_cache


def generate_passphrase(word_count=6, separator="-"):
    """Cryptographically secure diceware passphrase (secrets, never random).

    Returns (phrase, entropy_bits). 6 words ~ 77.5 bits — comfortably beyond
    offline-cracking reach for an scrypt-derived key."""
    import math
    import secrets
    words = _eff_words()
    word_count = max(3, min(20, int(word_count)))
    phrase = separator.join(secrets.choice(words) for _ in range(word_count))
    return phrase, round(word_count * math.log2(len(words)), 1)


def _set_creds_passphrase(pw):
    """Seed the in-process passphrase cache (e.g. from --generate) so the
    next _creds_passphrase() uses it without prompting."""
    global _creds_passphrase_cache
    _creds_passphrase_cache = bytearray(pw.encode("utf-8"))


def _creds_passphrase(confirm=False):
    global _creds_passphrase_cache
    if _creds_passphrase_cache is None:
        # Normally captured at startup; handle paths where that hasn't run.
        _scrub_passphrase_env()
    if _creds_passphrase_cache is not None:
        return _creds_passphrase_cache  # from env, or already entered — don't re-ask
    if not _stdin_is_tty():
        raise SystemExit("Error: encrypted credentials need a passphrase. Set "
                         "BLITCP_CREDS_PASSPHRASE or run in a terminal.")
    pw = getpass.getpass("  Credentials passphrase: ")
    if confirm and pw != getpass.getpass("  Confirm passphrase: "):
        raise SystemExit("Error: passphrases did not match.")
    if not pw:
        raise SystemExit("Error: empty passphrase.")
    _creds_passphrase_cache = bytearray(pw.encode("utf-8"))
    return _creds_passphrase_cache


def _derive_key(passphrase, salt, n=None, r=None, p=None):
    n = n or _SCRYPT["n"]
    r = r or _SCRYPT["r"]
    p = p or _SCRYPT["p"]
    return hashlib.scrypt(passphrase, salt=salt, dklen=32, n=n, r=r, p=p,
                          maxmem=_scrypt_maxmem(n, r))


def encrypt_conns(conns, passphrase):
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    salt, nonce = os.urandom(16), os.urandom(12)
    key = _derive_key(passphrase, salt)
    binhash = _self_hash()
    pt = json.dumps({"connections": conns}).encode("utf-8")
    ct = AESGCM(key).encrypt(nonce, pt, binhash.encode("utf-8"))
    env = {"magic": CREDS_MAGIC, "kdf": "scrypt", **_SCRYPT,
           "salt": base64.b64encode(salt).decode(),
           "nonce": base64.b64encode(nonce).decode(),
           "binhash": binhash,
           "ct": base64.b64encode(ct).decode()}
    return json.dumps(env, indent=2).encode("utf-8")


def _is_encrypted(raw):
    try:
        return json.loads(raw).get("magic") == CREDS_MAGIC
    except (ValueError, AttributeError):
        return False


def _stored_binhash(raw):
    """The bound-binary hash recorded in the envelope (plaintext AEAD AAD), or
    '' if unreadable. Lets us check the binary binding without the passphrase."""
    try:
        return json.loads(raw).get("binhash", "") or ""
    except (ValueError, AttributeError):
        return ""


def decrypt_conns(raw, passphrase):
    """Returns (conns, stored_binhash). Raises SystemExit on bad passphrase."""
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        from cryptography.exceptions import InvalidTag
    except ImportError:
        raise SystemExit("Error: encrypted credentials need the 'cryptography' "
                         "package. Install: python -m pip install cryptography")
    env = json.loads(raw)
    salt = base64.b64decode(env["salt"])
    key = _derive_key(passphrase, salt, n=env.get("n"), r=env.get("r"),
                      p=env.get("p"))
    try:
        pt = AESGCM(key).decrypt(base64.b64decode(env["nonce"]),
                                 base64.b64decode(env["ct"]),
                                 env.get("binhash", "").encode("utf-8"))
    except InvalidTag:
        raise SystemExit("Error: wrong passphrase, or the credentials file was "
                         "tampered with.")
    return json.loads(pt)["connections"], env.get("binhash", "")


def _set_hidden(path):
    """Windows: set the HIDDEN attribute. Unix: file already lives in ~/.config
    (a hidden dir); nothing extra needed."""
    if sys.platform == "win32":
        try:
            import ctypes
            FILE_ATTRIBUTE_HIDDEN = 0x2
            attrs = ctypes.windll.kernel32.GetFileAttributesW(path)
            if attrs != -1:
                ctypes.windll.kernel32.SetFileAttributesW(
                    path, attrs | FILE_ATTRIBUTE_HIDDEN)
        except Exception:
            pass


def set_immutable(path, on):
    """Toggle OS-level immutability. Returns (ok, message). NOTE: this is
    tamper-resistance, not confidentiality, and is not absolute against root —
    root can always reverse it. Setting it generally requires root/admin."""
    sysname = platform.system()
    try:
        if sysname == "Linux":
            import subprocess
            r = subprocess.run(["chattr", "+i" if on else "-i", path],
                               capture_output=True, text=True)
            if r.returncode != 0:
                msg = (r.stderr.strip() or "chattr failed") + \
                    " (needs root: try sudo, and an ext4/xfs/btrfs filesystem)"
                return False, msg
            return True, None
        if sysname == "Darwin":
            import subprocess
            r = subprocess.run(["chflags", "uchg" if on else "nouchg", path],
                               capture_output=True, text=True)
            return (r.returncode == 0, r.stderr.strip() or None)
        if sysname == "Windows":
            import ctypes
            RO = 0x1
            a = ctypes.windll.kernel32.GetFileAttributesW(path)
            if a == -1:
                return False, "GetFileAttributes failed"
            a = (a | RO) if on else (a & ~RO)
            ok = ctypes.windll.kernel32.SetFileAttributesW(path, a)
            return (bool(ok), None if ok else "SetFileAttributes failed "
                    "(note: read-only is weak; admins override it)")
        return False, f"immutability not supported on {sysname}"
    except FileNotFoundError:
        return False, "the immutability tool (chattr/chflags) is not installed"
    except Exception as e:
        return False, str(e)


def _is_immutable(path):
    """Best-effort check of the OS immutable attribute. Returns True only if we
    can positively confirm it is set; False on any uncertainty (unsupported FS,
    platform without a flag we can read, or error). Unlike the return value of
    `set_immutable(on=False)`, this reflects the file's actual state — clearing
    an already-clear flag 'succeeds' for any owner, so the unlock result can't
    be used to tell whether the file was really protected."""
    try:
        if _system == "Linux":
            import fcntl
            import array
            FS_IOC_GETFLAGS = 0x80086601
            FS_IMMUTABLE_FL = 0x00000010
            flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
            fd = os.open(path, flags)
            try:
                buf = array.array("B", b"\x00" * 8)
                fcntl.ioctl(fd, FS_IOC_GETFLAGS, buf, True)
                return bool(int.from_bytes(buf, "little") & FS_IMMUTABLE_FL)
            finally:
                os.close(fd)
        if _system == "Windows":
            # No true immutability on Windows — set_immutable() approximates it
            # with the read-only attribute, so mirror that here.
            import ctypes
            FILE_ATTRIBUTE_READONLY = 0x1
            a = ctypes.windll.kernel32.GetFileAttributesW(str(path))
            return a != -1 and bool(a & FILE_ATTRIBUTE_READONLY)
        # macOS/BSD surface immutability through stat flags.
        st = os.lstat(path)
        UF_IMMUTABLE, SF_IMMUTABLE = 0x00000002, 0x00020000
        return bool(getattr(st, "st_flags", 0) & (UF_IMMUTABLE | SF_IMMUTABLE))
    except Exception:
        return False


_tamper_warned = False  # one tamper-check Note per process (file is read twice)
_creds_cache = {}       # realpath -> decrypted conns, this process only


def load_credentials_file(path=None):
    """Load {name: {type, ...}} connections. Returns {} if no file. Decrypts
    transparently when the file is encrypted. Warns if perms are loose, or if
    the bound binary hash no longer matches (tamper-evidence).

    The result is memoized per resolved path for the life of the process: a
    single run reads/decrypts the file at most once even though it's loaded
    from several call sites (endpoint-name resolution, then the backend). Any
    write through _save_credentials_file invalidates the cache."""
    explicit = path is not None
    path = path or default_credentials_path()
    if not os.path.isfile(path):
        if explicit:
            print(f"  {C.YELLOW}Warning: credentials file not found: {path}{C.RESET}")
        return {}
    ckey = _fs_realpath(path)
    if ckey in _creds_cache:
        return _creds_cache[ckey]
    if hasattr(os, "geteuid"):
        try:
            mode = stat.S_IMODE(os.stat(path).st_mode)
            if mode & (stat.S_IRWXG | stat.S_IRWXO):
                print(f"  {C.YELLOW}Warning: {path} is group/world-accessible "
                      f"(mode {oct(mode)}). Fix: chmod 600 {path}{C.RESET}")
        except OSError:
            pass
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError as e:
        raise SystemExit(f"Error: cannot read credentials file {path}: {e}")
    if _is_encrypted(raw):
        # The bound-binary hash is stored in the envelope as plaintext (it's the
        # AEAD associated data), so we can warn about a mismatch *before* asking
        # for the passphrase — the prompt then has context, and the user can
        # rekey instead of typing into an unexpectedly-rebound file.
        cur = _self_hash()
        stored = _stored_binhash(raw)
        # The file is legitimately read more than once per run (endpoint-name
        # resolution, then the backend), so warn at most once per process.
        global _tamper_warned
        if stored and cur and stored != cur and not _tamper_warned:
            _tamper_warned = True
            print(f"  {C.YELLOW}Note: this credentials file was bound to a "
                  f"different blitcp (tamper check). If you just updated, "
                  f"run 'creds rekey' to re-bind.{C.RESET}")
        conns, _ = decrypt_conns(raw, _creds_passphrase())
        result = conns if isinstance(conns, dict) else {}
        _creds_cache[ckey] = result
        return result
    try:
        data = json.loads(raw)
    except ValueError as e:
        raise SystemExit(f"Error: cannot parse credentials file {path}: {e}")
    conns = data.get("connections", data) if isinstance(data, dict) else {}
    if not isinstance(conns, dict):
        raise SystemExit(f"Error: credentials file {path} has no 'connections' map.")
    _creds_cache[ckey] = conns
    return conns


def resolve_connection(spec, args):
    """Merge credentials for one cloud endpoint. Priority: a named connection
    from the file (when 'name@' is used, or a connection literally named
    'default' whose type matches) → overlaid by any explicit CLI flags. Returns
    a dict the backend reads; empty dict means 'use flags/env as before'."""
    name = spec.connection
    explicit_file = getattr(args, "credentials_file", None)
    # Only touch the credentials file when it's actually wanted. A named
    # connection or an explicit --credentials-file → load it (decrypt/prompt as
    # needed). Otherwise we only *peek* at a default-path file for a "default"
    # connection — and if that file is encrypted with no passphrase available,
    # skip it silently rather than forcing a prompt on an unrelated transfer.
    conns = {}
    if name or explicit_file:
        conns = load_credentials_file(explicit_file)
    elif os.path.isfile(default_credentials_path()):
        if _file_is_encrypted(default_credentials_path()) and \
                not _have_creds_passphrase():
            conns = {}
        else:
            try:
                conns = load_credentials_file(None)
            except SystemExit:
                conns = {}
    creds = {}
    if not name and "default" in conns and \
            isinstance(conns["default"], dict) and \
            conns["default"].get("type") == spec.scheme:
        name = "default"
    if name:
        if name not in conns:
            raise SystemExit(f"Error: no connection named {name!r} in the "
                             f"credentials file.")
        conn = conns[name]
        ctype = conn.get("type")
        if ctype and ctype != spec.scheme:
            raise SystemExit(f"Error: connection {name!r} is type {ctype!r} but "
                             f"the URL is {spec.scheme}://.")
        creds = {k: v for k, v in conn.items() if k != "type"}
    # Explicit flags override file values for this invocation.
    flag_overlay = {
        "s3": {"endpoint_url": getattr(args, "endpoint_url", None),
               "region": getattr(args, "s3_region", None),
               "profile": getattr(args, "s3_profile", None)},
        "az": {"connection_string": getattr(args, "az_connection_string", None),
               "account": getattr(args, "az_account", None),
               "key": getattr(args, "az_key", None)},
        "gs": {"project": getattr(args, "gcs_project", None),
               "credentials": getattr(args, "gcs_credentials", None)},
    }.get(spec.scheme, {})
    for k, v in flag_overlay.items():
        if v:
            creds[k] = v
    return creds


CLOUD_SCHEME_NAMES = {"s3": "S3", "az": "Azure Blob", "gs": "Google Cloud Storage",
                      "smb": "SMB/CIFS"}


def _quote_rel(rel):
    import urllib.parse
    return urllib.parse.quote(rel, safe="")


def _unquote_rel(val):
    import urllib.parse
    return urllib.parse.unquote(val)


def build_object_meta(entry, hash_hex, preserve=None):
    """blitcp object metadata so a download restores the file faithfully and
    cross-run dedup works without re-reading bytes. All keys lowercase (S3
    lowercases user metadata regardless)."""
    preserve = preserve or set()
    meta = {
        "fc_relpath": _quote_rel(entry.rel),
        "fc_hash": hash_hex or "",
        "fc_hash_algo": _hash_name,
    }
    try:
        st = os.stat(entry.src)
        meta["fc_mtime"] = repr(st.st_mtime)
        meta["fc_mode"] = oct(stat.S_IMODE(st.st_mode))
        if "owner" in preserve:
            meta["fc_uid"] = str(getattr(st, "st_uid", 0))
            meta["fc_gid"] = str(getattr(st, "st_gid", 0))
    except OSError:
        pass
    return meta


def apply_object_meta_local(local_path, meta):
    """Restore mtime/mode (and owner when present + permitted) from object
    metadata onto a freshly downloaded local file. Best-effort, single-line
    warnings only.

    SYMLINK-SAFE: mutates through an O_NOFOLLOW fd (POSIX), so a symlink swapped
    in between download and here can't redirect a privileged chown/chmod onto an
    arbitrary file — matching the tar/SFTP remote-to-local paths. The object's
    metadata is UNTRUSTED (a bucket may be attacker-writable), so setuid/setgid
    is stripped from the mode."""
    if not meta:
        return
    uid, gid = meta.get("fc_uid"), meta.get("fc_gid")
    safe_mode = None
    if meta.get("fc_mode"):
        try:  # untrusted object metadata → strip setuid/setgid
            safe_mode = int(meta["fc_mode"], 8) & ~(stat.S_ISUID | stat.S_ISGID)
        except ValueError:
            safe_mode = None
    t = None
    if meta.get("fc_mtime"):
        try:
            t = float(meta["fc_mtime"])
        except ValueError:
            t = None

    fd = None
    if hasattr(os, "O_NOFOLLOW") and hasattr(os, "fchmod"):
        try:
            fd = os.open(local_path, os.O_RDONLY | os.O_NOFOLLOW
                         | getattr(os, "O_CLOEXEC", 0))
        except OSError:
            fd = None  # symlink planted, or the (rare) mode-0 file can't be opened
    if fd is not None:
        try:
            # Owner BEFORE mode: os.fchown clears setuid/setgid (cp -a chowns 1st).
            if uid and gid and hasattr(os, "fchown"):
                try:
                    os.fchown(fd, int(uid), int(gid))
                except (OSError, ValueError):
                    pass
            if safe_mode is not None:
                try:
                    os.fchmod(fd, safe_mode)
                except OSError:
                    pass
            if t is not None:
                try:
                    os.utime(fd, (t, t))
                except OSError:
                    pass
        finally:
            os.close(fd)
        return
    # Fallback: Windows (no O_NOFOLLOW), or the fd couldn't be opened (rare mode-0
    # download). Path-based mode/times, guarded against a symlink at local_path.
    # Owner is NOT applied here — a path-based chown follows symlinks (TOCTOU);
    # owner restoration requires the fd path above.
    try:
        if not os.path.islink(local_path):
            if safe_mode is not None:
                os.chmod(_long_path(local_path), safe_mode)
            if t is not None:
                os.utime(_long_path(local_path), (t, t))
    except OSError:
        pass


# ── Backend base + provider implementations ─────────────────────────────────
class _ChunkReader:
    """Wrap an iterator of byte chunks (e.g. Azure's .chunks()) into a
    sequential .read(n) file-like, for the streaming-relay pipeline."""

    def __init__(self, chunks):
        self._it = iter(chunks)
        self._buf = b""
        self._done = False

    def read(self, n=-1):
        while not self._done and (n < 0 or len(self._buf) < n):
            try:
                self._buf += next(self._it)
            except StopIteration:
                self._done = True
        if n < 0:
            out, self._buf = self._buf, b""
        else:
            out, self._buf = self._buf[:n], self._buf[n:]
        return out

    def close(self):
        self._it = iter(())
        self._done = True


class CloudBackend:
    """Common interface. Subclasses implement the primitives; the orchestrator
    is provider-agnostic."""
    scheme = ""

    def __init__(self, spec, args, creds=None):
        self.spec = spec
        self.container = spec.container
        self.prefix = spec.prefix
        self.args = args
        # Resolved credentials for this endpoint (from the credentials file /
        # name@bucket / flags). Empty → backend falls back to env, as before.
        self.creds = creds or {}

    # discovery
    def list_objects(self, prefix):
        """Return {full_key: {'size': int}} for every object under prefix."""
        raise NotImplementedError

    def head(self, key):
        """Return metadata dict for key, or None if it does not exist."""
        raise NotImplementedError

    # transfer
    def upload(self, local_path, key, metadata):
        raise NotImplementedError

    def download(self, key, local_path):
        """Download key to local_path; return its metadata dict."""
        raise NotImplementedError

    def server_side_copy(self, src_key, dst_key, metadata):
        """Copy within the same container/account without round-tripping bytes."""
        raise NotImplementedError

    # streaming (relay) — CLOUD_RELAY_DESIGN.md §2
    def open_read(self, key):
        """Return (file_like, size, meta). file_like yields the object's bytes
        sequentially via .read(n); the caller never seeks it."""
        raise NotImplementedError

    def upload_stream(self, fileobj, key, metadata, size):
        """Upload exactly `size` bytes read from a SEEKABLE fileobj to key.
        Seekability keeps SDK retries (multipart/resumable) safe."""
        raise NotImplementedError

    def join_key(self, prefix, rel):
        rel = rel.replace(os.sep, "/")
        if not prefix:
            return rel
        return prefix.rstrip("/") + "/" + rel


class S3Backend(CloudBackend):
    scheme = "s3"

    def __init__(self, spec, args, creds=None):
        super().__init__(spec, args, creds)
        try:
            import boto3
            from botocore.config import Config
        except ImportError:
            raise SystemExit("Error: S3 transfers require boto3. "
                             "Install with: python -m pip install boto3")
        c = self.creds
        session_kwargs = {}
        if c.get("profile"):
            session_kwargs["profile_name"] = c["profile"]
        session = boto3.Session(**session_kwargs)
        cfg = Config(signature_version="s3v4",
                     retries={"max_attempts": 5, "mode": "standard"})
        client_kwargs = {
            "endpoint_url": c.get("endpoint_url"),
            "region_name": c.get("region") or "us-east-1",
            "config": cfg,
        }
        # Explicit keys from the credentials file (else boto3's default chain:
        # env / ~/.aws / instance profile).
        has_explicit_keys = bool(c.get("access_key_id")
                                 and c.get("secret_access_key"))
        if has_explicit_keys:
            client_kwargs["aws_access_key_id"] = c["access_key_id"]
            client_kwargs["aws_secret_access_key"] = c["secret_access_key"]
            if c.get("session_token"):
                client_kwargs["aws_session_token"] = c["session_token"]
        self.client = session.client("s3", **client_kwargs)
        # Fail fast with a clean message instead of a NoCredentialsError
        # traceback at the first API call. Only check the default chain when
        # no explicit keys were given (session creds don't reflect client keys).
        if not has_explicit_keys and session.get_credentials() is None:
            raise SystemExit(
                "Error: S3 needs credentials. Add them with `creds add`, use "
                "--s3-profile, or set AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY "
                "(and AWS_SESSION_TOKEN if used).")

    def list_objects(self, prefix):
        out = {}
        paginator = self.client.get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=self.container, Prefix=prefix or ""):
            for obj in page.get("Contents", []):
                # The ETag is already in this response. For an object stored by
                # a single PUT it is the MD5 of the bytes, which is the only
                # content fingerprint a download can get without paying for a
                # request per object — see _cloud_download_skip.
                out[obj["Key"]] = {"size": obj["Size"],
                                   "etag": (obj.get("ETag") or "").strip('"')}
        return out

    def head(self, key):
        try:
            r = self.client.head_object(Bucket=self.container, Key=key)
            return dict(r.get("Metadata", {}))
        except Exception:
            return None

    def upload(self, local_path, key, metadata):
        self.client.upload_file(
            local_path, self.container, key,
            ExtraArgs={"Metadata": metadata,
                       "ChecksumAlgorithm": "SHA256"})

    def download(self, key, local_path):
        r = self.client.get_object(Bucket=self.container, Key=key)
        body = r["Body"]
        with open(local_path, "wb") as f:
            for chunk in body.iter_chunks(chunk_size=1024 * 1024):
                f.write(chunk)
        return dict(r.get("Metadata", {}))

    def server_side_copy(self, src_key, dst_key, metadata):
        self.client.copy_object(
            Bucket=self.container, Key=dst_key,
            CopySource={"Bucket": self.container, "Key": src_key},
            Metadata=metadata, MetadataDirective="REPLACE")

    def open_read(self, key):
        r = self.client.get_object(Bucket=self.container, Key=key)
        return (r["Body"], int(r.get("ContentLength") or 0),
                dict(r.get("Metadata", {})))

    def upload_stream(self, fileobj, key, metadata, size):
        # use_threads=False: the relay already parallelises across OBJECTS;
        # s3transfer's per-call thread pool on top of that raced concurrent
        # part reads on the shared spool and desynced the connection (an
        # UploadPart 200 landed as unparsed garbage → KeyError 'ETag').
        from boto3.s3.transfer import TransferConfig
        self.client.upload_fileobj(
            fileobj, self.container, key,
            Config=TransferConfig(use_threads=False),
            ExtraArgs={"Metadata": metadata,
                       "ChecksumAlgorithm": "SHA256"})


class AzureBackend(CloudBackend):
    scheme = "az"

    def __init__(self, spec, args, creds=None):
        super().__init__(spec, args, creds)
        try:
            from azure.storage.blob import BlobServiceClient
        except ImportError:
            raise SystemExit("Error: Azure transfers require azure-storage-blob. "
                             "Install with: python -m pip install azure-storage-blob")
        c = self.creds
        conn = c.get("connection_string") \
            or os.environ.get("AZURE_STORAGE_CONNECTION_STRING")
        if conn:
            self.service = BlobServiceClient.from_connection_string(conn)
        else:
            account = c.get("account") \
                or os.environ.get("AZURE_STORAGE_ACCOUNT")
            key = c.get("key") \
                or os.environ.get("AZURE_STORAGE_KEY")
            if not account:
                raise SystemExit("Error: Azure needs --az-connection-string, or "
                                 "--az-account (+ --az-key), or the "
                                 "AZURE_STORAGE_* environment variables.")
            url = f"https://{account}.blob.core.windows.net"
            self.service = BlobServiceClient(account_url=url, credential=key)
        self.cc = self.service.get_container_client(self.container)

    def list_objects(self, prefix):
        out = {}
        for b in self.cc.list_blobs(name_starts_with=prefix or ""):
            out[b.name] = {"size": b.size}
        return out

    def head(self, key):
        try:
            props = self.cc.get_blob_client(key).get_blob_properties()
            return dict(props.metadata or {})
        except Exception:
            return None

    def upload(self, local_path, key, metadata):
        bc = self.cc.get_blob_client(key)
        with open(local_path, "rb") as f:
            bc.upload_blob(f, overwrite=True, metadata=metadata)

    def download(self, key, local_path):
        bc = self.cc.get_blob_client(key)
        stream = bc.download_blob()
        with open(local_path, "wb") as f:
            stream.readinto(f)
        try:
            meta = dict(bc.get_blob_properties().metadata or {})
        except Exception:
            meta = {}
        return meta

    def server_side_copy(self, src_key, dst_key, metadata):
        src = self.cc.get_blob_client(src_key)
        dst = self.cc.get_blob_client(dst_key)
        dst.start_copy_from_url(src.url, metadata=metadata)

    def open_read(self, key):
        dl = self.cc.get_blob_client(key).download_blob()
        try:
            meta = dict(dl.properties.metadata or {})
        except Exception:
            meta = {}
        return _ChunkReader(dl.chunks()), int(dl.size or 0), meta

    def upload_stream(self, fileobj, key, metadata, size):
        self.cc.get_blob_client(key).upload_blob(
            fileobj, length=size, overwrite=True, metadata=metadata)


class GCSBackend(CloudBackend):
    scheme = "gs"

    def __init__(self, spec, args, creds=None):
        super().__init__(spec, args, creds)
        try:
            from google.cloud import storage
        except ImportError:
            raise SystemExit("Error: GCS transfers require google-cloud-storage. "
                             "Install with: python -m pip install google-cloud-storage")
        c = self.creds
        client_kwargs = {}
        if c.get("project"):
            client_kwargs["project"] = c["project"]
        creds_path = c.get("credentials")
        emulator = os.environ.get("STORAGE_EMULATOR_HOST")
        if creds_path:
            self.client = storage.Client.from_service_account_json(
                creds_path, **client_kwargs)
        elif emulator:
            from google.auth.credentials import AnonymousCredentials
            self.client = storage.Client(
                credentials=AnonymousCredentials(),
                client_options={"api_endpoint": emulator},
                project=client_kwargs.get("project", "fast-copy"))
        else:
            try:
                self.client = storage.Client(**client_kwargs)
            except Exception as e:
                from google.auth.exceptions import DefaultCredentialsError
                if isinstance(e, DefaultCredentialsError):
                    raise SystemExit(
                        "Error: GCS needs credentials. Provide --gcs-credentials "
                        "<service-account.json>, set GOOGLE_APPLICATION_CREDENTIALS, "
                        "or run `gcloud auth application-default login`.")
                raise
        self.bucket = self.client.bucket(self.container)

    def list_objects(self, prefix):
        out = {}
        for b in self.client.list_blobs(self.container, prefix=prefix or ""):
            out[b.name] = {"size": b.size or 0}
        return out

    def head(self, key):
        b = self.bucket.get_blob(key)
        if b is None:
            return None
        return dict(b.metadata or {})

    def upload(self, local_path, key, metadata):
        blob = self.bucket.blob(key)
        blob.metadata = metadata
        blob.upload_from_filename(local_path)

    def download(self, key, local_path):
        blob = self.bucket.get_blob(key)
        if blob is None:
            raise FileNotFoundError(f"gs://{self.container}/{key}")
        blob.download_to_filename(local_path)
        return dict(blob.metadata or {})

    def server_side_copy(self, src_key, dst_key, metadata):
        src = self.bucket.blob(src_key)
        new = self.bucket.copy_blob(src, self.bucket, dst_key)
        if metadata:
            new.metadata = metadata
            new.patch()

    def open_read(self, key):
        blob = self.bucket.get_blob(key)
        if blob is None:
            raise FileNotFoundError(f"gs://{self.container}/{key}")
        return blob.open("rb"), int(blob.size or 0), dict(blob.metadata or {})

    def upload_stream(self, fileobj, key, metadata, size):
        blob = self.bucket.blob(key)
        blob.metadata = metadata
        blob.upload_from_file(fileobj, size=size)


class _SMBLockedFile:
    """SMB read handle that holds the backend's session lock for its whole
    lifetime (concurrent ops on one SMB session corrupt data — see
    SMBBackend.__init__). Release is close-once safe."""

    def __init__(self, f, lock):
        self._f = f
        self._lock = lock
        self._released = False

    def read(self, n=-1):
        return self._f.read(n)

    def close(self):
        try:
            self._f.close()
        finally:
            if not self._released:
                self._released = True
                self._lock.release()


class ObjectNameRefused(Exception):
    """The store refused the NAME, not the bytes.

    A share can legitimately be unable to hold a name: SMB reserves
    " * : < > ? \\ / | in a filename, so quote'and"quote.txt cannot exist on
    one whatever the underlying filesystem could store. That is not a
    transfer error — nothing broke, a rule said no — and it is the same
    distinction the local engines draw between "refused" and "error".

    It was neither, before: the upload recorded no per-file entries at all,
    so the file was absent from the destination, absent from the record, and
    the run said nothing. Measured against a real Samba (2026-09-10): the
    server answers the CREATE with NT_STATUS_OBJECT_NAME_INVALID and does not
    even log the name, because it rejects it before resolving it.

    Raised by a backend, turned into a refusal by the transfer driver, so the
    protocol knowledge stays in the backend and the accounting stays in one
    place.
    """


class SMBBackend(CloudBackend):
    """SMB/CIFS share as an object backend, via the pure-Python smbprotocol
    library. container=share, prefix=path within the share. Credentials resolve
    from a saved connection (by host), --smb-* flags, or env. SMB has no
    per-object metadata store, so cross-run dedup/verify ride the same
    HMAC-signed manifest sidecar the cloud backends use; mtime is preserved
    natively, mode/owner are best-effort (manifest only)."""
    scheme = "smb"

    def __init__(self, spec, args, creds=None):
        super().__init__(spec, args, creds)
        try:
            import smbclient
            import smbprotocol.exceptions as _smbexc
        except ImportError:
            raise SystemExit("Error: SMB transfers require smbprotocol. "
                             "Install with: python -m pip install smbprotocol")
        self._sc = smbclient
        self._smbexc = _smbexc
        c = dict(self.creds or {})
        stash = (getattr(args, "_smb_creds", None) or {}).get(spec.host, {})
        for k, v in stash.items():
            c.setdefault(k, v)
        self.host = spec.host or c.get("host")
        if not self.host:
            raise SystemExit("Error: SMB needs a host "
                             "(smb://host/share or a saved connection).")
        self.port = int(spec.port or c.get("port")
                        or getattr(args, "smb_port", None) or 445)
        user = spec.user or c.get("user") or getattr(args, "smb_user", None)
        domain = c.get("domain") or getattr(args, "smb_domain", None)
        password = c.get("password")
        if not password and getattr(args, "smb_password_env", None):
            password = os.environ.get(args.smb_password_env)
        if not password and getattr(args, "smb_password", False):
            password = getpass.getpass(
                f"  SMB password for {user or ''}@{self.host}: ")
        encrypt = not getattr(args, "smb_no_encrypt", False)
        # Connection kwargs passed to EVERY smbclient call: get_smb_tree only
        # reuses a pooled session when server + credentials + port match, so the
        # non-default port and creds must travel with each operation.
        self._ck = dict(
            username=(f"{domain}\\{user}" if (domain and user) else user),
            password=password, port=self.port, encrypt=encrypt)
        # The transfer drivers call upload/download/server_side_copy from a
        # thread pool, but concurrent operations on an SMB session corrupted
        # small files in testing (a parallel write/copy could land 0 bytes). SMB
        # over a single connection gains little from fan-out anyway, so serialise
        # every backend operation with a re-entrant lock — correctness first.
        self._lock = threading.RLock()
        try:
            try:
                smbclient.register_session(self.host, **self._ck)
            except TypeError:                      # older lib without encrypt kw
                self._ck.pop("encrypt", None)
                smbclient.register_session(self.host, **self._ck)
        except Exception as e:
            raise SystemExit(f"Error: SMB connection to {self.host} failed: "
                             f"{str(e).splitlines()[0] if str(e) else e}")
        self.root = "\\\\" + self.host + "\\" + self.container
        self._dl_manifest = None

    def _unc(self, key):
        sub = (key or "").replace("/", "\\").strip("\\")
        return self.root + ("\\" + sub if sub else "")

    def _ensure_manifest(self):
        if self._dl_manifest is None:
            self._dl_manifest = _load_cloud_manifest(self, self.prefix) or {}

    def _meta_for(self, key):
        """fc_* metadata for a key from the manifest (SMB keeps none on the
        object), so verify + relpath-restore work on download/head."""
        if key.endswith((CLOUD_MANIFEST_NAME, LEGACY_CLOUD_MANIFEST_NAME)):
            return {}
        self._ensure_manifest()
        prefix = self.prefix.rstrip("/")
        rel = key[len(prefix):].lstrip("/") \
            if prefix and key.startswith(prefix) else key
        info = self._dl_manifest.get(rel)
        meta = {}
        if info and info.get("hash"):
            meta = {"fc_hash": info["hash"], "fc_hash_algo": _hash_name,
                    "fc_relpath": _quote_rel(rel)}
        try:
            meta.setdefault("fc_mtime",
                            repr(self._sc.stat(self._unc(key), **self._ck).st_mtime))
        except Exception:
            pass
        return meta

    def list_objects(self, prefix):
        out = {}
        base = self.root.rstrip("\\")
        root = self._unc(prefix or "")
        with self._lock:
            # Single-file prefix → return just that object.
            try:
                st = self._sc.stat(root, **self._ck)
                if not stat.S_ISDIR(st.st_mode):
                    rel = root[len(base):].lstrip("\\").replace("\\", "/")
                    return {rel: {"size": st.st_size}}
            except Exception:
                pass
            try:
                for dirpath, _dirs, files in self._sc.walk(root, **self._ck):
                    for fn in files:
                        full = dirpath.rstrip("\\") + "\\" + fn
                        rel = full[len(base):].lstrip("\\").replace("\\", "/")
                        try:
                            size = self._sc.stat(full, **self._ck).st_size
                        except OSError:
                            size = 0
                        out[rel] = {"size": size}
            except self._smbexc.SMBOSError:
                return out
        return out

    def head(self, key):
        with self._lock:
            try:
                self._sc.stat(self._unc(key), **self._ck)
            except Exception:
                return None
            return self._meta_for(key)

    def _name_refused(self, exc):
        """True when the server said no to the NAME rather than to the write.

        Asked of the NT STATUS, not of the exception's class and not of its
        message. smbclient does not let the typed exception through: its raw
        IO layer catches SMBResponseException and re-raises SMBOSError(status,
        path), and STATUS_OBJECT_NAME_INVALID has no errno mapping there, so
        it arrives as errno 0 with the text "Unknown NtStatus error returned
        'STATUS_OBJECT_NAME_INVALID'". An isinstance check against
        ObjectNameInvalid looks right and never fires. Both spellings are
        accepted here, and the status is the thing actually compared.

        STATUS_OBJECT_NAME_INVALID / OBJECT_PATH_INVALID are what a server
        answers a CREATE with when the name cannot exist on the share.
        Everything else — no space, no permission, a dropped connection — is
        a real failure and stays one.
        """
        ns = self._smbexc.NtStatus
        status = getattr(exc, "ntstatus", None)
        if status is None:
            status = getattr(exc, "status", None)
        if status in (ns.STATUS_OBJECT_NAME_INVALID,
                      ns.STATUS_OBJECT_PATH_INVALID):
            return True
        return isinstance(exc, (self._smbexc.ObjectNameInvalid,
                                self._smbexc.ObjectPathInvalid))

    def upload(self, local_path, key, metadata):
        unc = self._unc(key)
        with self._lock:
            try:
                self._sc.makedirs(unc.rsplit("\\", 1)[0], exist_ok=True, **self._ck)
            except OSError:
                pass
            try:
                with open(local_path, "rb") as src, \
                        self._sc.open_file(unc, mode="wb", **self._ck) as dst:
                    for chunk in iter(lambda: src.read(1024 * 1024), b""):
                        dst.write(chunk)
            except Exception as e:                             # noqa: BLE001
                if self._name_refused(e):
                    raise ObjectNameRefused(
                        "the share cannot store this name (%s)"
                        % type(e).__name__)
                raise
            self._set_mtime(unc, metadata)

    def download(self, key, local_path):
        unc = self._unc(key)
        with self._lock:
            with self._sc.open_file(unc, mode="rb", **self._ck) as src, \
                    open(local_path, "wb") as dst:
                for chunk in iter(lambda: src.read(1024 * 1024), b""):
                    dst.write(chunk)
            return self._meta_for(key)

    def server_side_copy(self, src_key, dst_key, metadata):
        # smbprotocol's high-level API doesn't expose FSCTL_SRV_COPYCHUNK, so a
        # "server-side" copy relays bytes through the client over the same
        # session (correct, just not zero-copy).
        dst_unc = self._unc(dst_key)
        with self._lock:
            try:
                self._sc.makedirs(dst_unc.rsplit("\\", 1)[0], exist_ok=True,
                                  **self._ck)
            except OSError:
                pass
            try:
                with self._sc.open_file(self._unc(src_key), mode="rb",
                                        **self._ck) as s, \
                        self._sc.open_file(dst_unc, mode="wb", **self._ck) as d:
                    for chunk in iter(lambda: s.read(1024 * 1024), b""):
                        d.write(chunk)
            except Exception as e:                             # noqa: BLE001
                # A duplicate whose NAME the share cannot hold is refused for
                # exactly the reason a primary is; same answer, same word.
                if self._name_refused(e):
                    raise ObjectNameRefused(
                        "the share cannot store this name (%s)"
                        % type(e).__name__)
                raise
            self._set_mtime(dst_unc, metadata)

    def _set_mtime(self, unc, metadata):
        if metadata and metadata.get("fc_mtime"):
            try:
                t = float(metadata["fc_mtime"])
                self._sc.utime(unc, (t, t), **self._ck)
            except Exception:
                pass

    # ── Streaming-relay support (http(s):// source) ────────────────────
    # Handles are handed to a SINGLE-threaded relay loop, so using them
    # outside self._lock is safe — the lock exists to serialise the thread
    # -pool drivers, which never run concurrently with the relay.

    def stat_key(self, key):
        """os.stat_result for a key, or None if it doesn't exist."""
        with self._lock:
            try:
                return self._sc.stat(self._unc(key), **self._ck)
            except Exception:
                return None

    def open_write(self, key):
        """A write handle straight onto the share (parents created), so a
        relay can stream into it without touching the local disk."""
        unc = self._unc(key)
        with self._lock:
            try:
                self._sc.makedirs(unc.rsplit("\\", 1)[0], exist_ok=True,
                                  **self._ck)
            except OSError:
                pass
            return self._sc.open_file(unc, mode="wb", **self._ck)

    def open_read(self, key):
        # The returned reader HOLDS self._lock until closed: concurrent
        # operations on one SMB session corrupt data (see __init__), so a
        # parallel relay draining several open_read streams must serialise —
        # workers simply queue on the lock, per this backend's design.
        self._lock.acquire()
        try:
            st = self._sc.stat(self._unc(key), **self._ck)
            f = self._sc.open_file(self._unc(key), mode="rb", **self._ck)
        except Exception:
            self._lock.release()
            raise
        return _SMBLockedFile(f, self._lock), st.st_size, self._meta_for(key)

    def upload_stream(self, fileobj, key, metadata, size):
        # Entire write under the session lock — same serialisation rule.
        with self._lock:
            unc = self._unc(key)
            try:
                self._sc.makedirs(unc.rsplit("\\", 1)[0], exist_ok=True,
                                  **self._ck)
            except OSError:
                pass
            with self._sc.open_file(unc, mode="wb", **self._ck) as f:
                for chunk in iter(lambda: fileobj.read(1024 * 1024), b""):
                    f.write(chunk)
            self._set_mtime(unc, metadata)

    def set_key_mtime(self, key, mtime):
        with self._lock:
            try:
                self._sc.utime(self._unc(key), (mtime, mtime), **self._ck)
            except Exception:
                pass


def make_backend(spec, args):
    creds = resolve_connection(spec, args)
    cls = {"s3": S3Backend, "az": AzureBackend, "gs": GCSBackend,
           "smb": SMBBackend}[spec.scheme]
    return cls(spec, args, creds)


# ── creds manager:  blitcp creds add|list|remove|test ──────────────────
def _windows_clear_attrs(path):
    """Clear HIDDEN/READONLY/SYSTEM on an existing file so a rewrite can open it.
    On Windows, open(path,'wb') (CREATE_ALWAYS) FAILS with access-denied when the
    target is hidden — so we must strip the attribute before overwriting."""
    if _system != "Windows" or not os.path.exists(path):
        return
    try:
        import ctypes
        FILE_ATTRIBUTE_NORMAL = 0x80
        a = ctypes.windll.kernel32.GetFileAttributesW(path)
        if a != -1:
            cleared = a & ~0x1 & ~0x2 & ~0x4  # READONLY, HIDDEN, SYSTEM
            ctypes.windll.kernel32.SetFileAttributesW(
                path, cleared or FILE_ATTRIBUTE_NORMAL)
    except Exception:
        pass


def _entry_has_secret(c):
    """True if a connection entry holds a secret VALUE in cleartext (not a mere
    file-path reference). Used to warn before an unencrypted write. Note: an SSH
    'key' is a private-key file *path* (not a secret here), unlike an Azure
    'key' which is the account key itself."""
    t = c.get("type")
    if t == "s3":
        return bool(c.get("secret_access_key"))
    if t == "az":
        return bool(c.get("connection_string") or c.get("key"))
    if t == "ssh":
        return bool(c.get("password"))
    if t == "smb":
        return bool(c.get("password"))
    if t == "http":
        # The header line is a secret too — it typically IS the token.
        return bool(c.get("password") or c.get("header"))
    return False


def _save_credentials_file(path, conns, encrypt=False):
    """Write the connections file. encrypt=True → AES-256-GCM (prompts for the
    passphrase). Always 0600 + hidden.

    Auto-manages the immutable lock so a protected creds file stays protected
    without a manual unlock/lock dance: every mutating op (add/edit/remove/
    encrypt/decrypt/rekey) routes through here, so it transparently unlocks the
    file, rewrites it, then re-locks it — and a freshly created file is locked
    on first write. Best-effort, mirroring the audit log: where chattr/chflags
    is unavailable, the FS can't do it, or we lack root, it degrades silently —
    only warning if it had to remove protection it then couldn't restore.
    Read-only ops (list/test) don't come through here — an immutable file is
    still readable, so they need no unlock."""
    # The on-disk file is changing; drop any memoized decryption so a later read
    # in this same process sees the new contents (e.g. add → save → list).
    _creds_cache.clear()
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    if encrypt:
        blob = encrypt_conns(conns, _creds_passphrase(confirm=True))
    else:
        blob = json.dumps({"connections": conns}, indent=2).encode("utf-8")
        if any(isinstance(c, dict) and _entry_has_secret(c)
               for c in conns.values()):
            print(f"  {C.YELLOW}Warning: writing credentials UNENCRYPTED to "
                  f"{path} — passwords/keys are stored in cleartext, readable by "
                  f"anyone who can read the file. Encrypt with: "
                  f"blitcp creds encrypt{C.RESET}", file=sys.stderr)

    # Guard against a symlink before any chattr — set_immutable() follows
    # symlinks, so a planted link could otherwise redirect the lock elsewhere.
    try:
        _lst = os.lstat(path)
    except FileNotFoundError:
        _lst = None
    if _lst is not None and stat.S_ISLNK(_lst.st_mode):
        raise SystemExit(f"Error: refusing to write {path}: it is a symlink.")
    existed = _lst is not None
    # Was the file actually protected before we touched it? Check the real flag
    # (not the unlock return value — clearing an already-clear flag 'succeeds'
    # for any owner). This is the only case where failing to re-lock below is a
    # genuine regression worth warning about.
    was_immutable = _is_immutable(path) if existed else False
    if existed:
        unlocked, _ = set_immutable(path, on=False)  # unlock so the rewrite proceeds
        if was_immutable and not unlocked:
            # A non-root user can't clear the immutable flag, so the rewrite
            # below would fail with a cryptic EPERM and we'd point at
            # 'creds unlock' — which also needs root, looping the user. Fail
            # now with a command that actually works. The explicit path matters:
            # under sudo the default-path lookup resolves to root's home, not
            # this file.
            raise SystemExit(
                f"Error: {path} is immutable; clearing the lock needs root. "
                f"Run: sudo blitcp creds unlock {path}")

    _windows_clear_attrs(path)  # else overwriting a hidden file fails on Windows
    old = os.umask(0o077)  # owner-only from creation — no world-readable window
    _imm = (f"Error: cannot write {path} — it may be immutable or read-only. "
            f"Run: sudo blitcp creds unlock {path}")
    try:
        if hasattr(os, "O_NOFOLLOW"):
            # Refuse to write through a symlink (parity with the dedup DB), so a
            # planted symlink at the creds path can't redirect the write.
            try:
                fd = os.open(path, os.O_CREAT | os.O_WRONLY | os.O_TRUNC
                             | os.O_NOFOLLOW, 0o600)
            except OSError as e:
                if e.errno in (errno.ELOOP, errno.EMLINK):
                    raise SystemExit(f"Error: refusing to write {path}: it is a "
                                     f"symlink.")
                if isinstance(e, PermissionError):
                    raise SystemExit(_imm)
                raise
            with os.fdopen(fd, "wb") as f:
                f.write(blob)
        else:
            with open(path, "wb") as f:
                f.write(blob)
    except PermissionError:
        raise SystemExit(_imm)
    finally:
        os.umask(old)

    # Re-lock (or lock-on-first-write) so the file is immutable at rest. Quiet by
    # design: confirm on success, warn ONLY if we removed protection and then
    # couldn't restore it, and stay silent in the benign "can't lock here" case
    # (non-root or a FS without immutability, where nothing was protected).
    ok, msg = set_immutable(path, on=True)
    if ok:
        print(f"  {C.DIM}creds: {'locked' if not existed else 're-locked'} "
              f"(immutable){C.RESET}")
    elif was_immutable:
        print(f"  {C.YELLOW}creds: WARNING — {path} was immutable but could not "
              f"be re-locked ({msg or 'unknown error'}). Run 'sudo blitcp "
              f"creds lock' to restore protection.{C.RESET}", file=sys.stderr)
    if hasattr(os, "chmod"):
        try:
            os.chmod(path, 0o600)
        except OSError:
            pass
    _set_hidden(path)


def _file_is_encrypted(path):
    try:
        with open(path, "rb") as f:
            return _is_encrypted(f.read())
    except OSError:
        return False


def _mask(v):
    if not v:
        return ""
    return (v[:3] + "…") if len(v) > 6 else "***"


def _prompt_secret(prompt):
    """Read a secret from the terminal, echoing '*' per character so you get
    length feedback while typing without exposing the value (getpass shows
    nothing at all). Backspace erases the last character. Falls back to getpass
    (no echo) when stdin isn't a real TTY or the terminal can't be put into raw
    mode — so pipes, CI, and odd terminals keep working unchanged."""
    if not _stdin_is_tty():
        return getpass.getpass(prompt)
    try:
        if _system == "Windows":
            import msvcrt
            sys.stdout.write(prompt); sys.stdout.flush()
            buf = []
            while True:
                ch = msvcrt.getwch()
                if ch in ("\r", "\n"):
                    break
                if ch == "\x03":               # Ctrl-C
                    raise KeyboardInterrupt
                if ch in ("\x00", "\xe0"):     # function/arrow key: drop 2nd byte
                    msvcrt.getwch()
                elif ch == "\b":               # backspace
                    if buf:
                        buf.pop(); sys.stdout.write("\b \b")
                else:
                    buf.append(ch); sys.stdout.write("*")
                sys.stdout.flush()
            sys.stdout.write("\n"); sys.stdout.flush()
            return "".join(buf)
        import termios, tty
        fd = sys.stdin.fileno()
        old = termios.tcgetattr(fd)
        sys.stdout.write(prompt); sys.stdout.flush()
        buf = []
        try:
            tty.setraw(fd)
            while True:
                ch = sys.stdin.read(1)
                if ch in ("\r", "\n", ""):     # Enter or EOF ends input
                    break
                if ch == "\x03":               # raw mode delivers Ctrl-C as a byte
                    raise KeyboardInterrupt
                if ch in ("\x7f", "\b"):       # backspace / delete
                    if buf:
                        buf.pop(); sys.stdout.write("\b \b"); sys.stdout.flush()
                    continue
                buf.append(ch); sys.stdout.write("*"); sys.stdout.flush()
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
            sys.stdout.write("\n"); sys.stdout.flush()
        return "".join(buf)
    except KeyboardInterrupt:
        raise
    except Exception:
        # Any terminal-control hiccup → degrade to a plain no-echo prompt.
        return getpass.getpass(prompt)


# Zone-1 S3-compatible provider presets (CLOUD_PROVIDERS_DESIGN.md). They all
# ride the plain S3Backend — a preset only templates endpoint_url, prompts for
# the template's placeholders, and points at the provider's key console.
# name → (label, endpoint template, [placeholders], region default, key help)
KNOWN_S3_PROVIDERS = {
    "r2": ("Cloudflare R2",
           "https://{account}.r2.cloudflarestorage.com", ["account"], "auto",
           "dash.cloudflare.com → R2 → Manage R2 API Tokens"),
    "b2": ("Backblaze B2",
           "https://s3.{region}.backblazeb2.com", ["region"], None,
           "secure.backblaze.com → App Keys"),
    "wasabi": ("Wasabi",
               "https://s3.{region}.wasabisys.com", ["region"], None,
               "console.wasabisys.com → Access Keys"),
    "spaces": ("DigitalOcean Spaces",
               "https://{region}.digitaloceanspaces.com", ["region"], None,
               "cloud.digitalocean.com → API → Spaces Keys"),
    "scaleway": ("Scaleway Object Storage",
                 "https://s3.{region}.scw.cloud", ["region"], None,
                 "console.scaleway.com → IAM → API keys"),
    "hetzner": ("Hetzner Object Storage",
                "https://{region}.your-objectstorage.com", ["region"], None,
                "console.hetzner.cloud → Security → S3 credentials"),
    "idrive": ("IDrive e2",
               "{endpoint}", ["endpoint"], None,
               "app.idrivee2.com → Access Keys (endpoint is shown per region)"),
    "storj": ("Storj (S3 gateway)",
              "https://gateway.storjshare.io", [], None,
              "storj.io console → Access → Create S3 credentials"),
    "oracle": ("Oracle OCI Object Storage",
               "https://{namespace}.compat.objectstorage.{region}.oraclecloud.com",
               ["namespace", "region"], None,
               "OCI console → User Settings → Customer Secret Keys"),
}
_S3_PROVIDER_ALIASES = {
    "cloudflare": "r2", "backblaze": "b2", "digitalocean": "spaces",
    "do": "spaces", "oci": "oracle", "idrive-e2": "idrive", "e2": "idrive",
}


def creds_manager(argv):
    """Handle `blitcp creds <sub> [name] [path]`. Returns an exit code."""
    if not argv or argv[0] in ("-h", "--help", "help"):
        print("Usage: blitcp creds <sub> [NAME] [FILE]\n"
              "  list                       show connections (secrets masked)\n"
              "  add NAME [-y]              add a connection (s3/azure/gcs/ssh/smb/http\n"
              "                             or an S3-compatible provider preset:\n"
              "                             r2, b2, wasabi, spaces, scaleway,\n"
              "                             hetzner, idrive, storj, oracle;\n"
              "                             interactive; prompts before overwrite,\n"
              "                             -y/--force to skip)\n"
              "  edit NAME                  edit a connection (Enter keeps current,\n"
              "                             '-' clears an optional field)\n"
              "  remove NAME                delete a connection\n"
              "  test NAME                  live connection check (cloud or ssh)\n"
              "  encrypt | decrypt          toggle AES-256-GCM encryption at rest\n"
              "    encrypt --generate[=N]   offer a generated diceware passphrase\n"
              "                             (N words, default 6 ≈ 77 bits)\n"
              "  rekey                      re-bind an encrypted file to this binary\n"
              "  lock | unlock              set/clear OS immutability (needs root)\n"
              "  --use-sudo                 re-exec under sudo (e.g. for lock/\n"
              "                             unlock, which need root for chattr)\n"
              f"  Default file: {default_credentials_path()}\n"
              "  Passphrase: env BLITCP_CREDS_PASSPHRASE or a hidden prompt.\n"
              "  Note: on Linux, BLITCP_CREDS_PASSPHRASE is readable from\n"
              "  /proc/<pid>/environ by same-UID processes; prefer the hidden\n"
              "  prompt on shared/multi-user hosts.")
        return 0
    sub = argv[0]
    # Separate options from positionals so a flag (e.g. --use-sudo) is never
    # mistaken for the NAME or FILE positional. Only a small set of flags is
    # valid here; reject anything else instead of silently treating it as a path.
    opts = argv[1:]
    force = any(a in ("-y", "--yes", "--force") for a in opts)
    known = ("-y", "--yes", "--force", "--use-sudo", "--generate")
    gen_words = None                       # None = no --generate
    for a in opts:
        if a == "--generate":
            gen_words = 6
        elif a.startswith("--generate="):
            try:
                gen_words = int(a.split("=", 1)[1])
            except ValueError:
                print(f"{C.RED}Error: --generate=N needs a number of words "
                      f"(3-20).{C.RESET}", file=sys.stderr)
                return 2
    unknown = [a for a in opts if a.startswith("-") and a not in known
               and not a.startswith("--generate=")]
    if unknown:
        print(f"{C.RED}Error: unknown option for 'creds {sub}': "
              f"{' '.join(unknown)}. Valid flags: -y/--force, --use-sudo, "
              f"--generate[=N] (encrypt only). "
              f"NAME and FILE are positional.{C.RESET}", file=sys.stderr)
        return 2
    if gen_words is not None and sub != "encrypt":
        print(f"{C.RED}Error: --generate is only valid with "
              f"'creds encrypt'.{C.RESET}", file=sys.stderr)
        return 2
    positionals = [a for a in opts if not a.startswith("-")]
    # list/encrypt/decrypt/rekey/lock/unlock take only an optional FILE;
    # add/remove/test take NAME [FILE].
    if sub in ("list", "encrypt", "decrypt", "rekey", "lock", "unlock"):
        name = None
        path = positionals[0] if positionals else default_credentials_path()
    else:
        name = positionals[0] if positionals else None
        path = positionals[1] if len(positionals) > 1 else default_credentials_path()
    encrypted = _file_is_encrypted(path) if os.path.isfile(path) else False
    conns = load_credentials_file(path) if os.path.isfile(path) else {}

    if sub == "list":
        if not conns:
            print(f"  No connections in {path}")
            return 0
        print(f"  Connections in {path}:")
        for n, c in sorted(conns.items()):
            t = c.get("type", "?")
            if t == "s3":
                extra = f"endpoint={c.get('endpoint_url') or 'AWS'} key={_mask(c.get('access_key_id'))}"
            elif t == "az":
                extra = (f"conn={_mask(c.get('connection_string'))}"
                         if c.get("connection_string")
                         else f"account={c.get('account')} key={_mask(c.get('key'))}")
            elif t == "gs":
                extra = f"project={c.get('project')} creds={c.get('credentials') or 'ADC'}"
            elif t == "ssh":
                auth = (f"key={c.get('key')}" if c.get("key")
                        else "password=***" if c.get("password") else "agent")
                extra = f"{c.get('user')}@{c.get('host')}:{c.get('port', 22)} {auth}"
                if c.get("path"):
                    extra += f" path={c.get('path')}"
            elif t == "smb":
                dom = (c.get("domain") + "\\") if c.get("domain") else ""
                auth = "password=***" if c.get("password") else "anonymous"
                extra = (f"{dom}{c.get('user')}@{c.get('host')}:{c.get('port', 445)}"
                         f" {auth}")
                if c.get("share"):
                    extra += f" share={c.get('share')}"
            elif t == "http":
                auth = []
                if c.get("user"):
                    auth.append(f"{c.get('user')}"
                                + ("+password=***" if c.get("password") else ""))
                if c.get("header"):
                    auth.append("header=***")
                if c.get("cookies"):
                    auth.append(f"cookies={c.get('cookies')}")
                extra = f"host={c.get('host')} " + (" ".join(auth) or "no auth")
            else:
                extra = ""
            if t in ("s3", "az", "gs") and c.get("container"):
                extra += f" default={c.get('container')}"
                if c.get("prefix"):
                    extra += "/" + c.get("prefix").strip("/")
            print(f"    {C.BOLD}{n}{C.RESET}  [{t}]  {extra}")
        return 0

    if sub == "remove":
        if not name or name not in conns:
            print(f"{C.RED}Error: no connection named {name!r} in {path}{C.RESET}")
            return 1
        del conns[name]
        _save_credentials_file(path, conns, encrypt=encrypted)
        print(f"  Removed connection {name!r}.")
        return 0

    if sub == "add":
        if not name:
            print(f"{C.RED}Error: 'creds add' needs a connection name.{C.RESET}")
            return 1
        t = (input("  Type [s3/azure/gcs/ssh/smb/http — or a preset: "
                   + "/".join(KNOWN_S3_PROVIDERS) + "]: ").strip() or "s3").lower()
        t = _S3_PROVIDER_ALIASES.get(t, t)
        preset = KNOWN_S3_PROVIDERS.get(t)
        if preset:
            label, template, placeholders, region_default, key_help = preset
            print(f"  {label} — S3-compatible. Keys: {key_help}")
            entry = {"type": "s3", "preset": t}
            values = {}
            for ph in placeholders:
                v = input(f"  {ph.capitalize()}: ").strip()
                if not v:
                    print(f"{C.RED}Error: {label} needs the {ph}.{C.RESET}")
                    return 1
                values[ph] = v
            entry["endpoint_url"] = template.format(**values)
            print(f"  Endpoint: {entry['endpoint_url']}")
            entry["access_key_id"] = input("  Access key ID: ").strip()
            entry["secret_access_key"] = _prompt_secret("  Secret access key: ")
            if region_default:
                entry["region"] = region_default
            elif values.get("region"):
                entry["region"] = values["region"]
            t = "s3"   # the shared default-bucket prompt below applies too
        else:
            t = {"azure": "az", "gcs": "gs", "s3": "s3", "az": "az", "gs": "gs",
                 "ssh": "ssh", "sftp": "ssh", "smb": "smb", "cifs": "smb",
                 "http": "http", "https": "http"}.get(t)
            if t not in ("s3", "az", "gs", "ssh", "smb", "http"):
                print(f"{C.RED}Error: type must be s3, azure, gcs, ssh, smb, "
                      f"http, or a provider preset "
                      f"({'/'.join(KNOWN_S3_PROVIDERS)}).{C.RESET}")
                return 1
            entry = {"type": t}
        if preset:
            pass
        elif t == "s3":
            ep = input("  Endpoint URL (blank = AWS): ").strip()
            if ep:
                entry["endpoint_url"] = ep
            entry["access_key_id"] = input("  Access key ID: ").strip()
            entry["secret_access_key"] = _prompt_secret("  Secret access key: ")
            region = input("  Region [us-east-1]: ").strip()
            if region:
                entry["region"] = region
        elif t == "az":
            cs = _prompt_secret("  Connection string (blank to use account+key): ")
            if cs:
                entry["connection_string"] = cs
            else:
                entry["account"] = input("  Account name: ").strip()
                entry["key"] = _prompt_secret("  Account key: ")
        elif t == "gs":
            entry["project"] = input("  GCP project id: ").strip()
            cp = input("  Service-account JSON path (blank = ADC): ").strip()
            if cp:
                entry["credentials"] = cp
        elif t == "ssh":
            entry["host"] = input("  Host (name or IP): ").strip()
            if not entry["host"]:
                print(f"{C.RED}Error: SSH connection needs a host.{C.RESET}")
                return 1
            u = input(f"  User [{getpass.getuser()}]: ").strip()
            entry["user"] = u or getpass.getuser()
            p = input("  Port [22]: ").strip()
            if p:
                try:
                    entry["port"] = int(p)
                except ValueError:
                    print(f"{C.RED}Error: port must be a number.{C.RESET}")
                    return 1
            key = input("  Private key path (blank for password/agent): ").strip()
            if key:
                entry["key"] = key
            else:
                pw = _prompt_secret("  Password (blank = use SSH agent/keys): ")
                if pw:
                    entry["password"] = pw
            dp = input("  Default remote path (blank = none): ").strip()
            if dp:
                entry["path"] = dp
            proto = input("  Protocol [ssh/sftp/both] (blank = both): ").strip().lower()
            if proto and proto not in SSH_PROTOCOLS:
                print(f"{C.RED}Error: protocol must be one of "
                      f"{', '.join(SSH_PROTOCOLS)}.{C.RESET}")
                return 1
            entry["protocol"] = proto or "both"
        elif t == "smb":
            entry["host"] = input("  Host (name or IP): ").strip()
            if not entry["host"]:
                print(f"{C.RED}Error: SMB connection needs a host.{C.RESET}")
                return 1
            u = input(f"  User [{getpass.getuser()}]: ").strip()
            entry["user"] = u or getpass.getuser()
            pw = _prompt_secret("  Password (blank = anonymous/guest): ")
            if pw:
                entry["password"] = pw
            dom = input("  Domain (blank = none): ").strip()
            if dom:
                entry["domain"] = dom
            p = input("  Port [445]: ").strip()
            if p:
                try:
                    entry["port"] = int(p)
                except ValueError:
                    print(f"{C.RED}Error: port must be a number.{C.RESET}")
                    return 1
            sh = input("  Default share (blank = none): ").strip()
            if sh:
                entry["share"] = sh
        elif t == "http":
            # Matched by HOST: any http(s):// source URL on this host picks
            # these credentials up automatically (like SSH's match-by-host).
            entry["host"] = input("  Host (as it appears in the URL): ").strip()
            if not entry["host"]:
                print(f"{C.RED}Error: HTTP connection needs a host.{C.RESET}")
                return 1
            u = input("  User (blank = none, e.g. token-only auth): ").strip()
            if u:
                entry["user"] = u
                pw = _prompt_secret("  Password: ")
                if pw:
                    entry["password"] = pw
            h = _prompt_secret(
                "  Extra header (blank = none, e.g. Authorization: Bearer …): ")
            if h:
                if ":" not in h:
                    print(f"{C.RED}Error: header must be 'Name: value'.{C.RESET}")
                    return 1
                entry["header"] = h
            ck = input("  Cookies (blank = none; a cookies.txt path, or a "
                       "browser name\n    like 'chrome'/'firefox' to reuse a "
                       "login you already have): ").strip()
            if ck:
                entry["cookies"] = ck
        if t in ("s3", "az", "gs"):
            # A default bucket/container lets you copy to just `name` (no URL).
            cword = "container" if t == "az" else "bucket"
            dc = input(f"  Default {cword} (blank = none): ").strip()
            if dc:
                entry["container"] = dc
                pf = input("  Default prefix inside it (blank = none): ").strip()
                if pf:
                    entry["prefix"] = pf
        # Guard against silently clobbering an existing connection of the same
        # name (the classic "second profile overwrote my first" surprise).
        if name in conns and not force:
            if not _stdin_is_tty():
                print(f"{C.RED}Error: connection {name!r} already exists. "
                      f"Pass --force to overwrite.{C.RESET}")
                return 1
            ex = conns[name].get("type", "?")
            ans = input(f"  {C.YELLOW}Connection {name!r} already exists "
                        f"(type={ex}). Overwrite? [y/N]: {C.RESET}").strip().lower()
            if ans not in ("y", "yes"):
                print("  Aborted — existing connection kept.")
                return 0
        # First time this file is created → offer encryption up front, so
        # secrets aren't written in plaintext by default. Existing files keep
        # whatever state they already have.
        if not os.path.isfile(path):
            if _have_creds_passphrase():
                encrypted = True  # a passphrase is already provided → encrypt
            else:
                ans = input("  Encrypt this new credentials file with a "
                            "passphrase? [Y/n]: ").strip().lower()
                encrypted = ans in ("", "y", "yes")
        conns[name] = entry
        _save_credentials_file(path, conns, encrypt=encrypted)  # prompts if encrypting
        enc_note = ", encrypted" if encrypted else ""
        print(f"  {C.GREEN}✓ Saved connection {name!r} to {path} "
              f"({_perms_note(path)}{enc_note}){C.RESET}")
        return 0

    if sub == "edit":
        if not name or name not in conns:
            print(f"{C.RED}Error: no connection named {name!r} in {path}{C.RESET}")
            return 1
        if not _stdin_is_tty():
            print(f"{C.RED}Error: 'creds edit' is interactive; run it in a "
                  f"terminal (or use 'creds add {name} --force').{C.RESET}")
            return 1
        cur = conns[name]
        t = cur.get("type")
        print(f"  Editing {name!r} (type={t}). Enter = keep current; type a new "
              f"value to change; '-' to clear an optional field.")

        def ask(label, current, secret=False):
            if secret:
                shown = "set" if current else "unset"
                v = getpass.getpass(f"  {label} [{shown}]: ")
            else:
                v = input(f"  {label} [{current if current not in (None, '') else '—'}]: ").strip()
            if v == "":
                return current      # keep
            if v == "-":
                return None         # clear
            return v

        entry = {"type": t}

        def setif(k, v):
            if v not in (None, ""):
                entry[k] = v

        if t == "s3":
            setif("endpoint_url", ask("Endpoint URL (blank=AWS)", cur.get("endpoint_url")))
            setif("access_key_id", ask("Access key ID", cur.get("access_key_id")))
            setif("secret_access_key", ask("Secret access key", cur.get("secret_access_key"), secret=True))
            setif("region", ask("Region", cur.get("region")))
        elif t == "az":
            cs = ask("Connection string", cur.get("connection_string"), secret=True)
            if cs:
                setif("connection_string", cs)
            else:
                setif("account", ask("Account name", cur.get("account")))
                setif("key", ask("Account key", cur.get("key"), secret=True))
        elif t == "gs":
            setif("project", ask("GCP project id", cur.get("project")))
            setif("credentials", ask("Service-account JSON path (blank=ADC)", cur.get("credentials")))
        elif t == "ssh":
            setif("host", ask("Host", cur.get("host")))
            setif("user", ask("User", cur.get("user")))
            port = ask("Port", cur.get("port", 22))
            if port not in (None, ""):
                try:
                    entry["port"] = int(port)
                except (ValueError, TypeError):
                    print(f"{C.RED}Error: port must be a number.{C.RESET}")
                    return 1
            setif("key", ask("Private key path", cur.get("key")))
            setif("password", ask("Password", cur.get("password"), secret=True))
            setif("path", ask("Default remote path", cur.get("path")))
            proto = ask("Protocol (ssh/sftp/both)", cur.get("protocol"))
            if proto not in (None, ""):
                proto = str(proto).strip().lower()
                if proto not in SSH_PROTOCOLS:
                    print(f"{C.RED}Error: protocol must be one of "
                          f"{', '.join(SSH_PROTOCOLS)}.{C.RESET}")
                    return 1
                entry["protocol"] = proto
        elif t == "smb":
            setif("host", ask("Host", cur.get("host")))
            setif("user", ask("User", cur.get("user")))
            setif("password", ask("Password", cur.get("password"), secret=True))
            setif("domain", ask("Domain", cur.get("domain")))
            port = ask("Port", cur.get("port", 445))
            if port not in (None, ""):
                try:
                    entry["port"] = int(port)
                except (ValueError, TypeError):
                    print(f"{C.RED}Error: port must be a number.{C.RESET}")
                    return 1
            setif("share", ask("Default share", cur.get("share")))
        else:
            print(f"{C.RED}Error: connection {name!r} has an unknown type {t!r}.{C.RESET}")
            return 1

        if t in ("s3", "az", "gs"):
            cword = "container" if t == "az" else "bucket"
            setif("container", ask(f"Default {cword}", cur.get("container")))
            if entry.get("container"):
                setif("prefix", ask("Default prefix inside it", cur.get("prefix")))

        conns[name] = entry
        _save_credentials_file(path, conns, encrypt=encrypted)
        enc_note = ", encrypted" if encrypted else ""
        print(f"  {C.GREEN}✓ Updated connection {name!r} in {path} "
              f"({_perms_note(path)}{enc_note}){C.RESET}")
        return 0

    if sub == "test":
        if not name or name not in conns:
            print(f"{C.RED}Error: no connection named {name!r} in {path}{C.RESET}")
            return 1
        scheme = conns[name].get("type")
        if scheme == "ssh":
            c = conns[name]
            spec = RemoteSpec(user=c.get("user") or getpass.getuser(),
                              host=c.get("host"), port=int(c.get("port", 22)),
                              path=c.get("path", ""))
            ssh = None
            _sftp_conn = (c.get("protocol") == "sftp")
            try:
                ssh = SSHConnection(spec, port=spec.port, key_path=c.get("key"),
                                    password=c.get("password"),
                                    sftp_only=_sftp_conn).connect()
                if _sftp_conn:
                    ssh.open_sftp().stat(c.get("path") or ".")
                else:
                    ssh.exec_cmd("true")
            except Exception as e:
                print(f"  {C.RED}✗ {name}: connection failed — {e}{C.RESET}")
                return 1
            finally:
                if ssh:
                    try:
                        ssh.close()
                    except Exception:
                        pass
            print(f"  {C.GREEN}✓ {name}: SSH connection OK "
                  f"({spec.user}@{spec.host}:{spec.port}){C.RESET}")
            return 0
        if scheme == "smb":
            c = conns[name]
            spec = SMBSpec(scheme="smb", container=(c.get("share") or ""),
                           prefix="", connection=name, host=c.get("host"),
                           port=int(c.get("port", 445)), user=c.get("user"))
            try:
                b = make_backend(spec, argparse.Namespace(credentials_file=path))
                if c.get("share"):
                    b.list_objects("")
            except SystemExit:
                raise
            except Exception as e:
                print(f"  {C.RED}✗ {name}: connection failed — {e}{C.RESET}")
                return 1
            print(f"  {C.GREEN}✓ {name}: SMB connection OK "
                  f"({c.get('user')}@{c.get('host')}:{c.get('port', 445)}){C.RESET}")
            return 0
        if scheme == "http":
            c = conns[name]
            probe = argparse.Namespace(credentials_file=path, http_user=None,
                                       http_password=False,
                                       http_password_env=None, http_header=None)
            ch = c.get("host") or ""
            probe_url = ch if "://" in ch else f"https://{ch}/"
            try:
                url, hdrs = _http_resolve_auth(probe, probe_url)
                resp, _t, _m, _r = _http_open(url, headers=hdrs)
                code = resp.getcode()
                resp.close()
            except Exception as e:
                msg = str(e).strip().splitlines()[0] if str(e).strip() else e
                print(f"  {C.RED}✗ {name}: request failed — {msg}{C.RESET}")
                return 1
            print(f"  {C.GREEN}✓ {name}: HTTP {code} from "
                  f"{c.get('host')} (auth sent){C.RESET}")
            return 0
        if scheme not in ("s3", "az", "gs"):
            print(f"{C.RED}Error: connection {name!r} has no valid type.{C.RESET}")
            return 1
        probe_args = argparse.Namespace(credentials_file=path)
        spec = CloudSpec(scheme=scheme, container="_fc_probe_", prefix="",
                         connection=name)
        try:
            b = make_backend(spec, probe_args)
            if scheme == "s3":
                b.client.list_buckets()
            elif scheme == "az":
                b.service.get_service_properties()
            elif scheme == "gs":
                next(iter(b.client.list_buckets(page_size=1)), None)
        except SystemExit:
            raise
        except Exception as e:
            print(f"  {C.RED}✗ {name}: connection failed — {e}{C.RESET}")
            return 1
        print(f"  {C.GREEN}✓ {name}: connection OK{C.RESET}")
        return 0

    if sub == "encrypt":
        if not os.path.isfile(path):
            print(f"{C.RED}Error: no credentials file at {path}{C.RESET}")
            return 1
        if encrypted:
            print(f"  {path} is already encrypted.")
            return 0
        if gen_words is not None:
            if not _stdin_is_tty():
                print(f"{C.RED}Error: --generate needs a terminal (the "
                      f"passphrase is shown once and confirmed).{C.RESET}",
                      file=sys.stderr)
                return 2
            phrase, bits = generate_passphrase(gen_words)
            print(f"\n  Generated passphrase ({bits} bits of entropy):\n")
            print(f"      {C.BOLD}{phrase}{C.RESET}\n")
            print(f"  {C.YELLOW}Store it in your password manager NOW — it is "
                  f"shown only this once and\n  cannot be recovered.{C.RESET}")
            try:
                ans = input("  Use this passphrase? [Y/n] ").strip().lower()
            except (EOFError, KeyboardInterrupt):
                print()
                return 1
            if ans in ("", "y", "yes"):
                _set_creds_passphrase(phrase)
            else:
                print("  Not used — you will be prompted for your own.")
        _save_credentials_file(path, conns, encrypt=True)  # prompts (confirm)
        print(f"  {C.GREEN}✓ Encrypted {path} (AES-256-GCM, bound to this "
              f"blitcp).{C.RESET}")
        return 0

    if sub == "decrypt":
        if not encrypted:
            print(f"  {path} is not encrypted.")
            return 0
        _save_credentials_file(path, conns, encrypt=False)  # conns already decrypted
        print(f"  {C.GREEN}✓ Decrypted {path} (now plaintext, 0600).{C.RESET}")
        return 0

    if sub == "rekey":
        if not encrypted:
            print(f"{C.RED}Error: {path} is not encrypted; nothing to rekey.{C.RESET}")
            return 1
        _save_credentials_file(path, conns, encrypt=True)  # re-binds to current hash
        print(f"  {C.GREEN}✓ Re-bound {path} to this blitcp.{C.RESET}")
        return 0

    if sub in ("lock", "unlock"):
        if not os.path.isfile(path):
            print(f"{C.RED}Error: no credentials file at {path}{C.RESET}")
            return 1
        want = (sub == "lock")
        state = "immutable" if want else "writable"
        # Short-circuit if it's already in the requested state — avoids a
        # misleading "✓ now writable" on a file that was never locked, and a
        # needless (possibly failing) chattr on an already-locked one.
        if _is_immutable(path) == want:
            print(f"  {C.DIM}{path} is already {state}; nothing to do.{C.RESET}")
            return 0
        ok, msg = set_immutable(path, on=want)
        if ok:
            print(f"  {C.GREEN}✓ {path} is now {state}.{C.RESET}")
            if want:
                print(f"  {C.DIM}Note: tamper-resistance only — root can reverse "
                      f"it. Run 'creds unlock' before editing.{C.RESET}")
            return 0
        print(f"  {C.RED}✗ could not {sub}: {msg}{C.RESET}")
        return 1

    print(f"{C.RED}Error: unknown creds subcommand {sub!r}{C.RESET}")
    return 1


def _cloud_hash_entries(entries, threads):
    """Hash a list of FileEntry locally (parallel). Returns {rel: hash}."""
    import concurrent.futures
    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, threads)) as ex:
        futs = {ex.submit(hash_file, e.src): e for e in entries}
        for fut in concurrent.futures.as_completed(futs):
            e = futs[fut]
            try:
                results[e.rel] = fut.result()
            except Exception:
                results[e.rel] = None
    return results


def run_cloud_transfer(args):
    """Top-level driver for any transfer where the source or destination is an
    object-storage URL. Handles upload, download, and cloud-to-cloud."""
    if getattr(args, "extra_sources", None):
        print(f"{C.RED}Error: object-storage transfers take a single source "
              f"(got {len(args.extra_sources) + 1}). Point one source at a "
              f"common parent, or run separate copies.{C.RESET}")
        sys.exit(1)
    src_spec = _object_spec(args.source, args)
    dst_spec = _object_spec(args.destination, args)
    # One object side + one SSH side → relay through a local temp dir.
    if src_spec and not dst_spec and parse_remote_path(args.destination):
        return _relay_object_ssh(args, src_spec, obj_is_src=True)
    if dst_spec and not src_spec and parse_remote_path(args.source):
        return _relay_object_ssh(args, dst_spec, obj_is_src=False)
    if src_spec and dst_spec:
        return _cloud_to_cloud(args, src_spec, dst_spec)
    if dst_spec:
        return _upload_to_cloud(args, dst_spec)
    return _download_from_cloud(args, src_spec)


def _relay_object_ssh(args, obj_spec, obj_is_src):
    """Relay between an object endpoint (cloud/SMB) and an SSH endpoint by
    STREAMING each file through this machine — 1 MB chunks straight onto the
    far handle (object→SSH), or through a bounded per-object spool when the
    destination is a cloud store (SSH→cloud). Nothing dataset-sized ever
    lands on the local disk (CLOUD_RELAY_DESIGN.md §9, implemented)."""
    if not _load_paramiko():
        print(f"{C.RED}Error: SSH transfers require paramiko.{C.RESET}")
        sys.exit(1)
    try:
        rc = (_object_to_ssh_stream(args, obj_spec) if obj_is_src
              else _ssh_to_object_stream(args, obj_spec))
    except SystemExit:
        raise
    except Exception as e:
        msg = _fmt_exc(e)
        print(f"\n{C.RED}Error: {msg}{C.RESET}")
        rc = 1
    if rc:
        sys.exit(rc)


def _object_to_ssh_stream(args, obj_spec):
    """cloud/SMB → SSH: per file, open_read → pipelined SFTP write, 1 MB
    in-memory chunks (the R2R relay shape). Verify hashes the stream with an
    algorithm the destination can recompute — no re-download."""
    start = time.time()
    backend = make_backend(obj_spec, args)
    pretty = CLOUD_SCHEME_NAMES[obj_spec.scheme]
    dst_remote = parse_remote_path(args.destination)._replace(port=args.ssh_port)
    pw = _resolved_dst_pw(args)
    if not pw and getattr(args, "ssh_password", False):
        pw = getpass.getpass(
            f"Password for {dst_remote.user}@{dst_remote.host}: ")
    cli = _tar_ssh_connect(dst_remote, args.ssh_key, pw, args.compress)
    try:
        sftp = cli.open_sftp()
        dst_root = dst_remote.path.rstrip("/") or "/"
        banner(f"{pretty} → SSH  [streaming relay]")
        print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{args.source}{C.RESET}")
        print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dst_remote.user}@"
              f"{dst_remote.host}:{dst_root}{C.RESET}")

        objects = {k: v for k, v in backend.list_objects(obj_spec.prefix).items()
                   if not k.endswith((CLOUD_MANIFEST_NAME,
                                      LEGACY_CLOUD_MANIFEST_NAME))}
        if not objects:
            print(f"  {C.YELLOW}No objects found under that prefix.{C.RESET}")
            return 0
        sp = obj_spec.prefix.rstrip("/")
        src_manifest = {} if args.no_cache \
            else _load_cloud_manifest(backend, obj_spec.prefix)

        caps = None
        try:
            caps = _ssh_exec_caps(cli, dst_root)
        except Exception:
            caps = None
        halgo = caps["halgo"] if (caps and caps.get("halgo")) else None

        plan = []   # (key, rel, size)
        errors = 0
        for key, info in sorted(objects.items()):
            rel = key[len(sp):].lstrip("/") if sp and key.startswith(sp) else key
            rel = rel.lstrip("/") or key.rsplit("/", 1)[-1]
            if _unsafe_rel(rel):
                errors += 1
                print(f"  {C.RED}Skipping unsafe key: {key}{C.RESET}")
                continue
            if _rel_excluded(rel, args.exclude):
                continue
            plan.append((key, rel, info["size"]))

        # Incremental skip — only when it can be PROVEN: same size on the
        # destination AND the source-manifest hash matches a remotely computed
        # destination hash (one batched exec). No hash available → copy.
        skip = set()
        if (not args.overwrite and src_manifest and caps and caps.get("hash")
                and caps.get("halgo") == _hash_name):
            try:
                dmap = _ssh_remote_listing(cli, dst_root, caps)
            except Exception:
                dmap = {}
            cand = [rel for (_k, rel, size) in plan
                    if dmap.get(rel, (None,))[0] == size
                    and (src_manifest.get(rel) or {}).get("hash")]
            if cand:
                rh = _ssh_remote_hashes(cli, dst_root, cand, caps)
                skip = {rel for rel in cand
                        if rh.get(rel) == src_manifest[rel]["hash"]}
        total_bytes = sum(s for _k, _r, s in plan)
        todo = [(k, r, s) for (k, r, s) in plan if r not in skip]
        print(f"  Objects: {C.BOLD}{len(plan)}{C.RESET} "
              f"({fmt_size(total_bytes)})  ·  copy {len(todo)}, "
              f"skip {len(skip)}")
        if args.dry_run:
            print(f"  {C.YELLOW}(dry run — nothing relayed){C.RESET}")
            return 0

        prog = Progress(total_bytes, len(plan))
        if skip:
            prog.update(sum(s for _k, r, s in plan if r in skip), len(skip))
            prog.display()
        made_dirs = set()
        digests = {}
        copied = 0
        bytes_streamed = 0
        for key, rel, size in todo:
            tgt = posixpath.join(dst_root, rel)
            try:
                parent = posixpath.dirname(tgt) or "/"
                if parent not in made_dirs:
                    _sftp_mkdir_p(sftp, parent)
                    made_dirs.add(parent)
                fin, _sz, smeta = backend.open_read(key)
                h = _relay_hasher(halgo)
                n = 0
                fout = sftp.open(tgt, "wb")
                fout.set_pipelined(True)
                try:
                    while True:
                        data = fin.read(RELAY_CHUNK)
                        if not data:
                            break
                        fout.write(data)
                        if h is not None:
                            h.update(data)
                        n += len(data)
                        prog.update(len(data))
                        prog.display()
                finally:
                    fout.close()
                    try:
                        fin.close()
                    except Exception:
                        pass
                # Source-corruption gate: stream vs source manifest (same algo).
                want = (src_manifest.get(rel) or {}).get("hash")
                if (want and h is not None and halgo == _hash_name
                        and h.hexdigest() != want):
                    raise RuntimeError("source bytes do not match the source "
                                       "manifest hash — refusing to propagate")
                if smeta.get("fc_mtime"):
                    try:
                        t = float(smeta["fc_mtime"])
                        sftp.utime(tgt, (t, t))
                    except (ValueError, IOError):
                        pass
                if h is not None:
                    digests[rel] = h.hexdigest()
                copied += 1
                bytes_streamed += n
                _log("copied", rel, n, method="stream_relay")
                prog.update(0, 1)
                prog.display()
            except Exception as ex:
                msg = str(ex).strip().splitlines()[0] if str(ex).strip() \
                    else ex.__class__.__name__
                errors += 1
                print(f"\n  {C.RED}Error relaying {rel}: {msg}{C.RESET}")
                _log("error", rel, size, error=msg)
                prog.update(0, 1)
                prog.display()
        prog.finish()

        vfail = 0
        if not args.no_verify and digests and caps and caps.get("hash"):
            print("  " + C.DIM
                  + f"Verifying {len(digests)} files on the destination..."
                  + C.RESET)
            rh = _ssh_remote_hashes(cli, dst_root, sorted(digests), caps)
            for rel, dgs in sorted(digests.items()):
                if rh.get(rel) != dgs:
                    vfail += 1
                    print(f"  {C.RED}VERIFY MISMATCH: {rel}{C.RESET}")
            if not vfail:
                print(f"  {C.GREEN}✓ Verified {len(digests)} file(s){C.RESET}")

        banner("DONE")
        print(f"  Copied:  {C.BOLD}{copied}{C.RESET} "
              f"({fmt_size(bytes_streamed)})  "
              f"{C.DIM}streamed — no local temp{C.RESET}")
        if skip:
            print(f"  Skipped: {C.BOLD}{len(skip)}{C.RESET} unchanged")
        if errors or vfail:
            print(f"  {C.RED}Errors:  {errors + vfail}{C.RESET}")
        if args.log_file:
            write_log_file(args.log_file, {
                "source": args.source, "destination": args.destination,
                "mode": f"relay_{backend.scheme}_ssh",
                "total_files": len(plan), "copied": copied, "linked": 0,
                "skipped": len(skip), "errors": errors + vfail,
                "total_bytes": total_bytes, "bytes_written": bytes_streamed,
                "dedup_saved": 0, "hash_algo": halgo or "none",
            })
        return 1 if (errors or vfail) else 0
    finally:
        cli.close()


def _ssh_to_object_stream(args, obj_spec):
    """SSH → cloud/SMB: per file, SFTP read → bounded spool → upload_stream
    (SMB destinations stream straight onto the share, no spool). Dedup and
    incremental skip ride the remote hash tool + destination manifest."""
    import tempfile
    start = time.time()
    src_remote = parse_remote_path(args.source)._replace(port=args.src_port)
    pw = _resolved_src_pw(args)
    if not pw and getattr(args, "src_password", False):
        pw = getpass.getpass(
            f"Password for {src_remote.user}@{src_remote.host}: ")
    cli = _tar_ssh_connect(src_remote, args.src_key, pw, args.compress)
    backend = make_backend(obj_spec, args)
    pretty = CLOUD_SCHEME_NAMES[obj_spec.scheme]
    spool_dir = None
    try:
        sftp = cli.open_sftp()
        src_root = src_remote.path.rstrip("/") or "/"
        banner(f"SSH → {pretty}  [streaming relay]")
        print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{src_remote.user}@"
              f"{src_remote.host}:{src_root}{C.RESET}")
        print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{args.destination}{C.RESET}")

        caps = None
        try:
            caps = _ssh_exec_caps(cli, "/tmp")
        except Exception:
            caps = None
        smap = {}
        try:
            if caps:
                smap = _ssh_remote_listing(cli, src_root, caps)
        except Exception:
            smap = {}
        if not smap:
            smap = {r: (s, 0.0)
                    for r, s in _sftp_walk_files(sftp, src_root).items()}
        files = [(r, sz, mt) for r, (sz, mt) in sorted(smap.items())
                 if not _rel_excluded(r, args.exclude)]
        if not files:
            print(f"{C.RED}Error: nothing to copy at "
                  f"{src_remote.host}:{src_root}.{C.RESET}")
            return 1

        dst_manifest = {} if args.no_cache \
            else _load_cloud_manifest(backend, obj_spec.prefix)
        dp = obj_spec.prefix.rstrip("/")
        dst_sizes = {}
        for k, v in backend.list_objects(obj_spec.prefix).items():
            if k.endswith((CLOUD_MANIFEST_NAME, LEGACY_CLOUD_MANIFEST_NAME)):
                continue
            r = k[len(dp):].lstrip("/") if dp and k.startswith(dp) else k
            dst_sizes[r] = v["size"]

        # One batched remote-hash pass powers skip + dedup + the corruption
        # gate — only when the remote tool matches the local algorithm.
        src_hashes = {}
        if (caps and caps.get("hash") and caps.get("halgo") == _hash_name
                and not (args.no_dedup and args.no_verify)):
            print("  " + C.DIM + _tr("Hashing {n} files...")
                  .format(n=len(files)) + C.RESET)
            src_hashes = _ssh_remote_hashes(
                cli, src_root, [r for r, _s, _m in files], caps)

        new_manifest = {}
        primaries = []   # (rel, key, size, want_hash, mtime)
        dups = []        # (rel, primary_key, key, size, hash)
        skipped = 0
        skip_bytes = 0
        first_key_for_hash = {}
        total_bytes = sum(sz for _r, sz, _m in files)
        for r, sz, mt in files:
            key = backend.join_key(obj_spec.prefix, r)
            h = src_hashes.get(r)
            prev = dst_manifest.get(r)
            if (not args.overwrite and h and prev and prev.get("hash") == h
                    and dst_sizes.get(r) == sz):
                skipped += 1
                skip_bytes += sz
                new_manifest[r] = {"size": sz, "hash": h}
                continue
            if h and not args.no_dedup and h in first_key_for_hash:
                dups.append((r, first_key_for_hash[h], key, sz, h))
            else:
                primaries.append((r, key, sz, h, mt))
                if h and not args.no_dedup:
                    first_key_for_hash[h] = key
        print(f"  Files: {C.BOLD}{len(files)}{C.RESET} "
              f"({fmt_size(total_bytes)})  ·  relay {len(primaries)}, "
              f"dedup {len(dups)}, skip {skipped}")
        if args.dry_run:
            print(f"  {C.YELLOW}(dry run — nothing relayed){C.RESET}")
            return 0

        prog = Progress(total_bytes, len(files))
        if skipped:
            prog.update(skip_bytes, skipped)
            prog.display()
        spool_mb = getattr(args, "relay_spool_mb", 64)
        spool_dir = tempfile.mkdtemp(prefix="blitcp_spool_")
        copied = deduped = errors = 0
        bytes_up = bytes_deduped = 0
        for r, key, sz, want, mt in primaries:      # serial: one SFTP session
            try:
                fin = sftp.open(posixpath.join(src_root, r), "rb")
                fin.prefetch(min(sz, 256 * 1024 * 1024))
                if backend.scheme == "smb":
                    # SMB write handle streams directly — no spool needed.
                    h = _relay_hasher(_hash_name)
                    n = 0
                    fout = backend.open_write(key)
                    try:
                        while True:
                            data = fin.read(RELAY_CHUNK)
                            if not data:
                                break
                            fout.write(data)
                            h.update(data)
                            n += len(data)
                            prog.update(len(data))
                            prog.display()
                    finally:
                        fout.close()
                        fin.close()
                    digest = h.hexdigest()
                    if mt:
                        backend.set_key_mtime(key, mt)
                    prog.update(0, 1)
                else:
                    try:
                        spool, n, digest = _spool_from_stream(
                            fin, spool_mb, spool_dir, _hash_name, prog)
                    finally:
                        fin.close()
                    meta = {"fc_relpath": _quote_rel(r),
                            "fc_hash": digest or "",
                            "fc_hash_algo": _hash_name}
                    if mt:
                        meta["fc_mtime"] = repr(mt)
                    try:
                        backend.upload_stream(spool, key, meta, n)
                    finally:
                        spool.close()
                    prog.update(sz - sz // 2, 1)
                prog.display()
                if want and digest and want != digest:
                    raise RuntimeError(
                        "source changed while streaming (hash mismatch)")
                new_manifest[r] = {"size": n, "hash": digest}
                copied += 1
                bytes_up += n
                _log("copied", r, n, method="stream_relay")
            except Exception as ex:
                msg = str(ex).strip().splitlines()[0] if str(ex).strip() \
                    else ex.__class__.__name__
                errors += 1
                print(f"\n  {C.RED}Error relaying {r}: {msg}{C.RESET}")
                _log("error", r, sz, error=msg)
                prog.update(0, 1)
                prog.display()
        for r, pkey, key, sz, h in dups:
            try:
                meta = {"fc_relpath": _quote_rel(r), "fc_hash": h,
                        "fc_hash_algo": _hash_name}
                backend.server_side_copy(pkey, key, meta)
                new_manifest[r] = {"size": sz, "hash": h}
                deduped += 1
                bytes_deduped += sz
                prog.update(sz, 1)
                prog.display()
            except Exception as ex:
                errors += 1
                print("\n  " + C.RED + _tr("Error copying {name}: {err}")
                      .format(name=r, err=ex) + C.RESET)
                prog.update(sz, 1)
                prog.display()
        prog.finish()

        if not args.no_cache:
            _save_cloud_manifest(backend, obj_spec.prefix, new_manifest)
        vfail = 0
        if not args.no_verify and copied and backend.scheme != "smb":
            import random
            cand = [(r, m["hash"]) for r, m in new_manifest.items()
                    if m.get("hash")]
            smp = random.sample(cand, min(20, len(cand)))
            print(f"  {C.DIM}Verifying {len(smp)} uploaded objects...{C.RESET}")
            for r, hh in smp:
                m = backend.head(backend.join_key(obj_spec.prefix, r))
                if not m or m.get("fc_hash") != hh:
                    vfail += 1
                    print(f"  {C.RED}VERIFY MISMATCH: {r}{C.RESET}")
            if vfail == 0:
                print(f"  {C.GREEN}✓ Verified {len(smp)} objects OK{C.RESET}")

        banner("DONE")
        print(f"  Uploaded: {C.BOLD}{copied}{C.RESET} ({fmt_size(bytes_up)})  "
              f"{C.DIM}streamed — no dataset temp dir{C.RESET}")
        if deduped:
            print(f"  Deduped:  {C.BOLD}{deduped}{C.RESET} via server-side "
                  f"copy ({C.GREEN}{fmt_size(bytes_deduped)} bandwidth "
                  f"saved{C.RESET})")
        if skipped:
            print(f"  Skipped:  {C.BOLD}{skipped}{C.RESET} unchanged (cross-run)")
        if errors or vfail:
            print(f"  {C.RED}Errors:   {errors + vfail}{C.RESET}")
        if args.log_file:
            write_log_file(args.log_file, {
                "source": args.source, "destination": args.destination,
                "mode": f"relay_ssh_{backend.scheme}",
                "total_files": len(files), "copied": copied,
                "linked": deduped, "skipped": skipped,
                "errors": errors + vfail, "total_bytes": total_bytes,
                "bytes_written": bytes_up, "dedup_saved": bytes_deduped,
                "hash_algo": _hash_name,
            })
        return 1 if (errors or vfail) else 0
    finally:
        if spool_dir:
            shutil.rmtree(spool_dir, ignore_errors=True)
        cli.close()


# ── Plain HTTP(S) source → SSH/SMB destination (streaming relay) ───────────
# A bare https://server/dir/file URL as the source. Plain HTTP has no
# directory listing, so the source is always ONE file; it streams to the
# destination through this machine the way the R2R relay moves bytes —
# 1 MB in-memory chunks, nothing written to the local disk. The filename
# comes from the URL the user typed (never from server headers), so a
# redirecting or hostile server cannot choose where the file lands.

def is_http_url(path_str):
    return bool(path_str) and path_str.lower().startswith(("http://", "https://"))


def _http_creds_by_host(args, host):
    """The first 'http'-type saved connection whose host matches the URL's,
    or None. Peeks at the credentials file the way resolve_connection does:
    an encrypted file with no passphrase available is skipped silently."""
    if not host:
        return None
    explicit = getattr(args, "credentials_file", None)
    try:
        if explicit:
            conns = load_credentials_file(explicit)
        elif os.path.isfile(default_credentials_path()):
            if _file_is_encrypted(default_credentials_path()) \
                    and not _have_creds_passphrase():
                return None
            conns = load_credentials_file(None)
        else:
            return None
    except Exception:
        return None
    for c in (conns or {}).values():
        if c.get("type") != "http":
            continue
        ch = c.get("host") or ""
        if "://" in ch:                       # a full base URL is accepted too
            import urllib.parse
            ch = urllib.parse.urlsplit(ch).hostname or ""
        if ch.lower() == host.lower():
            return c
    return None


def _registrable_domain(host):
    """The domain a login cookie is actually stored on: dl.dell.com → dell.com.

    browser_cookie3 filters with a SUBSTRING test against each cookie's own
    domain ("dl.dell.com" in ".dell.com" is False), so asking it for the full
    hostname silently drops every parent-domain cookie — which is where
    sessions live, and why a logged-in browser still yielded nothing. Being
    broad here costs nothing: add_cookie_header() below still applies real
    RFC 6265 matching, so only cookies that genuinely belong to the URL are
    ever sent. It also covers the redirect a download link makes to its SSO
    host, which the full hostname could never match."""
    parts = [p for p in (host or "").split(".") if p]
    if len(parts) < 3:
        return host
    # co.uk / com.au / ac.jp — the registrable name needs one more label.
    if len(parts[-1]) == 2 and parts[-2] in (
            "co", "com", "net", "org", "gov", "edu", "ac"):
        return ".".join(parts[-3:])
    return ".".join(parts[-2:])


def _cookie_header_for(url, source):
    """Build a Cookie: header value for `url` from a cookie SOURCE, or None.

    `source` is either a path to a Netscape/Mozilla cookies.txt (what a browser
    "export cookies" extension writes, and what curl -b / wget --load-cookies
    read), or a browser name to pull the LIVE login session straight from the
    browser's own cookie store — 'chrome' / 'firefox' / 'chromium' / 'edge' /
    'brave' / 'opera' / 'safari', or 'browser'/'auto' to try them all. The jar
    does the domain/path/secure/expiry matching, so only the cookies that
    belong to this URL are sent."""
    import http.cookiejar
    import urllib.request
    import urllib.parse
    host = urllib.parse.urlsplit(url).hostname or ""
    src = (source or "").strip()
    if not src:
        return None
    # A path that exists (or is obviously a file) → cookies.txt via stdlib.
    looks_like_file = os.path.sep in src or src.lower().endswith(".txt") \
        or os.path.exists(os.path.expanduser(src))
    if looks_like_file:
        path = os.path.expanduser(src)
        if not os.path.isfile(path):
            raise SystemExit(f"Error: cookies file not found: {src}")
        jar = http.cookiejar.MozillaCookieJar()
        try:
            jar.load(path, ignore_discard=True, ignore_expires=True)
        except Exception as e:
            raise SystemExit(
                f"Error: could not read cookies file {src!r}: "
                f"{str(e).splitlines()[0] if str(e) else e}. It must be in "
                f"Netscape/Mozilla cookies.txt format.")
    else:
        try:
            import browser_cookie3
        except ImportError:
            # A frozen build has no pip and no site-packages to install into,
            # so "pip install browser-cookie3" is useless advice there: the
            # only route left is a cookies.txt export.
            if getattr(sys, "frozen", False):
                raise SystemExit(
                    "Error: this build cannot read a live browser session "
                    "(browser_cookie3 is not bundled). Export the browser's "
                    "cookies to a cookies.txt file (any \"cookies.txt\" "
                    "browser extension does it) and pass --cookies FILE "
                    "instead.")
            raise SystemExit(
                "Error: reading cookies from a browser needs browser_cookie3. "
                "Install with: python -m pip install browser-cookie3 "
                "(or export the browser's cookies to a cookies.txt file and "
                "point --cookies at it instead).")
        name = src.lower()
        loader = {
            "chrome": browser_cookie3.chrome,
            "chromium": getattr(browser_cookie3, "chromium", None),
            "firefox": browser_cookie3.firefox,
            "edge": getattr(browser_cookie3, "edge", None),
            "brave": getattr(browser_cookie3, "brave", None),
            "opera": getattr(browser_cookie3, "opera", None),
            "safari": getattr(browser_cookie3, "safari", None),
        }
        try:
            _cdom = _registrable_domain(host)
            if name in ("browser", "auto", ""):
                jar = browser_cookie3.load(domain_name=_cdom)
            else:
                fn = loader.get(name)
                if fn is None:
                    raise SystemExit(
                        f"Error: unknown browser {src!r}. Use one of: "
                        f"chrome, chromium, firefox, edge, brave, opera, "
                        f"safari (or 'browser' to try all).")
                jar = fn(domain_name=_cdom)
        except SystemExit:
            raise
        except Exception as e:
            raise SystemExit(
                f"Error: could not read {src} cookies for {host}: "
                f"{str(e).splitlines()[0] if str(e) else e}. Make sure you are "
                f"logged in there, and that the browser is closed if it locks "
                f"its cookie database.")
    # Let the jar pick the cookies that match this URL, then read the header
    # it composed onto a throwaway request.
    req = urllib.request.Request(url)
    jar.add_cookie_header(req)
    return req.get_header("Cookie")


def _http_resolve_auth(args, url):
    """(clean_url, headers) for an http(s) source. Merges, weakest first:
    an 'http' saved connection matched by host (Basic creds, a saved header,
    and/or a saved cookie source) → user:pass@ in the URL (stripped, with a
    shell-history warning) → --http-user / --http-password[-env] → a cookie
    source (--cookies FILE / --cookies-from-browser NAME) → header lines from
    $--http-header-env → --http-header lines (strongest, repeatable)."""
    import urllib.parse
    import base64
    parts = urllib.parse.urlsplit(url)
    host = parts.hostname or ""
    user = pw = None
    if parts.username is not None or parts.password is not None:
        user = urllib.parse.unquote(parts.username or "")
        pw = urllib.parse.unquote(parts.password or "")
        netloc = host + (f":{parts.port}" if parts.port else "")
        url = urllib.parse.urlunsplit(
            (parts.scheme, netloc, parts.path, parts.query, parts.fragment))
        print(f"  {C.YELLOW}Note: credentials taken from the URL are visible "
              f"in shell history — prefer --http-user with "
              f"--http-password-env.{C.RESET}")
    conn = _http_creds_by_host(args, host)
    headers = {}
    if conn:
        if user is None and conn.get("user"):
            user = conn["user"]
        if pw is None and conn.get("password"):
            pw = conn["password"]
        hline = conn.get("header")
        if hline and ":" in hline:
            k, _, v = hline.partition(":")
            headers[k.strip()] = v.strip()
    if getattr(args, "http_user", None):
        user = args.http_user
    if getattr(args, "http_password_env", None):
        env_pw = os.environ.get(args.http_password_env)
        if env_pw is None:
            raise SystemExit(
                f"Error: ${args.http_password_env} is not set, so the HTTP "
                f"password never arrived. Under --use-sudo the environment is "
                f"reset; re-run without it, or allow sudo to preserve that "
                f"variable.")
        pw = env_pw
    elif getattr(args, "http_password", False):
        pw = getpass.getpass(f"  HTTP password for {user or ''}@{host}: ")
    if user is not None and pw is not None:
        headers["Authorization"] = "Basic " + base64.b64encode(
            f"{user}:{pw}".encode()).decode()
    # Cookie/session source: reuse a login the user already has. A CLI flag
    # wins over the connection's saved cookie source; either way an explicit
    # --http-header "Cookie: …" below overrides.
    cookie_src = (getattr(args, "cookies_from_browser", None)
                  or getattr(args, "cookies", None)
                  or (conn.get("cookies") if conn else None))
    if cookie_src:
        cookie = _cookie_header_for(url, cookie_src)
        if cookie:
            headers["Cookie"] = cookie
        else:
            print(f"  {C.YELLOW}Note: no cookies matched {host} in "
                  f"{cookie_src!r} — is the login still active there?{C.RESET}")
    # Header lines passed by name of an env var rather than on the command
    # line — a token in argv is readable by any other user through `ps`. The
    # GUI uses this for an ad-hoc "Authorization: Bearer …"; the var may hold
    # several header lines separated by newlines.
    hdr_env = getattr(args, "http_header_env", None)
    if hdr_env and os.environ.get(hdr_env) is None:
        raise SystemExit(
            f"Error: ${hdr_env} is not set, so the HTTP header never arrived. "
            f"Under --use-sudo the environment is reset; re-run without it, or "
            f"allow sudo to preserve that variable.")
    for line in (os.environ.get(hdr_env, "").splitlines() if hdr_env else []):
        line = line.strip()
        if not line:
            continue
        if ":" not in line:
            raise SystemExit(
                f"Error: ${hdr_env} expects 'Name: value' lines, got {line!r}")
        k, _, v = line.partition(":")
        headers[k.strip()] = v.strip()
    for line in (getattr(args, "http_header", None) or []):
        if ":" not in line:
            raise SystemExit(
                f"Error: --http-header expects 'Name: value', got {line!r}")
        k, _, v = line.partition(":")
        headers[k.strip()] = v.strip()
    return url, headers


def _http_looks_like_html_wall(resp, url):
    """True when the server answered with an HTML page for a URL that does
    not name an HTML file — almost always a login or terms page standing in
    front of the real download (curl/wget save it silently; we refuse)."""
    ct = (resp.headers.get("Content-Type") or "").split(";")[0].strip().lower()
    if ct not in ("text/html", "application/xhtml+xml"):
        return False
    import urllib.parse
    path = urllib.parse.urlsplit(url).path.lower()
    return not path.endswith((".html", ".htm", ".xhtml"))


def _http_wall_report(resp, url):
    """Say what the server actually did, not just that the bytes look like HTML.

    "returned an HTML page" names a symptom; the cause is a redirect chain that
    ended somewhere else — a vendor download link bouncing to an SSO host is
    invisible otherwise, and the useful fact is WHERE it landed, because that
    is the domain the login cookie has to come from."""
    lines = []
    try:
        final = resp.geturl()
    except Exception:
        final = url
    try:
        code = resp.getcode()
    except Exception:
        code = None
    import urllib.parse
    fhost = urllib.parse.urlsplit(final).hostname or ""
    ohost = urllib.parse.urlsplit(url).hostname or ""
    if final and final != url:
        lines.append(f"redirected to {final}")
        if fhost and fhost != ohost:
            lines.append(f"a login on {ohost} is not enough — the session "
                         f"lives on {fhost}")
    if code and code != 200:
        lines.insert(0, f"HTTP {code}")
    return lines


def _http_open(url, offset=0, headers=None):
    """GET the URL (redirects followed). With offset, ask for a Range resume.
    Returns (response, total_size_or_None, mtime_or_None, resumed)."""
    import urllib.request
    hdrs = {"User-Agent": "blitcp/" + __version__}
    hdrs.update(headers or {})
    req = urllib.request.Request(url, headers=hdrs)
    if offset:
        req.add_header("Range", "bytes=%d-" % offset)
    resp = urllib.request.urlopen(req, timeout=30)
    resumed = (resp.getcode() == 206)
    total = None
    if resumed:
        m = re.match(r"bytes\s+\d+-\d+/(\d+)",
                     resp.headers.get("Content-Range", ""))
        if m:
            total = int(m.group(1))
    else:
        cl = resp.headers.get("Content-Length")
        if cl and cl.isdigit():
            total = int(cl)
    mtime = None
    lm = resp.headers.get("Last-Modified")
    if lm:
        try:
            from email.utils import parsedate_to_datetime
            mtime = parsedate_to_datetime(lm).timestamp()
        except Exception:
            pass
    return resp, total, mtime, resumed


def _relay_hasher(algo):
    if not algo:
        return None
    return new_hasher() if algo == "xxh128" else hashlib.new(algo)


def _http_pump(url, resp, total, fout, halgo, reopen_dst, start, headers=None):
    """Pump resp → fout in 1 MB in-memory chunks (the R2R relay chunk size).
    A broken HTTP stream is retried up to 3 times with a Range resume (same
    auth headers); a server that ignores Range restarts the transfer from
    zero (reopen_dst must hand back a truncated destination handle). Returns
    (bytes_written, final_response, final_fout, hex_digest_or_None)."""
    hasher = _relay_hasher(halgo)
    written = 0
    attempts = 0
    while True:
        try:
            data = resp.read(1024 * 1024)
        except (OSError, IOError) as e:
            attempts += 1
            if attempts > 3:
                raise
            try:
                resp.close()
            except Exception:
                pass
            msg = str(e).strip().splitlines()[0] if str(e).strip() else e.__class__.__name__
            print(f"\n  {C.YELLOW}HTTP stream broke at {fmt_size(written)} "
                  f"({msg}) — resuming (attempt {attempts}/3)…{C.RESET}")
            resp, _t, _m, resumed = _http_open(url, offset=written,
                                               headers=headers)
            if not resumed and written:
                print(f"  {C.YELLOW}Server does not support Range — "
                      f"restarting from 0.{C.RESET}")
                fout = reopen_dst(fout)
                hasher = _relay_hasher(halgo)
                written = 0
            continue
        if not data:
            break
        fout.write(data)
        if hasher is not None:
            hasher.update(data)
        written += len(data)
        if PROGRESS_JSON or total:
            _tar_emit(written, total or 0, 0, 1, start)
        else:
            el = time.time() - start
            sys.stdout.write(f"\r  {fmt_size(written)}  "
                             f"{fmt_speed(written / el if el > 0 else 0)}   ")
            sys.stdout.flush()
    return written, resp, fout, (hasher.hexdigest() if hasher else None)


def _http_dest_filename(url):
    """The destination filename for an http(s):// source, as ONE path segment.

    This used to be basename(urlsplit(url).path) followed by unquote(), in that
    order — so percent-encoding survived the basename and reappeared after it.
    'https://h/dir/%2e%2e%2fevil' has a single last segment when basename runs
    and becomes '../evil' a line later, which was then posixpath.join()ed onto
    the remote destination directory and escaped it.

    Nobody but the user controls this URL (Content-Disposition is not honoured
    and the redirect target is used only for a diagnostic), so it is a footgun
    rather than an attack. It is still a name that leaves the directory the
    user named. Unquote first, then take the basename, then refuse anything
    that is not a plain segment. Returns None when there is no usable name.
    """
    import urllib.parse
    raw = urllib.parse.unquote(urllib.parse.urlsplit(url).path)
    # Both separators: a Windows destination path joins on backslash too.
    raw = raw.replace("\\", "/")
    # A path that ENDS in a separator names a directory, and a directory is not
    # a file to download. The rstrip("/") that used to sit inside the basename
    # call answered 'https://host/dir/' with 'dir' — a plausible-looking name
    # that sent the run on to open the URL, so the user got whatever the
    # network said (a DNS error, a 404) instead of the refusal this is for.
    if not raw or raw.endswith("/"):
        return None
    name = posixpath.basename(raw)
    if not name or name in (".", "..") or "/" in name or "\\" in name:
        return None
    return name


def _http_skip_up_to_date(dst_size, dst_mtime, total, http_mtime, args):
    """R2R's incremental rule: same size, and mtimes agree within 2s when
    both sides know one."""
    return (not args.overwrite and total is not None and dst_size == total
            and (http_mtime is None or not dst_mtime
                 or abs(dst_mtime - http_mtime) <= 2))


def run_http_transfer(args):
    """Driver for an http(s):// SOURCE. Destination must be SSH or SMB."""
    if is_http_url(args.destination):
        print(f"{C.RED}Error: an http(s):// URL can only be the source — "
              f"plain HTTP has no generic upload.{C.RESET}")
        return 1
    if getattr(args, "extra_sources", None):
        print(f"{C.RED}Error: an http(s):// source takes a single URL "
              f"(got {len(args.extra_sources) + 1} sources).{C.RESET}")
        return 1
    url = args.source
    fname = _http_dest_filename(url)
    if not fname:
        print(f"{C.RED}Error: the URL names no file "
              f"(https://host/dir/file expected): {url}{C.RESET}")
        return 1
    try:
        dst_spec = _object_spec(args.destination, args)
        if dst_spec is not None and dst_spec.scheme == "smb":
            return _http_to_smb(args, url, fname, dst_spec)
        if dst_spec is not None:
            print(f"{C.RED}Error: http(s) → cloud is not supported yet — "
                  f"relay via an SSH or SMB destination, or download "
                  f"locally first.{C.RESET}")
            return 1
        dst_remote = parse_remote_path(args.destination)
        if dst_remote is None:
            print(f"{C.RED}Error: an http(s):// source needs an SSH "
                  f"(user@host:/path) or SMB (smb://host/share) destination. "
                  f"For a local download use curl or wget.{C.RESET}")
            return 1
        return _http_to_ssh(args, url, fname, dst_remote)
    except SystemExit:
        raise
    except Exception as e:
        msg = _fmt_exc(e)
        print(f"{C.RED}Error: {msg}{C.RESET}")
        return 1


def _http_to_ssh(args, url, fname, dst_remote):
    """https://…/file → SSH destination, streamed over a pipelined SFTP handle
    exactly like the R2R SFTP relay's destination half — or, when the
    destination is SSH-only, over a `cat > file` exec channel instead.

    Honouring that choice is not optional: a connection saved as protocol 'ssh'
    (or --ssh-no-sftp) is one whose SFTP subsystem is off, and opening an SFTP
    handle there used to fail with a bare "Channel closed." after the flag had
    already been read and silently dropped."""
    if not _load_paramiko():
        print(f"{C.RED}Error: SSH transfers require paramiko.{C.RESET}")
        return 1
    start = time.time()
    dst_remote = dst_remote._replace(port=args.ssh_port)
    pw = _resolved_dst_pw(args)
    if not pw and getattr(args, "ssh_password", False):
        pw = getpass.getpass(
            f"Password for {dst_remote.user}@{dst_remote.host}: ")
    cli = _tar_ssh_connect(dst_remote, args.ssh_key, pw, args.compress)
    resp = None
    try:
        use_sftp = not getattr(args, "ssh_no_sftp", False)
        sftp = None
        if use_sftp:
            try:
                sftp = cli.open_sftp()
            except Exception as e:
                # The server took the connection and then refused the channel —
                # SSH on, SFTP off, a common NAS default. The exec writer below
                # serves this case, so fall through to it rather than failing:
                # the same shape as the shell fallback in _ssh_ls.
                why = str(e).strip().splitlines()[0] or type(e).__name__
                if getattr(args, "sftp_only", False):
                    # An explicit --sftp-only is a restriction, not a
                    # preference: opening a shell on a host the user confined
                    # to SFTP is exactly what the flag exists to prevent.
                    print(f"\n{C.RED}Error: {dst_remote.user}@"
                          f"{dst_remote.host} accepted the SSH connection but "
                          f"would not open an SFTP channel ({why}), and "
                          f"--sftp-only forbids the shell fallback.{C.RESET}")
                    if _env("TRACEBACK"):
                        import traceback as _tb
                        print(_tb.format_exc().rstrip())
                    return 1
                # Not announced: the banner below already says "(SSH only,
                # cat over exec)", so the transport is on screen either way
                # and a line on every run against an SFTP-less NAS is noise.
                # BLITCP_TRACEBACK still shows where the SFTP attempt died.
                if _env("TRACEBACK"):
                    import traceback as _tb
                    print(_tb.format_exc().rstrip())
                sftp = None
                use_sftp = False

        # ── destination primitives, one shape over SFTP or an exec channel ──
        def _d_stat(pth):
            """('dir'|'file'|None, size, mtime)."""
            if sftp is not None:
                try:
                    st = sftp.stat(pth)
                except IOError:
                    return None, 0, 0.0
                return (("dir" if stat.S_ISDIR(st.st_mode) else "file"),
                        st.st_size, st.st_mtime)
            return _ssh_exec_stat(cli, pth)

        def _d_mkdir(pth):
            if sftp is not None:
                _sftp_mkdir_p(sftp, pth)
            else:
                _ssh_run(cli, "mkdir -p " + shlex.quote(pth), timeout=60)

        def _d_open(pth):
            if sftp is not None:
                f = sftp.open(pth, "wb")
                f.set_pipelined(True)
                return f
            return _SshExecWriter(cli, pth)

        def _d_utime(pth, when):
            if sftp is not None:
                try:
                    sftp.utime(pth, (when, when))
                except IOError:
                    pass
            else:
                _ssh_run(cli, "touch -d @%d %s 2>/dev/null || true"
                         % (int(when), shlex.quote(pth)), timeout=60)

        target = dst_remote.path
        # Single-file convention: an existing directory — or a path spelled
        # with a trailing '/' — receives <dir>/<url filename>; any other
        # path IS the target name (rename-on-copy).
        kind, _sz, _mt = _d_stat(target)
        is_dir = (kind == "dir") if kind else target.endswith("/")
        if is_dir:
            target = posixpath.join(target.rstrip("/") or "/", fname)
        rel = posixpath.basename(target)
        parent = posixpath.dirname(target) or "/"

        url, hdrs = _http_resolve_auth(args, url)
        resp, total, http_mtime, _ = _http_open(url, headers=hdrs)
        banner("HTTP → SSH  [streaming relay]"
               + ("" if use_sftp else "  (SSH only, cat over exec)"))
        print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{url}{C.RESET}")
        print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dst_remote.user}@"
              f"{dst_remote.host}:{target}{C.RESET}")
        print(f"  Size:      "
              f"{C.BOLD}{fmt_size(total) if total is not None else 'unknown'}{C.RESET}")
        if not args.force and _http_looks_like_html_wall(resp, url):
            print(f"  {C.RED}Error: the server returned an HTML page instead "
                  f"of the file (a login or terms page?).{C.RESET}")
            for _l in _http_wall_report(resp, url):
                print(f"  {C.YELLOW}  → {_l}{C.RESET}")
            print(f"  {C.DIM}Use the direct download link, or pass the needed "
                  f"cookie/token via --http-header / --cookies; --force saves "
                  f"the HTML anyway.{C.RESET}")
            return 1

        dkind, dsize, dmtime = _d_stat(target)
        if dkind == "file" and _http_skip_up_to_date(dsize, dmtime,
                                                     total, http_mtime, args):
            print(f"  {C.GREEN}Up to date — skipped (same size"
                  f"{'' if http_mtime is None else ' and mtime'}).{C.RESET}")
            return 0
        if args.dry_run:
            print(f"  {C.YELLOW}Dry run — would stream to {target}.{C.RESET}")
            return 0

        # Hash the stream with an algorithm the destination can recompute,
        # so verify never re-downloads. No exec channel (SFTP-only gateway)
        # or no common tool → verify falls back to a size check.
        caps = None
        if not args.no_verify:
            try:
                caps = _ssh_exec_caps(cli, parent)
            except Exception:
                caps = None
        halgo = caps["halgo"] if caps else None

        _d_mkdir(parent)

        def _reopen(old):
            try:
                old.close()
            except Exception:
                pass
            return _d_open(target)

        fout = _d_open(target)
        try:
            written, resp, fout, digest = _http_pump(
                url, resp, total, fout, halgo, _reopen, start, headers=hdrs)
        finally:
            fout.close()
        print()
        if total is not None and written != total:
            print(f"  {C.RED}Error: transfer truncated — got "
                  f"{fmt_size(written)} of {fmt_size(total)}.{C.RESET}")
            _log("error", rel, written, error="truncated HTTP stream")
            return 1
        if http_mtime:
            _d_utime(target, http_mtime)
        _log("copied", rel, written, method="http_relay")

        verified = True
        if not args.no_verify:
            ok = None
            if digest and caps and caps.get("hash"):
                rh = _ssh_remote_hashes(cli, parent, [rel], caps).get(rel)
                ok = (rh == digest) if rh else None
            if ok is None:
                vkind, vsize, _vm = _d_stat(target)
                ok = (vkind == "file" and vsize == written)
                print(f"  {C.YELLOW}Verified by size only (no common hash "
                      f"tool on the destination).{C.RESET}")
            verified = bool(ok)
            if verified:
                print(f"  {C.GREEN}Verified ✓{C.RESET}")
            else:
                print(f"  {C.RED}VERIFICATION FAILED — destination does not "
                      f"match the downloaded stream.{C.RESET}")
        el = time.time() - start
        print(f"  {C.GREEN}Done: {fmt_size(written)} in {el:.1f}s "
              f"({fmt_speed(written / el if el > 0 else 0)}){C.RESET}")
        if PROGRESS_JSON:
            _tar_emit(written, total or written, 1, 1, start, final=True)
        return 0 if verified else 1
    except Exception as e:
        msg = _fmt_exc(e)
        print(f"\n{C.RED}Error: {msg}{C.RESET}")
        return 1
    finally:
        if resp is not None:
            try:
                resp.close()
            except Exception:
                pass
        cli.close()


def _http_to_smb(args, url, fname, dst_spec):
    """https://…/file → SMB share, streamed through an open write handle on
    the share (never the local disk). Verify reads the file back and
    re-hashes it — SMB has no server-side hash tool."""
    start = time.time()
    backend = make_backend(dst_spec, args)
    resp = None
    try:
        key = dst_spec.prefix.rstrip("/")
        # parse_smb_url strips the trailing slash off the prefix, so the SPEC
        # can no longer answer "did the user write a directory?" — that check
        # against dst_spec.prefix could never be true. Ask the raw destination
        # the user typed. Without it, `smb://host/share/dir/` with no `dir` on
        # the share yet wrote the download to the share as a FILE named `dir`:
        # exit 0, verification passed (it read back the file it had just
        # written), and nothing at `dir/<name>` for the next run to find.
        dst_named_dir = str(args.destination or "").rstrip().endswith(("/", "\\"))
        st = backend.stat_key(key) if key else None
        if not key or dst_named_dir \
                or (st is not None and stat.S_ISDIR(st.st_mode)):
            key = (key + "/" + fname).lstrip("/")

        url, hdrs = _http_resolve_auth(args, url)
        resp, total, http_mtime, _ = _http_open(url, headers=hdrs)
        banner("HTTP → SMB  [streaming relay]")
        print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{url}{C.RESET}")
        print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}smb://{backend.host}/"
              f"{dst_spec.container}/{key}{C.RESET}")
        print(f"  Size:      "
              f"{C.BOLD}{fmt_size(total) if total is not None else 'unknown'}{C.RESET}")
        if not args.force and _http_looks_like_html_wall(resp, url):
            print(f"  {C.RED}Error: the server returned an HTML page instead "
                  f"of the file (a login or terms page?).{C.RESET}")
            for _l in _http_wall_report(resp, url):
                print(f"  {C.YELLOW}  → {_l}{C.RESET}")
            print(f"  {C.DIM}Use the direct download link, or pass the needed "
                  f"cookie/token via --http-header / --cookies; --force saves "
                  f"the HTML anyway.{C.RESET}")
            return 1

        tstat = backend.stat_key(key)
        if tstat is not None and _http_skip_up_to_date(
                tstat.st_size, tstat.st_mtime, total, http_mtime, args):
            print(f"  {C.GREEN}Up to date — skipped (same size"
                  f"{'' if http_mtime is None else ' and mtime'}).{C.RESET}")
            return 0
        if args.dry_run:
            print(f"  {C.YELLOW}Dry run — would stream to {key}.{C.RESET}")
            return 0

        halgo = None if args.no_verify else _hash_name

        def _reopen(old):
            try:
                old.close()
            except Exception:
                pass
            return backend.open_write(key)

        fout = backend.open_write(key)
        try:
            written, resp, fout, digest = _http_pump(
                url, resp, total, fout, halgo, _reopen, start, headers=hdrs)
        finally:
            fout.close()
        print()
        if total is not None and written != total:
            print(f"  {C.RED}Error: transfer truncated — got "
                  f"{fmt_size(written)} of {fmt_size(total)}.{C.RESET}")
            _log("error", key, written, error="truncated HTTP stream")
            return 1
        if http_mtime:
            backend.set_key_mtime(key, http_mtime)
        _log("copied", key, written, method="http_relay")

        verified = True
        if not args.no_verify and digest:
            print(f"  Verifying (reading back from the share)…", end="",
                  flush=True)
            h = _relay_hasher(halgo)
            fin, _rsz, _rm = backend.open_read(key)
            try:
                for chunk in iter(lambda: fin.read(1024 * 1024), b""):
                    h.update(chunk)
            finally:
                fin.close()
            verified = (h.hexdigest() == digest)
            print(f"\r  {C.GREEN}Verified ✓{' ' * 40}{C.RESET}" if verified
                  else f"\r  {C.RED}VERIFICATION FAILED — share content does "
                       f"not match the downloaded stream.{C.RESET}")
        el = time.time() - start
        print(f"  {C.GREEN}Done: {fmt_size(written)} in {el:.1f}s "
              f"({fmt_speed(written / el if el > 0 else 0)}){C.RESET}")
        if PROGRESS_JSON:
            _tar_emit(written, total or written, 1, 1, start, final=True)
        return 0 if verified else 1
    except Exception as e:
        msg = _fmt_exc(e)
        print(f"\n{C.RED}Error: {msg}{C.RESET}")
        return 1
    finally:
        if resp is not None:
            try:
                resp.close()
            except Exception:
                pass


def _preserve_set(args):
    val = (args.preserve or "")
    if val == "all":
        return {"mode", "times", "owner", "xattr", "acl"}
    if val == "none":
        return set()
    return set(t.strip() for t in val.split(",") if t.strip())


def _cloud_upload_skip(backend, key, dest_info, entry, local_hash, no_cache):
    """Is this exact file already the object at `key`?

    THE DESTINATION ANSWERS THIS, NOT A CACHE. The upload used to decide it
    from the cross-run manifest alone — "we uploaded this hash last time" —
    which is a fact about the SOURCE and about the past, and says nothing
    about what is in the bucket now. Delete one object between two runs and
    the second reported "Skipped: 3 unchanged (cross-run)" over a prefix
    holding two, exited 0, and never brought the file back. The summary
    counted a bucket it had not looked at.

    So the object has to be there, and it has to be this file:

      1. present in the destination listing at all — one LIST for the whole
         prefix, which is why the caller passes a row from it rather than
         asking per key;
      2. the same size;
      3. the same bytes, established against the OBJECT: the digest blitcp
         recorded on it when it uploaded it (one HEAD, no re-read of the
         local file), or failing that a plain-MD5 ETag compared with the
         local bytes. A multipart ETag is an MD5 of part MD5s and is not
         used — reconstructing it means guessing the uploader's part size.

    Anything that cannot be shown identical is uploaded again. The cost is
    bandwidth; the alternative is what this function exists to stop.

    Two honest limits, stated rather than papered over. A store with no
    per-object metadata and no usable ETag — SMB is the one here — can only
    offer steps 1 and 2, so its content evidence still comes from the signed
    sidecar; the existence and size checks are new and are what fix the
    deleted-object case there. And --no-cache keeps its meaning: it turns the
    cross-run skip off entirely rather than making it cleverer.
    """
    if no_cache or dest_info is None:
        return False
    if int(dest_info.get("size") or -1) != entry.size:
        return False
    meta = backend.head(key) or {}
    want, algo = meta.get("fc_hash"), meta.get("fc_hash_algo")
    if want and algo:
        if algo == _hash_name and local_hash:
            return want == local_hash
        try:
            return _hash_local_file(entry.src, algo) == want
        except (OSError, ValueError):
            return False
    etag = str(dest_info.get("etag") or "").strip('"').lower()
    if len(etag) == 32 and "-" not in etag:
        try:
            return _md5_file(entry.src) == etag
        except OSError:
            return False
    return False


def _upload_to_cloud(args, dst_spec):
    backend = make_backend(dst_spec, args)
    pretty = CLOUD_SCHEME_NAMES[dst_spec.scheme]
    banner(f"UPLOAD → {pretty}")
    print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{args.source}{C.RESET}")
    print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dst_spec.scheme}://{dst_spec.container}/"
          f"{dst_spec.prefix}{C.RESET}")

    src = os.path.abspath(args.source)
    if not os.path.exists(src):
        print(f"\n{C.RED}Error: source not found: {args.source}{C.RESET}")
        sys.exit(1)
    # A single file uploads under <prefix>/<basename>; a directory mirrors the
    # tree (cp/SSH-backend semantics).
    if os.path.isfile(src):
        entries = [FileEntry(src=src, rel=os.path.basename(src),
                             size=os.path.getsize(src), physical_offset=0,
                             content_hash=None)]
    else:
        entries, scan_errors = scan_source(
            src, None, args.exclude,
            include_node_modules=args.include_node_modules)
        print()
        if scan_errors:
            print(f"  {C.YELLOW}{len(scan_errors)} file(s) could not be read "
                  f"and were skipped.{C.RESET}")
    if not entries:
        print(f"  {C.YELLOW}Nothing to upload.{C.RESET}")
        return

    preserve = _preserve_set(args)
    total_bytes = sum(e.size for e in entries)
    print(f"  Files:   {C.BOLD}{len(entries)}{C.RESET}  "
          f"({fmt_size(total_bytes)})")

    # Hash for verification + dedup (skip when dedup and verify both off).
    hashes = {}
    if not args.no_dedup or not args.no_verify:
        print("  " + C.DIM + _tr("Hashing {n} files...").format(n=len(entries)) + C.RESET)
        hashes = _cloud_hash_entries(entries, args.threads)

    # Classify every entry BEFORE any network I/O so the parallel phases below
    # run without races. A duplicate is server-side-copied FROM its primary's
    # object, so all primaries must land first (Phase A) before any copy runs
    # (Phase B). first_key_for_hash is built here, single-threaded, so the
    # primary/duplicate decision is deterministic and lock-free.
    first_key_for_hash = {}
    uploaded = copied = skipped = errors = refused = 0
    bytes_uploaded = bytes_deduped = bytes_refused = 0

    # What is ACTUALLY in the destination, in one call. The cross-run skip
    # used to be decided from the manifest alone and never looked here, so an
    # object deleted between two runs stayed deleted and was reported as
    # "unchanged". --overwrite replaces everything by definition, so the
    # listing is not fetched for it.
    dest_index = {}
    if not args.overwrite and not args.no_cache:
        try:
            dest_index = backend.list_objects(dst_spec.prefix) or {}
        except Exception as ex:                                # noqa: BLE001
            # No listing is not the same as "nothing is there". Upload
            # everything rather than skip on an answer we did not get.
            print(f"  {C.YELLOW}Could not list the destination ({ex}) — "
                  f"nothing will be skipped this run{C.RESET}")
            dest_index = {}

    new_manifest = {}
    primaries = []          # (entry, key, meta) — upload the bytes
    dups = []               # (entry, src_key, key, meta) — server-side copy
    skip_bytes = 0
    for e in entries:
        key = backend.join_key(dst_spec.prefix, e.rel)
        h = hashes.get(e.rel)
        new_manifest[e.rel] = {"size": e.size, "hash": h}

        # Cross-run skip: the OBJECT is this file. Asked of the destination
        # listing and the object itself — see _cloud_upload_skip.
        if (not args.overwrite
                and _cloud_upload_skip(backend, key, dest_index.get(key), e,
                                       h, args.no_cache)):
            skipped += 1
            skip_bytes += e.size
            _log("skipped", e.rel, e.size, reason="unchanged")
            continue

        meta = build_object_meta(e, h, preserve)
        if h and not args.no_dedup and h in first_key_for_hash:
            dups.append((e, first_key_for_hash[h], key, meta))
        else:
            primaries.append((e, key, meta))
            if h and not args.no_dedup:
                first_key_for_hash[h] = key

    prog = Progress(total_bytes, len(entries))
    if skipped:
        prog.update(skip_bytes, skipped)
        prog.display()

    lock = threading.Lock()

    def _do_upload(item):
        nonlocal uploaded, bytes_uploaded, errors, refused, bytes_refused
        e, key, meta = item
        try:
            if not args.dry_run:
                backend.upload(e.src, key, meta)
            with lock:
                uploaded += 1
                bytes_uploaded += e.size
                # The record names files here, like every other engine. It
                # named none at all: the upload wrote no per-file entries, so
                # a file the store refused was absent from the destination AND
                # absent from the record, and nothing said so.
                _log("copied", e.rel, e.size, method="object")
                prog.update(e.size, 1)
                prog.display()
        except ObjectNameRefused as ex:
            with lock:
                refused += 1
                bytes_refused += e.size
                _note_refusal(e.rel)
                _log("refused", e.rel, e.size, error="refused: %s" % ex)
                print(f"\n  {C.RED}Refused: {e.rel}: {ex}{C.RESET}")
                prog.update(e.size, 1)
                prog.display()
        except Exception as ex:
            with lock:
                errors += 1
                _log("error", e.rel, e.size, error=str(ex))
                print(f"\n  {C.RED}Error uploading {e.rel}: {ex}{C.RESET}")
                prog.update(e.size, 1)
                prog.display()

    def _do_copy(item):
        nonlocal copied, bytes_deduped, errors, refused, bytes_refused
        e, src_key, key, meta = item
        try:
            if not args.dry_run:
                backend.server_side_copy(src_key, key, meta)
            with lock:
                copied += 1
                bytes_deduped += e.size
                _log("linked", e.rel, e.size, method="server_side_copy")
                prog.update(e.size, 1)
                prog.display()
        except ObjectNameRefused as ex:
            with lock:
                refused += 1
                bytes_refused += e.size
                _note_refusal(e.rel)
                _log("refused", e.rel, e.size, error="refused: %s" % ex)
                print(f"\n  {C.RED}Refused: {e.rel}: {ex}{C.RESET}")
                prog.update(e.size, 1)
                prog.display()
        except Exception as ex:
            with lock:
                errors += 1
                _log("error", e.rel, e.size, error=str(ex))
                print("\n  " + C.RED + _tr("Error copying {name}: {err}").format(name=e.rel, err=ex) + C.RESET)
                prog.update(e.size, 1)
                prog.display()

    workers = max(1, args.cloud_concurrency)
    # Phase A — upload primaries in parallel (moves the bytes).
    if primaries:
        with ThreadPoolExecutor(max_workers=workers) as pool:
            list(as_completed([pool.submit(_do_upload, it) for it in primaries]))
    # Phase B — server-side-copy duplicates in parallel; primaries now exist.
    if dups:
        with ThreadPoolExecutor(max_workers=workers) as pool:
            list(as_completed([pool.submit(_do_copy, it) for it in dups]))
    prog.finish()

    if not args.dry_run and not args.no_cache:
        # A refused name never became an object, so it must not appear in the
        # manifest as one. It did: new_manifest is filled from the scan, before
        # anything is uploaded, so the next run matched the recorded hash and
        # SKIPPED the file — reporting "unchanged" about something that was
        # never there. That is the silent loss again, one run later and harder
        # to see.
        _refused_now = set(_REFUSED_PATHS)
        _save_cloud_manifest(backend, dst_spec.prefix,
                             {k: v for k, v in new_manifest.items()
                              if k not in _refused_now})

    # Verify: HEAD a sample and confirm fc-hash matches what we computed.
    if not args.dry_run and not args.no_verify and uploaded:
        # Not over the refused ones. A refusal is already reported on its own
        # line; sampling it here as well produced "VERIFY MISMATCH" for a file
        # nobody tried to upload — a check firing on a correct run, which is
        # how people learn to ignore checks.
        _refused_now = set(_REFUSED_PATHS)
        _verify_uploads(backend, dst_spec.prefix,
                        [e for e in entries if e.rel not in _refused_now],
                        hashes)

    banner("DONE")
    print(f"  Uploaded: {C.BOLD}{uploaded}{C.RESET} new  "
          f"({fmt_size(bytes_uploaded)})")
    if copied:
        print(f"  Deduped:  {C.BOLD}{copied}{C.RESET} via server-side copy  "
              f"({C.GREEN}{fmt_size(bytes_deduped)} bandwidth saved{C.RESET})")
    if skipped:
        print(f"  Skipped:  {C.BOLD}{skipped}{C.RESET} unchanged (cross-run)")
    if refused:
        print("  " + C.RED
              + _tr("{n} file(s) were refused and not written:").format(n=refused)
              + C.RESET)
        for _rel in sorted(_REFUSED_PATHS)[:10]:
            print(f"    {C.DIM}{_rel}{C.RESET}")
        if refused > 10:
            print("    " + C.DIM
                  + _tr("... and {m} more").format(m=refused - 10) + C.RESET)
    if errors:
        print(f"  {C.RED}Errors:   {errors}{C.RESET}")
    _closed = uploaded + copied + skipped + refused + errors
    if _closed != len(entries):
        print(f"  {C.YELLOW}Note:    these numbers do not add up: "
              f"{uploaded} uploaded + {copied} deduped + {skipped} skipped + "
              f"{refused} refused + {errors} errors = {_closed}, not "
              f"{len(entries)}. One of them is wrong — treat the run as "
              f"unreported, not as done.{C.RESET}")
    if args.dry_run:
        print(f"  {C.YELLOW}(dry run — nothing uploaded){C.RESET}")
    if args.log_file:
        write_log_file(args.log_file, {
            "source": args.source, "destination": args.destination,
            "mode": f"upload_{dst_spec.scheme}", "total_files": len(entries),
            "copied": uploaded, "linked": copied, "refused": refused,
            "refused_paths": sorted(_REFUSED_PATHS)[:100],
            "skipped": skipped,
            "errors": errors, "total_bytes": total_bytes,
            "bytes_written": bytes_uploaded, "bytes_refused": bytes_refused,
            "dedup_saved": bytes_deduped,
            "hash_algo": _hash_name,
        })
    # Deliberately NOT `or refused`, and this is the one place in the codebase
    # where a refusal does not set the exit code.
    #
    # Every other refusal blitcp raises is actionable: a destination path that
    # leads outside itself is fixed by naming the real path, so failing the
    # run tells the operator to go and fix it. A name the share cannot
    # represent is not that. " is illegal in an SMB filename; no re-run, no
    # flag and no permission changes it, and there is nothing for the operator
    # to do except know. Failing every future run of an otherwise perfect
    # backup over a permanent property of the destination is how an exit code
    # stops being read.
    #
    # It is not silent: the name is printed under "were refused and not
    # written" and carried in the record as a refused entry with its path, and
    # the buckets close over it. Reported, not fatal.
    if errors:
        sys.exit(1)


def _md5_file(path, buf=4 * 1024 * 1024):
    """MD5 of a local file, for comparison against an object's ETag.

    MD5 is not a security choice here and is not used as one: it is the
    algorithm S3 defines for the ETag of a single-PUT object, so it is the
    only way to compare local bytes against a fingerprint the store already
    computed. Nothing is authorised on the strength of it — a match means
    "do not download this again", and a mismatch means download.
    """
    h = hashlib.new("md5")
    with open(path, "rb") as f:
        while True:
            b = f.read(buf)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def _cloud_download_skip(backend, key, info, local_path):
    """Is the local file already this object, byte for byte?

    The download direction had no incremental check at all: `skipped` was
    initialised to 0 and never incremented anywhere, so a second run over a
    destination that already held every file downloaded the whole prefix again
    and reported all of it as copied.

    An object store does not offer the download the two facts the local and
    SSH incremental checks lean on. mtime is assigned by the SERVER, not
    carried from the source, so "same size and mtime" says nothing about the
    bytes — it is exactly the state the overwrite scenario stages as DIFFERENT
    content. So size is the cheap gate and CONTENT is the decision:

      1. the ETag, when the store gives a plain MD5 — free, it arrives with
         the listing. A multipart upload's ETag is an MD5 of part MD5s with a
         '-N' suffix and is deliberately NOT used: reconstructing it means
         guessing the part size the uploader chose, and a guess is how this
         check would start being wrong.
      2. otherwise the hash blitcp itself recorded on the object, one HEAD,
         and only when the object names the algorithm it used.

    No answer means download. A file that cannot be shown identical is
    fetched; that costs bandwidth, and the alternative is keeping a stale
    file because nothing could prove it stale.
    """
    try:
        st = os.lstat(local_path)
    except OSError:
        return False
    if not stat.S_ISREG(st.st_mode) or st.st_size != int(info.get("size") or -1):
        return False
    etag = str(info.get("etag") or "").strip('"').lower()
    if len(etag) == 32 and "-" not in etag:
        try:
            return _md5_file(local_path) == etag
        except OSError:
            return False
    meta = backend.head(key) or {}
    want, algo = meta.get("fc_hash"), meta.get("fc_hash_algo")
    if want and algo:
        try:
            return _hash_local_file(local_path, algo) == want
        except (OSError, ValueError):
            return False
    return False


def _download_from_cloud(args, src_spec):
    backend = make_backend(src_spec, args)
    pretty = CLOUD_SCHEME_NAMES[src_spec.scheme]
    banner(f"DOWNLOAD ← {pretty}")
    print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{src_spec.scheme}://{src_spec.container}/"
          f"{src_spec.prefix}{C.RESET}")
    print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{args.destination}{C.RESET}")

    objects = backend.list_objects(src_spec.prefix)
    # Never download our own manifest.
    objects = {k: v for k, v in objects.items()
               if not k.endswith((CLOUD_MANIFEST_NAME, LEGACY_CLOUD_MANIFEST_NAME))}
    if not objects:
        print(f"  {C.YELLOW}No objects found under that prefix.{C.RESET}")
        return

    dst_root = os.path.abspath(args.destination)
    prefix = src_spec.prefix.rstrip("/")
    total_bytes = sum(v["size"] for v in objects.values())
    print(f"  Objects: {C.BOLD}{len(objects)}{C.RESET}  ({fmt_size(total_bytes)})")

    downloaded = skipped = errors = refused = verified_fail = 0
    bytes_written = 0
    real_root = _fs_realpath(dst_root)
    # Same report as the local flow, same reason: an object store with a
    # thousand keys under a symlinked destination directory would print a
    # thousand "Skipping unsafe key" lines and no explanation. The
    # per-key check below stays — this only announces it once.
    # The rels, computed ONCE, and the same list given to the preflight and to
    # the download loop. Handing the preflight raw object KEYS meant it
    # reported the prefix directory — "backups" — instead of the destination
    # directory the files actually land in.
    def _key_to_rel(key):
        rel = (key[len(prefix):].lstrip("/")
               if prefix and key.startswith(prefix) else key)
        rel = rel.lstrip("/")
        return rel or key.rsplit("/", 1)[-1]

    _rels = [_key_to_rel(k) for k in sorted(objects)]
    # A bucket is untrusted, and the per-key check below is
    # _safe_local_dest(..., trusted_source=False). The preflight has to ask
    # that same question or it reports nothing and the flood it replaces
    # happens anyway.
    warn_symlinked_dest_dirs(dst_root, _rels, trusted_source=False)

    # ── Incremental check ──
    # Decided here, before the pool starts, so it is single-threaded and the
    # numbers below cannot race. --overwrite means "replace what is there",
    # which is the one thing this must not second-guess.
    skip_keys = set()
    skip_bytes = 0
    if not args.overwrite and not args.dry_run and os.path.isdir(dst_root):
        for key, info in sorted(objects.items()):
            rel = _key_to_rel(key)
            local_path = _safe_local_dest(real_root, rel)
            if local_path is None:
                continue                       # the download loop refuses it
            if _cloud_download_skip(backend, key, info, local_path):
                skip_keys.add(key)
                skipped += 1
                skip_bytes += int(info.get("size") or 0)
                _log("skipped", rel, int(info.get("size") or 0),
                     reason="unchanged")
        if skipped:
            print(f"  Unchanged: {C.BOLD}{skipped}{C.RESET} already present "
                  f"({C.GREEN}{fmt_size(skip_bytes)}{C.RESET})")

    prog = Progress(total_bytes, len(objects))
    if skipped:
        prog.update(skip_bytes, skipped)
        prog.display()
    lock = threading.Lock()

    # No dedup ordering on the way down, so every object is independent — one
    # flat parallel pool. os.makedirs(exist_ok=True) is safe under concurrency.
    def _do_download(item):
        nonlocal downloaded, bytes_written, errors, refused, verified_fail
        key, info = item
        # Map key → local relative path. Prefer fc-relpath metadata when present.
        rel = _key_to_rel(key)
        # A remote bucket is untrusted: its keys/metadata can attempt traversal.
        # _safe_local_dest returns None for '..'/absolute/symlink-escape paths.
        local_path = _safe_local_dest(real_root, rel)
        if local_path is None:
            with lock:
                # A policy refusal, on the one list every other engine writes
                # to. It used to be counted as an error, which is the bucket
                # for something that broke.
                refused += 1
                _note_refusal(rel)
                _log("refused", rel, int(info.get("size") or 0),
                     error="refused: resolves outside the destination")
                print(f"\n  {C.RED}Skipping unsafe key: {key}{C.RESET}")
                prog.update(info["size"], 1); prog.display()
            return
        try:
            os.makedirs(os.path.dirname(local_path) or ".", exist_ok=True)
            if args.dry_run:
                with lock:
                    prog.update(info["size"], 1); prog.display()
                return
            meta = backend.download(key, local_path)
            # If the object recorded its original relpath, honor it (rename) —
            # but only if it, too, stays safely inside the destination.
            recorded = meta.get("fc_relpath")
            if recorded:
                want = _unquote_rel(recorded)
                want_path = _safe_local_dest(real_root, want)
                if want_path is not None \
                        and os.path.abspath(want_path) != os.path.abspath(local_path):
                    os.makedirs(os.path.dirname(want_path) or ".", exist_ok=True)
                    os.replace(local_path, want_path)
                    local_path = want_path
            apply_object_meta_local(local_path, meta)
            # Verify: re-hash and compare to stored fc-hash (same algo only).
            vfail = False
            if not args.no_verify:
                want_hash = meta.get("fc_hash")
                if want_hash and meta.get("fc_hash_algo") == _hash_name:
                    vfail = hash_file(local_path) != want_hash
            with lock:
                if vfail:
                    verified_fail += 1
                    print(f"\n  {C.RED}VERIFY FAILED: {rel}{C.RESET}")
                downloaded += 1
                bytes_written += int(info.get("size") or 0)
                _log("copied", rel, int(info.get("size") or 0), method="cloud")
                prog.update(info["size"], 1); prog.display()
        except Exception as ex:
            with lock:
                errors += 1
                print(f"\n  {C.RED}Error downloading {key}: {ex}{C.RESET}")
                prog.update(info["size"], 1); prog.display()

    workers = max(1, args.cloud_concurrency)
    with ThreadPoolExecutor(max_workers=workers) as pool:
        list(as_completed([pool.submit(_do_download, it)
                           for it in sorted(objects.items())
                           if it[0] not in skip_keys]))
    prog.finish()

    banner("DONE")
    print(f"  Downloaded: {C.BOLD}{downloaded}{C.RESET} ({fmt_size(bytes_written)})")
    if skipped:
        print(f"  Skipped:  {C.BOLD}{skipped}{C.RESET} unchanged "
              f"({C.GREEN}{fmt_size(skip_bytes)}{C.RESET})")
    if refused:
        print("  " + C.RED
              + _tr("{n} file(s) were refused and not written:").format(n=refused)
              + C.RESET)
    if verified_fail:
        print("  " + C.RED + _tr("Verification failures: {n}").format(n=verified_fail) + C.RESET)
    if errors:
        print(f"  {C.RED}Errors: {errors}{C.RESET}")
    if args.dry_run:
        print(f"  {C.YELLOW}(dry run — nothing downloaded){C.RESET}")
    if args.log_file:
        write_log_file(args.log_file, {
            "source": args.source, "destination": args.destination,
            "mode": f"download_{src_spec.scheme}", "total_files": len(objects),
            "copied": downloaded, "linked": 0, "refused": refused,
            "refused_paths": sorted(_REFUSED_PATHS)[:100],
            "skipped": skipped,
            "errors": errors + verified_fail, "total_bytes": total_bytes,
            # What this run actually moved. It reported the size of the whole
            # prefix whatever it did, so a run that downloaded nothing still
            # claimed every byte.
            "bytes_written": bytes_written, "bytes_refused": 0,
            "dedup_saved": 0, "hash_algo": _hash_name,
        })
    if errors or refused or verified_fail:
        sys.exit(1)


RELAY_CHUNK = 1024 * 1024  # relay chunk size — same as the R2R pipe


def _unsafe_rel(rel):
    """True for a relative path that could escape the destination root — the
    source listing is UNTRUSTED (a hostile bucket/share can craft keys)."""
    if not rel or rel.startswith(("/", "\\")):
        return True
    return any(p == ".." for p in rel.replace("\\", "/").split("/"))


def _rel_excluded(rel, patterns):
    """--exclude for the streaming relays: match the rel path or any of its
    path components (same spirit as scan_source's name matching)."""
    if not patterns:
        return False
    parts = rel.replace("\\", "/").split("/")
    return any(fnmatch.fnmatch(rel, p) or any(fnmatch.fnmatch(c, p)
               for c in parts) for p in patterns)


def _spool_from_stream(fin, spool_mb, spool_dir, halgo, prog=None):
    """Drain fin into a SpooledTemporaryFile — pure RAM up to spool_mb MB,
    transparently overflowing to a temp file under spool_dir — hashing the
    bytes in flight. Progress is credited at half weight (the download half;
    the upload half lands on completion). Returns (spool, nbytes, digest)."""
    import tempfile
    h = _relay_hasher(halgo)
    sp = tempfile.SpooledTemporaryFile(
        max_size=max(0, int(spool_mb)) * 1024 * 1024, dir=spool_dir)
    n = 0
    while True:
        data = fin.read(RELAY_CHUNK)
        if not data:
            break
        sp.write(data)
        if h is not None:
            h.update(data)
        n += len(data)
        if prog is not None:
            prog.update(len(data) // 2)
            prog.display()
    sp.seek(0)
    return sp, n, (h.hexdigest() if h else None)


def _cloud_relay_stream(args, src_spec, dst_spec):
    """Cross-provider/container object relay that STREAMS every object through
    a bounded per-object spool (CLOUD_RELAY_DESIGN.md §3–4) instead of landing
    the whole dataset in a local temp dir. Disk/memory use is O(objects in
    flight) — RAM up to --relay-spool-mb per object, overflow bounded by the
    largest in-flight object, never the dataset."""
    import tempfile
    src = make_backend(src_spec, args)
    dst = make_backend(dst_spec, args)
    banner(f"RELAY (streaming) — {CLOUD_SCHEME_NAMES[src_spec.scheme]} → "
           f"{CLOUD_SCHEME_NAMES[dst_spec.scheme]}")
    print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{args.source}{C.RESET}")
    print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{args.destination}{C.RESET}")

    objects = {k: v for k, v in src.list_objects(src_spec.prefix).items()
               if not k.endswith((CLOUD_MANIFEST_NAME,
                                  LEGACY_CLOUD_MANIFEST_NAME))}
    if not objects:
        print(f"  {C.YELLOW}No objects found under that prefix.{C.RESET}")
        return
    sp = src_spec.prefix.rstrip("/")
    dp = dst_spec.prefix.rstrip("/")

    src_manifest = {} if args.no_cache else _load_cloud_manifest(src, src_spec.prefix)
    dst_manifest = {} if args.no_cache else _load_cloud_manifest(dst, dst_spec.prefix)
    dst_sizes = {}
    for k, v in dst.list_objects(dst_spec.prefix).items():
        r = k[len(dp):].lstrip("/") if dp and k.startswith(dp) else k
        dst_sizes[r] = v["size"]

    # Single-threaded classify (mirrors _upload_to_cloud): skip / primary /
    # duplicate, BEFORE any byte moves. v1 dedup uses hashes known in advance
    # (source manifest); unknown-hash objects simply relay (design §4.3).
    new_manifest = {}
    primaries = []   # (key, rel, dkey, size, want_hash)
    dups = []        # (rel, primary_dkey, dkey, size, hash)
    skipped = errors = 0
    skip_bytes = 0
    first_dkey_for_hash = {}
    total_bytes = 0
    for key, info in sorted(objects.items()):
        rel = key[len(sp):].lstrip("/") if sp and key.startswith(sp) else key
        rel = rel.lstrip("/") or key.rsplit("/", 1)[-1]
        if _unsafe_rel(rel):
            errors += 1
            print(f"  {C.RED}Skipping unsafe key: {key}{C.RESET}")
            continue
        if _rel_excluded(rel, args.exclude):
            continue
        dkey = (dp + "/" + rel).lstrip("/") if dp else rel
        size = info["size"]
        total_bytes += size
        h = (src_manifest.get(rel) or {}).get("hash")
        prev = dst_manifest.get(rel)
        if (not args.overwrite and h and prev and prev.get("hash") == h
                and dst_sizes.get(rel) == size):
            skipped += 1
            skip_bytes += size
            new_manifest[rel] = {"size": size, "hash": h}
            continue
        if h and not args.no_dedup and h in first_dkey_for_hash:
            dups.append((rel, first_dkey_for_hash[h], dkey, size, h))
        else:
            primaries.append((key, rel, dkey, size, h))
            if h and not args.no_dedup:
                first_dkey_for_hash[h] = dkey
    print(f"  Objects: {C.BOLD}{len(objects)}{C.RESET} ({fmt_size(total_bytes)})"
          f"  ·  relay {len(primaries)}, dedup {len(dups)}, skip {skipped}")
    if args.dry_run:
        print(f"  {C.YELLOW}(dry run — nothing relayed){C.RESET}")
        return

    prog = Progress(total_bytes, len(objects))
    if skipped:
        prog.update(skip_bytes, skipped)
        prog.display()
    lock = threading.Lock()
    relayed = deduped = 0
    bytes_relayed = bytes_deduped = 0
    spool_mb = getattr(args, "relay_spool_mb", 64)
    spool_dir = tempfile.mkdtemp(prefix="blitcp_spool_")
    try:
        def _do_relay(item):
            nonlocal relayed, bytes_relayed, errors
            key, rel, dkey, size, want = item
            try:
                fin, _sz, smeta = src.open_read(key)
                try:
                    spool, n, digest = _spool_from_stream(
                        fin, spool_mb, spool_dir, _hash_name, prog)
                except Exception:
                    raise
                finally:
                    try:
                        fin.close()
                    except Exception:
                        pass
                try:
                    if want and digest and want != digest:
                        raise RuntimeError(
                            "source bytes do not match the source manifest "
                            "hash — refusing to propagate corruption")
                    meta = {"fc_relpath": _quote_rel(rel),
                            "fc_hash": digest or "",
                            "fc_hash_algo": _hash_name}
                    for mk in ("fc_mtime", "fc_mode", "fc_uid", "fc_gid"):
                        if smeta.get(mk):
                            meta[mk] = smeta[mk]
                    dst.upload_stream(spool, dkey, meta, n)
                finally:
                    spool.close()
                with lock:
                    relayed += 1
                    bytes_relayed += n
                    new_manifest[rel] = {"size": n, "hash": digest}
                    prog.update(size - size // 2, 1)
                    prog.display()
            except Exception as ex:
                msg = str(ex).strip().splitlines()[0] if str(ex).strip() \
                    else ex.__class__.__name__
                if os.environ.get("BLITCP_DEBUG"):
                    import traceback
                    traceback.print_exc()
                with lock:
                    errors += 1
                    print(f"\n  {C.RED}Error relaying {rel}: {msg}{C.RESET}")
                    prog.update(size, 1)
                    prog.display()

        workers = max(1, args.cloud_concurrency)
        # Phase A — stream primaries; uploads overlap later downloads.
        if primaries:
            with ThreadPoolExecutor(max_workers=workers) as pool:
                list(as_completed([pool.submit(_do_relay, it)
                                   for it in primaries]))
        # Phase B — duplicates via server-side copy on the destination.
        def _do_dup(item):
            nonlocal deduped, bytes_deduped, errors
            rel, pkey, dkey, size, h = item
            try:
                meta = {"fc_relpath": _quote_rel(rel), "fc_hash": h,
                        "fc_hash_algo": _hash_name}
                dst.server_side_copy(pkey, dkey, meta)
                with lock:
                    deduped += 1
                    bytes_deduped += size
                    new_manifest[rel] = {"size": size, "hash": h}
                    prog.update(size, 1)
                    prog.display()
            except Exception as ex:
                with lock:
                    errors += 1
                    print("\n  " + C.RED + _tr("Error copying {name}: {err}")
                          .format(name=rel, err=ex) + C.RESET)
                    prog.update(size, 1)
                    prog.display()

        if dups:
            with ThreadPoolExecutor(max_workers=workers) as pool:
                list(as_completed([pool.submit(_do_dup, it) for it in dups]))
        prog.finish()
    finally:
        shutil.rmtree(spool_dir, ignore_errors=True)

    if not args.no_cache:
        _save_cloud_manifest(dst, dst_spec.prefix, new_manifest)

    # Verify: the in-flight hash already compared against the source manifest;
    # sample the destination's metadata (real per-object metadata stores only —
    # SMB's head() answers from the manifest we just wrote, proving nothing).
    if not args.no_verify and relayed and dst.scheme != "smb":
        import random
        cand = [(r, m["hash"]) for r, m in new_manifest.items() if m.get("hash")]
        smp = random.sample(cand, min(20, len(cand)))
        print(f"  {C.DIM}Verifying {len(smp)} destination objects...{C.RESET}")
        bad = 0
        for r, hh in smp:
            m = dst.head((dp + "/" + r).lstrip("/") if dp else r)
            if not m or m.get("fc_hash") != hh:
                bad += 1
                print(f"  {C.RED}VERIFY MISMATCH: {r}{C.RESET}")
        if bad == 0:
            print(f"  {C.GREEN}✓ Verified {len(smp)} objects OK{C.RESET}")
        errors += bad

    banner("DONE")
    print(f"  Relayed:  {C.BOLD}{relayed}{C.RESET} ({fmt_size(bytes_relayed)})"
          f"  {C.DIM}streamed — no dataset temp dir{C.RESET}")
    if deduped:
        print(f"  Deduped:  {C.BOLD}{deduped}{C.RESET} via server-side copy "
              f"({C.GREEN}{fmt_size(bytes_deduped)} bandwidth saved{C.RESET})")
    if skipped:
        print(f"  Skipped:  {C.BOLD}{skipped}{C.RESET} unchanged (cross-run)")
    if errors:
        print(f"  {C.RED}Errors:   {errors}{C.RESET}")
    if args.log_file:
        write_log_file(args.log_file, {
            "source": args.source, "destination": args.destination,
            "mode": f"relay_{src.scheme}_{dst.scheme}",
            "total_files": len(objects), "copied": relayed, "linked": deduped,
            "skipped": skipped, "errors": errors, "total_bytes": total_bytes,
            "bytes_written": bytes_relayed, "dedup_saved": bytes_deduped,
            "hash_algo": _hash_name,
        })
    if errors:
        sys.exit(1)


def _cloud_to_cloud(args, src_spec, dst_spec):
    """Cloud→cloud. Same provider + same container → server-side copy; otherwise
    per-object streaming relay (_cloud_relay_stream)."""
    if (src_spec.scheme == dst_spec.scheme
            and src_spec.container == dst_spec.container
            and getattr(src_spec, "host", None) == getattr(dst_spec, "host", None)
            and src_spec.prefix.rstrip("/") == dst_spec.prefix.rstrip("/")):
        print(f"{C.RED}Error: source and destination are the same location.{C.RESET}")
        sys.exit(1)
    if (src_spec.scheme == dst_spec.scheme
            and src_spec.container == dst_spec.container
            and getattr(src_spec, "host", None) == getattr(dst_spec, "host", None)):
        backend = make_backend(src_spec, args)
        banner(f"COPY (server-side) — {CLOUD_SCHEME_NAMES[src_spec.scheme]}")
        objects = {k: v for k, v in backend.list_objects(src_spec.prefix).items()
                   if not k.endswith((CLOUD_MANIFEST_NAME, LEGACY_CLOUD_MANIFEST_NAME))}
        if not objects:
            print(f"  {C.YELLOW}No objects found under that prefix.{C.RESET}")
            return
        sp = src_spec.prefix.rstrip("/")
        dp = dst_spec.prefix.rstrip("/")
        copied = errors = 0
        prog = Progress(sum(v["size"] for v in objects.values()), len(objects))
        lock = threading.Lock()

        def _do_c2c(item):
            nonlocal copied, errors
            key, info = item
            rel = key[len(sp):].lstrip("/") if sp and key.startswith(sp) else key
            dst_key = (dp + "/" + rel).lstrip("/") if dp else rel
            try:
                if not args.dry_run:
                    meta = backend.head(key) or {}
                    backend.server_side_copy(key, dst_key, meta)
                with lock:
                    copied += 1
                    prog.update(info["size"], 1); prog.display()
            except Exception as ex:
                with lock:
                    errors += 1
                    print("\n  " + C.RED + _tr("Error copying {name}: {err}").format(name=key, err=ex) + C.RESET)
                    prog.update(info["size"], 1); prog.display()

        workers = max(1, getattr(args, "cloud_concurrency",
                                 DEFAULT_CLOUD_CONCURRENCY))
        with ThreadPoolExecutor(max_workers=workers) as pool:
            list(as_completed([pool.submit(_do_c2c, it)
                               for it in sorted(objects.items())]))
        prog.finish()
        banner("DONE")
        print(f"  Server-side copied: {C.BOLD}{copied}{C.RESET}")
        if errors:
            print(f"  {C.RED}Errors: {errors}{C.RESET}")
            sys.exit(1)
        return

    # Cross-provider / cross-container → per-object streaming relay
    # (bounded spool, nothing dataset-sized on the local disk).
    return _cloud_relay_stream(args, src_spec, dst_spec)


def _load_cloud_manifest(backend, prefix):
    # New sidecar key first, then the pre-rename one — a first blitcp run
    # against a bucket written by fast-copy must still see prior uploads.
    # Writes (_save_cloud_manifest) always use the new key.
    for name in (CLOUD_MANIFEST_NAME, LEGACY_CLOUD_MANIFEST_NAME):
        data = _load_cloud_manifest_key(
            backend, (prefix.rstrip("/") + "/" + name).lstrip("/"))
        if data:
            return data
    return {}


def _load_cloud_manifest_key(backend, key):
    import tempfile
    # mkstemp (not mktemp) creates the file atomically with an O_EXCL fd, closing
    # the TOCTOU window where an attacker could pre-plant a symlink at the path.
    fd, tmp = tempfile.mkstemp(prefix="fc_manifest_")
    os.close(fd)
    try:
        backend.download(key, tmp)
        with open(tmp, "r") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {}
        # Verify HMAC: an unsigned or tampered manifest is ignored, so a party
        # with write access to the bucket can't forge "already copied" entries
        # to make blitcp silently skip uploading those files.
        stored_mac = data.pop("__hmac__", None)
        if stored_mac is None:
            return {}
        payload = json.dumps(data, sort_keys=True).encode()
        expected = _hmac_mod.new(_manifest_key(), payload, hashlib.sha256).hexdigest()
        if not _hmac_mod.compare_digest(stored_mac, expected):
            return {}
        return data
    except Exception:
        return {}
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass


def _save_cloud_manifest(backend, prefix, manifest):
    key = (prefix.rstrip("/") + "/" + CLOUD_MANIFEST_NAME).lstrip("/")
    import tempfile
    fd, tmp = tempfile.mkstemp(prefix="fc_manifest_")
    os.close(fd)
    try:
        # Sign with the same per-user HMAC key the SSH manifest uses.
        signed = dict(manifest)
        payload = json.dumps(signed, sort_keys=True).encode()
        signed["__hmac__"] = _hmac_mod.new(
            _manifest_key(), payload, hashlib.sha256).hexdigest()
        with open(tmp, "w") as f:
            json.dump(signed, f)
        backend.upload(tmp, key, {"fc_relpath": _quote_rel(CLOUD_MANIFEST_NAME)})
    except Exception as ex:
        print(f"  {C.YELLOW}Warning: could not write manifest: {ex}{C.RESET}")
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass


def _verify_uploads(backend, prefix, entries, hashes, sample=20):
    import random
    candidates = [e for e in entries if hashes.get(e.rel)]
    if not candidates:
        return
    sample_entries = random.sample(candidates, min(sample, len(candidates)))
    print(f"  {C.DIM}Verifying {len(sample_entries)} uploaded objects...{C.RESET}")
    bad = 0
    for e in sample_entries:
        key = backend.join_key(prefix, e.rel)
        meta = backend.head(key)
        if not meta or meta.get("fc_hash") != hashes.get(e.rel):
            bad += 1
            print(f"  {C.RED}VERIFY MISMATCH: {e.rel}{C.RESET}")
    if bad == 0:
        print(f"  {C.GREEN}✓ Verified {len(sample_entries)} objects OK{C.RESET}")


def _ssh_ls(target, overrides=None, cli_port=22, cli_key=None, cli_password=False):
    """List a remote directory over SFTP. `target` is a user@host:/path string.
    `overrides` (from a saved SSH profile) supplies port/key/password and takes
    precedence over the CLI fallbacks. Returns an exit code."""
    if not _load_paramiko():
        print(f"{C.RED}Error: SSH listing requires paramiko. "
              f"Install: python -m pip install paramiko{C.RESET}")
        return 1
    remote = parse_remote_path(target)
    if not remote:
        print(f"{C.RED}Error: {target!r} is not a valid user@host:/path.{C.RESET}")
        return 1
    ov = overrides or {}
    port = ov.get("port") or cli_port or 22
    key = ov.get("key") or cli_key
    password = ov.get("password")
    if not password and cli_password:
        password = getpass.getpass(
            f"  SSH password for {remote.user}@{remote.host}: ")
    ssh = SSHConnection(remote, port=port, key_path=key, password=password,
                        sftp_only=(ov.get("protocol") == "sftp"))
    where = f"{remote.user}@{remote.host}:{remote.path}"
    try:
        ssh.connect()
        # SFTP first (sizes for free); when the server closes the sftp
        # subsystem — SSH on, SFTP off, a common NAS default — list over the
        # shell instead, exactly as the GUI's browser does. A connection saved
        # as "SFTP only" never touches the shell.
        try:
            kind, entries = _ssh_ls_via_sftp(ssh, remote.path)
        except Exception as sftp_err:
            if ssh.sftp_only:
                raise
            try:
                kind, entries = _ssh_ls_via_shell(ssh, remote.path)
            except Exception:
                raise sftp_err
    except SystemExit:
        raise
    except Exception as e:
        ssh.close()
        msg = _fmt_exc(e)
        low = msg.lower()
        if any(k in low for k in ("channel closed", "subsystem", "sftpclient")):
            msg = ("SFTP is not available on the SSH server and the shell "
                   "listing failed too. Enable SFTP (Synology: Control Panel "
                   "→ File Services → FTP → “Enable SFTP service”).")
        print(f"{C.RED}Error listing {where}: {msg}{C.RESET}")
        return 1
    try:
        if kind == "missing":
            print(f"{C.RED}Error: no such path: {where}{C.RESET}")
            return 1
        if kind == "file":
            e = entries[0]
            shown = fmt_size(e.st_size) if e.st_size is not None else ""
            print(f"    {shown:>10}  {remote.path}")
            return 0
        if not entries:
            print(f"  Empty directory: {where}")
            return 0
        # Directories first, then files, each sorted by name (like `ls`).
        entries.sort(key=lambda a: (0 if stat.S_ISDIR(a.st_mode) else 1, a.filename))
        files = sum(1 for a in entries if not stat.S_ISDIR(a.st_mode))
        sized = [a for a in entries if not stat.S_ISDIR(a.st_mode) and a.st_size is not None]
        total = sum(a.st_size for a in sized)
        print(f"  Entries in {where}:")
        for a in entries:
            is_dir = stat.S_ISDIR(a.st_mode)
            if is_dir:
                shown = "<DIR>"
            else:
                shown = fmt_size(a.st_size) if a.st_size is not None else ""
            name = a.filename + ("/" if is_dir else "")
            print(f"    {shown:>10}  {name}")
        plural = "entry" if len(entries) == 1 else "entries"
        if len(sized) == files:
            print(f"  {C.BOLD}{len(entries)} {plural}, {fmt_size(total)} "
                  f"in {files} file(s){C.RESET}")
        else:
            print(f"  {C.BOLD}{len(entries)} {plural}, {files} file(s){C.RESET} "
                  f"{C.DIM}(sizes unavailable: listed over the shell without "
                  f"GNU find){C.RESET}")
        return 0
    finally:
        ssh.close()


class _LsEntry:
    """The three attributes the `ls` printer reads, for shell-listed paths
    (paramiko's SFTPAttributes has the same names). st_size None = unknown."""
    __slots__ = ("filename", "st_mode", "st_size")

    def __init__(self, filename, is_dir, size=None):
        self.filename = filename
        self.st_mode = stat.S_IFDIR if is_dir else stat.S_IFREG
        self.st_size = size


def _ssh_ls_via_sftp(ssh, path):
    """Returns (kind, entries): kind is 'dir' | 'file' | 'missing'; entries are
    SFTPAttributes for a dir, a one-element list for a file. Raises when the
    server has no usable SFTP subsystem."""
    sftp = ssh.open_sftp()
    # Stat first so we give an accurate message: a regular file is listed
    # like `ls file`, a missing path says so, only directories are walked.
    try:
        st = sftp.stat(path)
    except IOError:
        return "missing", []
    if not stat.S_ISDIR(st.st_mode):
        return "file", [_LsEntry(path, False, st.st_size or 0)]
    return "dir", list(sftp.listdir_attr(path))


def _ssh_ls_via_shell(ssh, path):
    """Same contract as _ssh_ls_via_sftp, over the exec channel. With GNU find
    the sizes come along; otherwise `ls -1ApL` gives names only (size None)."""
    import shlex
    q = shlex.quote(path)
    out, err, rc = ssh.exec_cmd(
        f"if [ -d {q} ]; then echo D; elif [ -e {q} ]; then echo F; "
        f"wc -c < {q}; else echo M; fi", timeout=30)
    head = out.strip().splitlines() or [""]
    if head[0] == "M":
        return "missing", []
    if head[0] == "F":
        try:
            size = int(head[1].strip()) if len(head) > 1 else None
        except ValueError:
            size = None
        return "file", [_LsEntry(path, False, size)]
    if head[0] != "D":
        raise OSError(err.strip() or f"unexpected reply: {out.strip()[:80]!r}")
    entries = []
    if ssh.caps.get("gnu_find"):
        out, err, rc = ssh.exec_cmd(
            f"LC_ALL=C find -L {q} -mindepth 1 -maxdepth 1 "
            f"-printf '%y\\t%s\\t%f\\n' 2>/dev/null", timeout=60)
        if rc == 0:
            for line in out.splitlines():
                parts = line.split("\t", 2)
                if len(parts) != 3:
                    continue
                kind, size, name = parts
                if not name or name in (".", ".."):
                    continue
                try:
                    sz = int(size)
                except ValueError:
                    sz = None
                entries.append(_LsEntry(name, kind == "d", None if kind == "d" else sz))
            return "dir", entries
    out, err, rc = ssh.exec_cmd(f"LC_ALL=C ls -1ApL -- {q}", timeout=60)
    if rc != 0:
        raise OSError(err.strip() or f"ls exited {rc}")
    for line in out.splitlines():
        nm = line.rstrip("\r")
        if not nm or nm in ("./", "../", ".", ".."):
            continue
        if nm.endswith("/"):
            entries.append(_LsEntry(nm[:-1], True))
        else:
            entries.append(_LsEntry(nm, False))
    return "dir", entries


def cloud_ls(argv):
    """`blitcp ls <connection[:folder] | scheme://bucket/prefix | user@host:/path>`
    — list objects in a cloud location, or files in a remote SSH directory, from
    the terminal. Returns an exit code."""
    if not argv or argv[0] in ("-h", "--help", "help"):
        print("Usage: blitcp ls <connection[:folder] | s3://bucket/prefix | user@host:/path>\n"
              "  List objects under a cloud location, or files in a remote SSH directory.\n"
              "  Cloud: a saved cloud connection name, or an s3:// / az:// / gs:// URL.\n"
              "  SSH:   a saved ssh connection name, or a user@host:/path\n"
              "         (via SFTP; over the shell when the server has SFTP off).\n"
              "  Examples:\n"
              "    blitcp ls aws_fastcopies\n"
              "    blitcp ls gcs_fastcopies:backup\n"
              "    blitcp ls s3://bucket/prefix --credentials-file FILE\n"
              "    blitcp ls user@host:/var/log --ssh-key ~/.ssh/id_ed25519\n"
              "  Encrypted creds: set BLITCP_CREDS_PASSPHRASE or run in a terminal.")
        return 0
    target, cred_file = None, None
    ssh_port, ssh_key, ssh_password = 22, None, False
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("--credentials-file", "--credentials"):
            cred_file = argv[i + 1] if i + 1 < len(argv) else None
            i += 2
            continue
        if a in ("--ssh-port", "--port"):
            val = argv[i + 1] if i + 1 < len(argv) else ""
            if not val.isdigit():
                print(f"{C.RED}Error: --ssh-port needs a number.{C.RESET}")
                return 1
            ssh_port = int(val)
            i += 2
            continue
        if a in ("--ssh-key", "--key"):
            ssh_key = argv[i + 1] if i + 1 < len(argv) else None
            i += 2
            continue
        if a in ("--ssh-password", "--password"):
            ssh_password = True
            i += 1
            continue
        if a == "--ssh-strict-host-key-checking":
            global _strict_host_keys
            _strict_host_keys = True
            i += 1
            continue
        if target is None and not a.startswith("-"):
            target = a
        i += 1
    if not target:
        print(f"{C.RED}Error: 'ls' needs a connection name, cloud URL, "
              f"or user@host:/path.{C.RESET}")
        return 1
    ns = argparse.Namespace(credentials_file=cred_file)
    spec = parse_cloud_url(target) or parse_smb_url(target)
    if spec is None:
        # Only open/unlock the credentials file when the target actually looks
        # like a saved-profile name. A bare user@host:/path is listed directly
        # over SSH and must never trigger a creds-file passphrase prompt.
        if _looks_like_profile_ref(target):
            conns = _conns_for_named_endpoints(ns)
            new, overrides = resolve_named_endpoint(target, conns) if conns else (None, None)
            if new:
                obj_spec = parse_object_url(new)
                if obj_spec is not None:
                    if overrides and "smb" in overrides:
                        _stash_smb_creds(ns, overrides["smb"])
                    spec = obj_spec
                else:  # resolved to an SSH endpoint
                    return _ssh_ls(new, overrides, ssh_port, ssh_key, ssh_password)
        elif parse_remote_path(target):
            # A bare user@host:/path SSH target — no creds file involved.
            return _ssh_ls(target, None, ssh_port, ssh_key, ssh_password)
    if spec is None or spec.scheme not in ("s3", "az", "gs", "smb"):
        print(f"{C.RED}Error: {target!r} is not a cloud connection/URL "
              f"(s3://, az://, gs://), an smb:// / UNC share, or an SSH path "
              f"(user@host:/path).{C.RESET}")
        return 1
    try:
        backend = make_backend(spec, ns)
        objs = backend.list_objects(spec.prefix or "")
    except SystemExit:
        raise
    except Exception as e:
        print(f"{C.RED}Error listing {spec.scheme}://{spec.container}/"
              f"{spec.prefix or ''}: {e}{C.RESET}")
        return 1
    # Hide blitcp's own manifest sidecar from the listing.
    keys = sorted(k for k in objs if not k.endswith((REMOTE_MANIFEST_NAME, LEGACY_REMOTE_MANIFEST_NAME)))
    if spec.scheme == "smb":
        where = f"smb://{getattr(spec, 'host', '')}/{spec.container}/{spec.prefix or ''}"
    else:
        where = f"{spec.scheme}://{spec.container}/{spec.prefix or ''}"
    if not keys:
        print(f"  No objects in {where}")
        return 0
    total = 0
    print(f"  Objects in {where}:")
    for k in keys:
        sz = objs[k].get("size", 0) or 0
        total += sz
        print(f"    {fmt_size(sz):>10}  {k}")
    print(f"  {C.BOLD}{len(keys)} object(s), {fmt_size(total)}{C.RESET}")
    return 0


# ════════════════════════════════════════════════════════════════════════════
# SSH-ONLY TRANSPORT (tar over the SSH exec channel — no SFTP subsystem)
# ════════════════════════════════════════════════════════════════════════════
# For servers that have SSH enabled but SFTP disabled (common on NAS appliances
# like Synology). This is a plain recursive copy — no dedup / incremental /
# verify — but it works wherever a shell + tar exist on the remote.

def _ssh_auth_diagnosis(spec, key_path=None, password=None):
    """What this process actually offered the server, and how to give it more.

    "No authentication methods available" is the symptom; it names neither the
    key files that were looked for, nor whether an agent was running, nor
    which credentials file was consulted, nor that --ssh-*-key and
    --ssh-*-password exist. Everything here is read from the state the
    connection really used — nothing is assumed, and the credentials file is
    NOT opened (an encrypted one would prompt, from an error path)."""
    tried = []
    if key_path:
        kp = os.path.expanduser(key_path)
        tried.append("%s (%s)" % (kp, "found" if os.path.isfile(kp) else "missing"))
    else:
        # The same files paramiko's look_for_keys walks, under this process's
        # own HOME — which is what makes an isolated HOME fail here.
        ssh_dir = os.path.join(os.path.expanduser("~"), ".ssh")
        names = ["id_rsa", "id_ecdsa", "id_ed25519", "id_dsa"]
        present = [n for n in names if os.path.isfile(os.path.join(ssh_dir, n))]
        tried.append("default keys in %s (%s)"
                     % (ssh_dir, ", ".join(present) if present else "none found"))
    sock = os.environ.get("SSH_AUTH_SOCK")
    tried.append("ssh-agent (%s)" % ("SSH_AUTH_SOCK=" + sock if sock
                                     else "not running"))
    if password:
        tried.append("a supplied password")
    else:
        try:
            cred = default_credentials_path()
        except Exception:                                       # noqa: BLE001
            cred = "the credentials file"
        tried.append("saved connection for host %s (searched %s%s)"
                     % (spec.host, cred,
                        "" if os.path.isfile(cred) else " — no such file"))
    return ("no usable credentials for %s@%s:%s. Tried: %s. Provide one with "
            "--ssh-dst-key / --ssh-src-key, --ssh-dst-password / "
            "--ssh-src-password, or a saved connection (blitcp creds add; set "
            "BLITCP_CREDS_PASSPHRASE for an encrypted file)."
            % (spec.user, spec.host, spec.port, "; ".join(tried)))


def _is_auth_failure(exc):
    txt = str(exc).lower()
    return ("authentication" in txt or "no authentication methods" in txt
            or type(exc).__name__ == "AuthenticationException")


def _tar_ssh_connect(spec, key_path, password, compress):
    cli = paramiko.SSHClient()
    try:
        cli.load_system_host_keys()
    except Exception:
        pass
    kh = _user_known_hosts_path()
    if os.path.isfile(kh):
        try:
            cli.load_host_keys(kh)
        except Exception:
            pass
    cli.set_missing_host_key_policy(
        paramiko.RejectPolicy() if _strict_host_keys else _InteractiveHostKeyPolicy())
    kw = dict(hostname=spec.host, port=spec.port, username=spec.user,
              timeout=15, compress=compress)
    if key_path:
        kw["key_filename"] = os.path.expanduser(key_path)
    if password:
        kw["password"] = password
    try:
        cli.connect(**kw)
    except Exception as e:                                      # noqa: BLE001
        # Enriched HERE, at the one place that knows what was offered, so all
        # three reporting sites print the same full sentence without each
        # having to rebuild it.
        if _is_auth_failure(e):
            raise type(e)(_ssh_auth_diagnosis(spec, key_path, password)) from None
        raise
    tr = cli.get_transport()
    if tr:
        tr.set_keepalive(15)
    return cli


def _sftp_subsystem_ok(spec, key_path, password, compress):
    """Whether the server actually offers the SFTP subsystem: (available, err).

    SSH on / SFTP off is a common NAS and managed-gateway default, and every
    SFTP call in the copy path is made deep inside a transfer — the first one
    lands after the scan, so without this the run dies halfway with a bare
    "Channel closed." Probing once, before the transport is chosen, is what
    lets the whole copy switch to tar-over-exec instead.

    A probe that cannot even connect returns available=True with the error:
    the caller must leave routing alone and let the real connection report an
    auth or network failure properly, rather than silently taking a fallback
    for a problem that has nothing to do with SFTP."""
    cli = None
    try:
        cli = _tar_ssh_connect(spec, key_path, password, compress)
    except Exception as e:                                  # noqa: BLE001
        return True, e
    try:
        sf = cli.open_sftp()
        try:
            sf.close()
        except Exception:
            pass
        return True, None
    except Exception:                                       # noqa: BLE001
        # Silent by default — the chosen transport is named in the banner. But
        # a probe that decides this wrongly would otherwise be undebuggable,
        # so the reason stays reachable through the usual escape hatch.
        if _env("TRACEBACK"):
            import traceback as _tb
            print(_tb.format_exc().rstrip())
        return False, None
    finally:
        try:
            cli.close()
        except Exception:
            pass


def _tar_emit(done, total, files_done, files_total, start, final=False):
    """Emit a progress event compatible with the --progress-json consumer."""
    el = time.time() - start
    sp = done / el if el > 0 else 0
    if PROGRESS_JSON:
        evt = {"t": "done" if final else "progress",
               "pct": round(min(100.0, done / total * 100) if total
                            else (100.0 if final else 0.0), 2),
               "bytes_done": done, "bytes_total": total or done, "speed_bps": sp,
               "files_done": files_done, "files_total": files_total}
        if final:
            evt["elapsed_s"] = el
        else:
            evt["eta_s"] = max(0.0, (total - done) / sp) if (total and sp > 0) else 0
        sys.stdout.write(json.dumps(evt) + "\n")
        sys.stdout.flush()
    elif total:
        pct = min(100.0, done / total * 100)
        sys.stdout.write(f"\r  {fmt_size(done)}/{fmt_size(total)}  {pct:5.1f}%  "
                         f"{fmt_speed(sp)}   ")
        sys.stdout.flush()


def _verify_emit(done, total):
    """Progress event for the verify phase — the GUI switches the bar/label to
    'Verifying…' and shows how many files have been verified."""
    if PROGRESS_JSON:
        # Leading \n: the 'Verifying N files…' print uses end="" (no newline), so
        # the JSON must start its own line or the GUI shows it raw.
        sys.stdout.write("\n" + json.dumps({
            "t": "verify", "files_done": done, "files_total": total,
            "pct": round(min(100.0, done / total * 100) if total else 100.0, 2),
        }) + "\n")
        sys.stdout.flush()


_PHASE_T0 = {}  # phase name → start time, for the files/sec rate


def _phase_emit(phase, done, total, bytes_done=None, bytes_total=None):
    """Progress for a pre-copy phase (hashing / indexing / mapping / linking).
    Under --progress-json the GUI labels its header with `phase`, shows the live
    N/total AND the files/sec rate — so a long pass reads 'Hashing… 300/3653 ·
    1.2k/s' instead of a stuck 'Copying… 0/0'. The plain CLI prints the same.

    When bytes_total is given (hashing large files), the PERCENTAGE is driven by
    bytes so the bar tracks real work — a few multi-GB files no longer sit at a
    frozen 0% just because the file COUNT barely moved. The N/total file count is
    still reported for the header label."""
    now = time.time()
    t0 = _PHASE_T0.setdefault(phase, now)
    el = now - t0
    rate = done / el if el > 0 else 0.0
    # bytes/sec — the meaningful metric when hashing large files (files/s looks
    # "slow" at 10/s while the disk is actually reading at its full throughput).
    # Byte-driven percentage only when BOTH byte counts are present — a caller
    # passing bytes_total without bytes_done would otherwise hit None/int.
    _have_bytes = bytes_total and bytes_done is not None
    brate = (bytes_done / el if (_have_bytes and el > 0) else 0.0)
    if _have_bytes:
        pct = min(100.0, bytes_done / bytes_total * 100)
    else:
        pct = min(100.0, done / total * 100) if total else 0.0
    if PROGRESS_JSON:
        # Leading \n: a preceding 'Creating N links…' / 'Indexing …' print uses
        # end="" (no newline) for the CLI's \r overlay, so the JSON must start its
        # own line or it concatenates onto that text and the GUI shows it raw.
        sys.stdout.write("\n" + json.dumps({
            "t": "phase", "phase": phase, "files_done": done,
            "files_total": total, "rate": round(rate, 1),
            "bytes_rate": round(brate, 1),
            "pct": round(pct, 2),
        }) + "\n")
        sys.stdout.flush()
    elif total:
        extra = (f" · {pct:.0f}% ({fmt_size(bytes_done)}/{fmt_size(bytes_total)}) "
                 f"{fmt_speed(brate)}" if _have_bytes else "")
        sys.stdout.write(f"\r  {C.DIM}{phase}... {done}/{total} "
                         f"({rate:,.0f}/s){extra}{C.RESET}   ")
        sys.stdout.flush()
    else:
        # Unknown total (a discovery walk) — show the running count + rate.
        sys.stdout.write(f"\r  {C.DIM}{phase}... {done} ({rate:,.0f}/s){C.RESET}   ")
        sys.stdout.flush()


class _TarReadCounter:
    """Wraps a paramiko stdout stream, counting bytes + emitting progress."""

    def __init__(self, f, total, files_total, start):
        self.f, self.total, self.files_total, self.start = f, total, files_total, start
        self.n, self._last = 0, 0
        self.files_done = 0          # updated by _tar_extract_stream as files land

    def read(self, size):
        b = self.f.read(size)
        self.n += len(b)
        if self.n - self._last >= 2 * 1024 * 1024:
            self._last = self.n
            _tar_emit(self.n, self.total, self.files_done, self.files_total, self.start)
        return b


class _TarWriteCounter:
    def __init__(self, f, total, files_total, start):
        self.f, self.total, self.files_total, self.start = f, total, files_total, start
        self.n, self._last = 0, 0
        self.files_done = 0          # updated by the push loop as files are added

    def write(self, data):
        self.f.write(data)
        self.n += len(data)
        if self.n - self._last >= 2 * 1024 * 1024:
            self._last = self.n
            _tar_emit(self.n, self.total, self.files_done, self.files_total, self.start)
        return len(data)

    def flush(self):
        try:
            self.f.flush()
        except Exception:
            pass


def _tar_extract_stream(reader, dst):
    """Extract a pulled tar stream. The stream comes from an UNTRUSTED remote.

    This used to call tf.extract() directly, so nothing in this file checked
    the member names: no traversal check, no symlink/device/hard-link refusal,
    no symlinked-ancestor check, and no setuid/setgid strip on content the far
    side chose. The only thing standing behind it was tarfile's own filter,
    which is a backstop and not ours — and the `except TypeError` fallback
    below it extracted with no filter at all, which on every interpreter up to
    3.13 means fully_trusted (measured: a member named '../x' lands above the
    destination).

    It goes through _safe_tar_extract now, like the other two pull paths, with
    trusted_source=False so remote-supplied setuid bits are stripped rather
    than honoured — under --use-sudo the extracted file is root-owned.

    Returns (delivered, rejected). The rejected count is not decoration: the
    first version of this printed each refusal and returned only the delivered
    count, so the caller could not tell a clean transfer from one where every
    member was refused. That is the same defect as reporting "verified" for a
    check that did not run, rebuilt inside the fix for it.
    """
    done = 0
    errors = 0
    ctx = _ExtractCtx(dst)
    with tarfile.open(fileobj=reader, mode="r|") as tf:
        for m in tf:
            result = _safe_tar_extract(tf, m, dst, trusted_source=False, ctx=ctx)
            if result is not True:
                errors += 1
                print(f"\n  {C.YELLOW}Skipped: {m.name}: {result}{C.RESET}")
                # Every string _safe_tar_extract returns is a policy refusal
                # ("blocked: …"); a real I/O failure comes out as an exception.
                # So this goes to the ONE refusal list the summary and the exit
                # code read, exactly like the local engines. Keeping a private
                # count here and nowhere else is why the pull's summary said
                # "0 refused" and then accused its own arithmetic.
                _note_refusal(m.name)
                _log("refused", m.name, getattr(m, "size", 0),
                     error="refused: %s" % result)
                continue
            if not m.isdir():
                done += 1
                # The record gets a line per file here, like every other
                # engine: a record whose only entries are the refusals cannot
                # answer "which files did this run actually write".
                _log("copied", m.name, getattr(m, "size", 0),
                     method="tar_stream")
                # let the byte-progress emitter report the running file count
                if hasattr(reader, "files_done"):
                    reader.files_done = done
    return done, errors


def _ssh_run(cli, cmd, timeout=1800):
    _i, o, e = cli.exec_command(cmd, timeout=timeout)
    out = o.read().decode("utf-8", "replace")
    err = e.read().decode("utf-8", "replace")
    return out, err, o.channel.recv_exit_status()


def _resolved_dst_pw(args):
    if args.ssh_password_env:
        return os.environ.get(args.ssh_password_env)
    return getattr(args, "_resolved_dst_password", None)


def _resolved_src_pw(args):
    if args.src_password_env:
        return os.environ.get(args.src_password_env)
    return getattr(args, "_resolved_src_password", None)


def _hash_local_file(path, algo, buf=4 * 1024 * 1024):
    # xxh128 isn't in hashlib — use the engine's xxhash hasher so local digests
    # match both the remote xxh128sum and the L2L block-order copy.
    h = new_hasher() if algo == "xxh128" else hashlib.new(algo)
    with open(path, "rb") as f:
        while True:
            b = f.read(buf)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


class _SshExecWriter:
    """Write handle backed by `cat > path` on an exec channel — the SFTP-free
    stand-in for sftp.open(path, "wb").

    A destination saved as protocol 'ssh' (or given --ssh-no-sftp) is one where
    the SFTP subsystem is off or unreachable, so opening an SFTP handle there
    dies with a bare "Channel closed." Exposes just the write()/close() surface
    _http_pump needs, and turns a non-zero remote exit into the shell's own
    stderr rather than a silent short file."""

    def __init__(self, cli, path):
        self.path = path
        self._in, self._out, self._err = cli.exec_command(
            "cat > %s" % shlex.quote(path))
        self._chan = self._in.channel
        self._closed = False

    def write(self, data):
        self._chan.sendall(data)

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            self._chan.shutdown_write()
        except Exception:
            pass
        rc = self._out.channel.recv_exit_status()
        err = self._err.read().decode("utf-8", "replace").strip()
        if rc:
            raise IOError("remote write to %s failed (exit %d)%s"
                          % (self.path, rc, ": " + err if err else ""))


def _ssh_exec_stat(cli, path):
    """('dir'|'file'|None, size, mtime) for a remote path over plain SSH.

    One round trip standing in for sftp.stat(): the caller needs the same three
    answers (is it a directory, how big, how old) and an exec-only destination
    has no other way to ask. mtime falls back to 0 where neither GNU nor BSD
    stat exists — the up-to-date check treats 0 as 'unknown' and compares sizes."""
    q = shlex.quote(path)
    cmd = ('if [ -d %s ]; then echo "D 0 0"; elif [ -e %s ]; then '
           'echo "F $(wc -c < %s 2>/dev/null || echo 0) '
           '$(stat -c %%Y %s 2>/dev/null || stat -f %%m %s 2>/dev/null || echo 0)"; '
           'else echo "N 0 0"; fi') % (q, q, q, q, q)
    out, _e, rc = _ssh_run(cli, cmd, timeout=60)
    parts = out.split()
    if rc != 0 or len(parts) < 3:
        return None, 0, 0
    kind = {"D": "dir", "F": "file"}.get(parts[0])
    try:
        return kind, int(parts[1]), float(parts[2])
    except ValueError:
        return kind, 0, 0.0


def _ssh_exec_caps(cli, dest_dir):
    """Detect what the remote can do over plain SSH: a hash tool, GNU find
    -printf, and (in dest_dir) hardlink/symlink support."""
    caps = {"hash": None, "halgo": None, "hashes": {}, "hardlink": False,
            "symlink": False, "find_printf": False}
    # Prefer the remote tool whose digest matches the LOCAL hash, so the dedup DB
    # is shared with L2L. xxh128sum is byte-identical to Python's xxhash; fall
    # back to sha256/md5 when the remote doesn't have it.
    candidates = [("sha256sum", "sha256"), ("md5sum", "md5")]
    if _hash_name == "xxh128":
        candidates = [("xxh128sum", "xxh128"), ("xxhsum -H2", "xxh128")] + candidates
    # Record EVERY tool this host has, not just its favourite. Two hosts can
    # each have a first choice the other lacks while sharing a perfectly good
    # second one — see _common_hash_algo.
    for tool, algo in candidates:
        o, _e, rc = _ssh_run(cli, "command -v " + shlex.quote(tool.split()[0]))
        if rc == 0 and o.strip():
            caps["hashes"].setdefault(algo, tool)
            if caps["hash"] is None:
                caps["hash"], caps["halgo"] = tool, algo
    o, _e, rc = _ssh_run(cli, "cd / && find . -maxdepth 0 -printf x 2>/dev/null")
    caps["find_printf"] = (rc == 0 and "x" in o)
    q = shlex.quote(dest_dir)
    test = ("mkdir -p %s && cd %s && : > .fc_a 2>/dev/null && "
            "{ ln .fc_a .fc_h 2>/dev/null && echo HL; }; "
            "{ ln -s .fc_a .fc_s 2>/dev/null && echo SL; }; "
            "rm -f .fc_a .fc_h .fc_s") % (q, q)
    o, _e, _rc = _ssh_run(cli, test)
    toks = o.split()
    caps["hardlink"], caps["symlink"] = ("HL" in toks), ("SL" in toks)
    return caps


def _common_hash_algo(scaps, dcaps):
    """Best hash algorithm BOTH remotes can run, or None.

    Comparing each side's first choice was wrong: a NAS with only sha256sum
    and a workstation with xxh128sum installed each picked a different
    favourite, the two did not match, and a pair of hosts that both had
    sha256sum AND md5sum was told it had "no common tool" — which silently
    turned off deduplication and, worse, verification."""
    pref = ["xxh128", "sha256", "md5"] if _hash_name == "xxh128" \
        else ["sha256", "xxh128", "md5"]
    have_s, have_d = scaps.get("hashes") or {}, dcaps.get("hashes") or {}
    for algo in pref:
        if algo in have_s and algo in have_d:
            return algo
    return None


def _ssh_remote_listing(cli, root, caps):
    """{relpath: (size, mtime)} for every file under root (relpath has no ./)."""
    res = {}
    q = shlex.quote(root)
    if caps["find_printf"]:
        o, _e, rc = _ssh_run(
            cli, "cd %s 2>/dev/null && find . -type f -printf '%%s\\t%%T@\\t%%P\\n'" % q)
        if rc == 0:
            for line in o.splitlines():
                p = line.split("\t", 2)
                if len(p) == 3:
                    try:
                        res[p[2]] = (int(p[0]), float(p[1]))
                    except ValueError:
                        pass
            return res
    # portable fallback (busybox): find + wc -c (slower, no mtime)
    o, _e, rc = _ssh_run(
        cli, "cd %s 2>/dev/null && find . -type f | while IFS= read -r f; do "
             "printf '%%s\\t%%s\\n' \"$(wc -c < \"$f\")\" \"${f#./}\"; done" % q)
    if rc == 0:
        for line in o.splitlines():
            p = line.split("\t", 1)
            if len(p) == 2:
                try:
                    res[p[1]] = (int(p[0]), 0.0)
                except ValueError:
                    pass
    return res


def _ssh_remote_hashes(cli, root, rels, caps):
    """{relpath: hexdigest} computed on the remote via its hash tool."""
    res = {}
    if not caps["hash"] or not rels:
        return res
    q = shlex.quote(root)
    rels = list(rels)
    for i in range(0, len(rels), 100):
        files = " ".join(shlex.quote(r) for r in rels[i:i + 100])
        o, _e, _rc = _ssh_run(cli, "cd %s && %s %s 2>/dev/null" % (q, caps["hash"], files))
        for line in o.splitlines():
            m = re.match(r"([0-9a-fA-F]{8,})\s+\*?(.*)", line)
            if m:
                res[m.group(2)] = m.group(1).lower()
    return res


def _ssh_remote_free(cli, path):
    """(total, free) bytes for the filesystem holding `path` on the remote, via
    df. Walks up to an existing parent. Returns (None, None) if df is unusable."""
    check = path or "/"
    for _ in range(12):
        o, _e, rc = _ssh_run(
            cli, "df -kP %s 2>/dev/null || df -k %s 2>/dev/null"
            % (shlex.quote(check), shlex.quote(check)))
        lines = [l for l in o.strip().splitlines() if l.strip()]
        if rc == 0 and len(lines) >= 2:
            parts = lines[-1].split()
            try:
                return int(parts[1]) * 1024, int(parts[3]) * 1024
            except (IndexError, ValueError):
                return None, None
        parent = posixpath.dirname(check.rstrip("/"))
        if not parent or parent == check:
            break
        check = parent
    return None, None


def _print_space_block(total, free, required, force):
    """Shared Total/Free/Required/Headroom block (matches the SFTP/local modes)."""
    if total:
        print("  " + _tr("Destination disk:"))
        print(f"    {_pad(_tr('Total:'), 11)}{C.BOLD}{fmt_size(total)}{C.RESET}")
        print(f"    Free:      {C.BOLD}{fmt_size(free)}{C.RESET} "
              f"({free / total * 100:.1f}% free)")
    else:
        print(f"  Destination free: {C.BOLD}{fmt_size(free)}{C.RESET}")
    print(f"    Required:  {C.BOLD}{fmt_size(required)}{C.RESET}")
    if required > free:
        print(f"\n  {C.RED}✗ NOT ENOUGH SPACE — need {fmt_size(required - free)} "
              f"more{C.RESET}")
        if force:
            print(f"  {C.YELLOW}Proceeding anyway (--force){C.RESET}")
            return True
        return False
    print(f"    Headroom:  {fmt_size(free - required)}")
    print("\n  " + C.GREEN + "✓ " + _tr("Enough space") + C.RESET)
    return True


def _check_space_remote(cli, path, required, force):
    total, free = _ssh_remote_free(cli, path)
    if free is None:
        print("  " + C.YELLOW + _tr("Could not check destination free space — continuing") + C.RESET)
        return True
    return _print_space_block(total, free, required, force)


def _check_space_local(dst, required, force):
    try:
        target = dst if os.path.isdir(dst) else (os.path.dirname(dst) or ".")
        usage = shutil.disk_usage(target)
    except OSError:
        return True
    return _print_space_block(usage.total, usage.free, required, force)


def _ssh_tar_send(cli, cwd, rels):
    """Run `tar c` of an explicit file list on the remote, feeding the list via
    stdin (`-T -`) so it isn't limited by the SSH exec command-line length
    (thousands of files). Returns (stdout, stderr) streams for the archive."""
    stdin, out, err = cli.exec_command("cd %s && tar cf - -T -" % shlex.quote(cwd))
    data = ("\n".join(rels) + "\n").encode("utf-8")

    def _feed():
        try:
            stdin.write(data)
            stdin.flush()
        except Exception:
            pass
        finally:
            try:
                stdin.channel.shutdown_write()
            except Exception:
                pass

    threading.Thread(target=_feed, daemon=True).start()
    return out, err


_SummaryTotals = namedtuple(
    "_SummaryTotals",
    "copied linked refused bytes_written bytes_refused bytes_deduped")


def _refused_rel_size(rel, size_by_rel, link_map):
    """Logical size of a refused file, or None when it cannot be known.

    A refused COPY is in size_by_rel. A refused LINK is not — its size is its
    canonical's, which is either another entry in this run or, for a cross-run
    dedup match, a file already on disk. None means "do not guess": the byte
    arithmetic below is skipped rather than reported wrong, because a summary
    that invents a number is the thing this whole change exists to stop.
    """
    if rel in size_by_rel:
        return size_by_rel[rel]
    target = (link_map or {}).get(rel)
    if isinstance(target, str):
        return size_by_rel.get(target)
    if isinstance(target, tuple) and target[0] == "__abs__":
        try:
            return os.path.getsize(target[1])
        except OSError:
            return None
    return None


def _print_files_summary(total_files, copy_entries, link_map,
                         skipped_count=0, forecast=None, byte_totals=None):
    """Print the DONE summary's Files line, and make it check itself.

    ONE READER. The counts come from _REFUSED_PATHS and from nothing else: a
    rel on that list is neither copied nor linked, whichever engine refused
    it. Subtracting a total from a total — what this used to do — cannot work
    when the refusals came from the link loop and the subtraction was applied
    to the copy list, which is how a run that refused five files reported
    "1 copied + 4 linked, 1 refused".

    Returns the numbers it printed, so the Data line, the sudo audit file and
    the --log JSON report the same run this line describes instead of each
    recomputing it from len().

    THREE SELF-CHECKS, because numbers printed on the same screen are not
    compared by anyone:

      copied + linked + refused + skipped == total
          Every file in the run is in exactly one of those buckets. If the
          arithmetic does not close, the summary says so instead of printing
          a total it cannot justify.

      written + refused + skipped + deduped == total bytes
          The same closure over bytes, for the same reason: "Data: 17 B
          written" for a run that wrote 4 B is the file-count bug in another
          unit. Pass byte_totals=(total, saved, skipped) to enable it;
          it is skipped, not guessed, when a refused file's size is unknown.

      forecast == refused
          Phase 3 predicts how many files the destination policy will refuse;
          this is what it actually refused. The prediction and the result are
          produced by different code from the same policy, so a disagreement
          means one of them is wrong — and nothing else in the run would
          notice. Pass forecast=None where no prediction was made.
    """
    refused = set(_REFUSED_PATHS)
    size_by_rel = {e.rel: e.size for e in copy_entries}
    copied = linked = 0
    bytes_written = bytes_refused_copies = 0
    for e in copy_entries:
        if e.rel in refused:
            bytes_refused_copies += e.size
        else:
            copied += 1
            bytes_written += e.size
    bytes_refused_links = 0
    unknown_size = False
    for rel in (link_map or {}):
        if rel not in refused:
            linked += 1
            continue
        sz = _refused_rel_size(rel, size_by_rel, link_map)
        if sz is None:
            unknown_size = True
        else:
            bytes_refused_links += sz
    n_refused = len(refused)

    bits = []
    if link_map or n_refused:
        bits.append(f"{copied} copied + {linked} linked")
    if n_refused:
        bits.append(_tr("{n} refused").format(n=n_refused))
    print(f"  Files:   {C.BOLD}{total_files}{C.RESET} total"
          + (f" ({', '.join(bits)})" if bits else ""))

    if copied + linked + n_refused + skipped_count != total_files:
        print(f"  {C.YELLOW}Note:    these numbers do not add up: "
              f"{copied} copied + {linked} linked + {n_refused} refused + "
              f"{skipped_count} skipped = "
              f"{copied + linked + n_refused + skipped_count}, "
              f"not {total_files}. One of them is wrong — treat the run as "
              f"unreported, not as done.{C.RESET}")

    bytes_refused = bytes_refused_copies + bytes_refused_links
    bytes_deduped = 0
    if byte_totals is not None:
        total_bytes, saved_bytes, skipped_bytes = byte_totals
        bytes_deduped = saved_bytes - bytes_refused_links
        if not unknown_size:
            closed = (bytes_written + bytes_refused + bytes_deduped
                      + skipped_bytes)
            if closed != total_bytes:
                print(f"  {C.YELLOW}Note:    the bytes do not add up: "
                      f"{fmt_size(bytes_written)} written + "
                      f"{fmt_size(bytes_refused)} refused + "
                      f"{fmt_size(bytes_deduped)} deduped + "
                      f"{fmt_size(skipped_bytes)} skipped = "
                      f"{fmt_size(closed)}, not {fmt_size(total_bytes)}. "
                      f"One of them is wrong — treat the run as unreported, "
                      f"not as done.{C.RESET}")

    if forecast is not None and forecast != n_refused:
        print(f"  {C.YELLOW}Note:    the space-check phase predicted "
              f"{forecast} refused file(s), the copy refused {n_refused}. "
              f"The prediction and the result disagree; one of them is "
              f"wrong.{C.RESET}")
    return _SummaryTotals(copied, linked, n_refused,
                          bytes_written, bytes_refused, bytes_deduped)


def _ssh_done_summary(source, dest, total_files, nbytes, elapsed, verb,
                      copied=None, linked=0, skipped=0, saved=0, verified=None,
                      failed=0):
    """Standardized completion block (matches the SFTP/local modes), printed on
    every SSH-only transfer so the GUI and CLI show a consistent summary.

    `failed` is the fifth bucket, and it exists because the closure check
    without it was worse than no check at all: a pull whose extractor refused
    five members, or whose link hit EXDEV, or where the remote simply did not
    send a file, closes short — and the summary answered that by telling the
    user "one of them is wrong — treat the run as unreported", on a run that
    had just reported the failure correctly two lines above. A check that
    fires on correct runs teaches people to ignore it, which costs more than
    the check is worth. Every file is now in exactly one of five buckets:
    copied, linked, skipped, refused (policy said no) or failed (it was
    attempted and broke), and the note fires only when they genuinely do not
    account for the total.

    Refusals come from _REFUSED_PATHS and nowhere else — the same list the
    local engines write to and the same one the exit code reads — so the pull
    can no longer report a number the rest of the run disagrees with."""
    speed = nbytes / elapsed if elapsed > 0 else 0
    print()
    print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{source}{C.RESET}")
    print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dest}{C.RESET}")
    parts = []
    if copied is not None:
        parts.append(_tr("{n} copied").format(n=copied))
    if linked:
        parts.append(_tr("{n} linked").format(n=linked))
    if skipped:
        parts.append(_tr("{n} skipped").format(n=skipped))
    # A refused file was never written, and it is not subtracted from the
    # total either: the total is what the user asked for, and the breakdown
    # has to account for all of it. Shrinking the total was how the refused
    # files disappeared from the one number people read.
    _refused = len(_REFUSED_PATHS)
    if _refused:
        parts.append(_tr("{n} refused").format(n=_refused))
    if failed:
        parts.append(_tr("{n} failed").format(n=failed))
    detail = f"  ({', '.join(parts)})" if parts else ""
    print(f"  {_pad(_tr('Files:'), 11)}{C.BOLD}{total_files}{C.RESET} {_tr('total')}{detail}")
    if copied is not None:
        _closed = copied + linked + skipped + _refused + failed
        if _closed != total_files:
            print(f"  {C.YELLOW}Note:    these numbers do not add up: "
                  f"{copied} copied + {linked} linked + {_refused} refused + "
                  f"{failed} failed + {skipped} skipped = {_closed}, not "
                  f"{total_files}. One of them is wrong — treat the run as "
                  f"unreported, not as done.{C.RESET}")
    sv = "  (" + _tr("{size} saved by dedup").format(size=fmt_size(saved)) + ")" if saved else ""
    print(f"  {_pad(_tr('Data:'), 11)}{C.BOLD}{fmt_size(nbytes)}{C.RESET} {verb}{sv}")
    print(f"  {_pad(_tr('Time:'), 11)}{C.BOLD}{fmt_time(elapsed)}{C.RESET}")
    print(f"  {_pad(_tr('Speed:'), 11)}{C.GREEN}{C.BOLD}{fmt_speed(speed)}{C.RESET}")
    if verified is not None:
        print(f"  {_pad(_tr('Verify:'), 11)}{C.GREEN}✓ {_tr('passed')}{C.RESET}" if verified
              else f"  {_pad(_tr('Verify:'), 11)}{C.RED}✗ {_tr('FAILED')}{C.RESET}")
    else:
        # An absent line is not a report. A run that could not verify has to
        # say so, or "Done" reads as "checked and correct".
        print(f"  {_pad(_tr('Verify:'), 11)}{C.YELLOW}"
              f"{_tr('not run')}{C.RESET}")


def _ssh_record(args, source, dest, mode, total_files, total_bytes, copied,
                linked, skipped, errors, bytes_written, bytes_refused,
                dedup_saved, elapsed, algo):
    """Write the --log-file record for a tar-over-SSH transfer.

    This transport accepted --log-file and wrote nothing. Not a wrong number —
    no file at all, and exit 0 over it, so anything reading the record instead
    of the screen (which is every unattended run) had no way to tell a clean
    transfer from one that refused every file. The flag was parsed and then
    dropped on the floor by the one path a server with SFTP switched off
    selects automatically.

    The shape is the shape every other flow writes, so a consumer never has to
    know which transport carried the bytes. `refused` is read from
    _REFUSED_PATHS — the same list _ssh_done_summary just printed from — so the
    record and the screen cannot tell two different stories about one run.
    """
    speed = bytes_written / elapsed if elapsed > 0 else 0
    summary = {
        "mode": mode,
        "total_files": total_files, "copied": copied, "linked": linked,
        "refused": len(_REFUSED_PATHS),
        "refused_paths": sorted(_REFUSED_PATHS)[:100],
        "skipped": skipped, "errors": errors,
        "total_bytes": total_bytes, "bytes_written": bytes_written,
        "bytes_refused": bytes_refused, "dedup_saved": dedup_saved,
        "elapsed_sec": round(elapsed, 2), "avg_speed_bps": round(speed),
        # The algorithm the two ends actually agreed on, or none: a transfer
        # with no hash tool in common did not dedup and did not verify, and
        # naming an algorithm it never ran would say the opposite.
        "hash_algo": algo or None,
    }
    # BEFORE write_log_file, which clears _log_entries — and unconditionally,
    # because write_sudo_audit decides for itself whether this run is
    # elevated. An elevated transfer over this transport left no audit trail
    # at all, which is the one kind of run that most needs one.
    write_sudo_audit(source, dest, summary)
    if getattr(args, "log_file", None):
        write_log_file(args.log_file,
                       dict(summary, source=source, destination=dest))


def _plan_record(args, source, destination, mode, total_files, copy_entries,
                 link_map, skipped_count, total_bytes, saved_bytes,
                 skipped_bytes, refused=()):
    """The --log-file record for a plan.

    --dry-run accepted --log-file and wrote nothing — the same shape of defect
    as the transports that wrote no record at all, one flag over. The plan was
    printed for a person to read and left unreadable to the thing that has to
    decide whether to run it for real, so nothing could compare what was
    forecast against what then happened.

    Same buckets as a real run's record, plus `dry_run: true` so a consumer
    can tell a forecast from a result. Refusals are not estimated: the caller
    passes the rels the destination policy already said no to, so a plan
    cannot promise to copy a file the run is going to refuse.
    """
    if not getattr(args, "log_file", None):
        return
    refused = set(refused)
    size_by_rel = {e.rel: e.size for e in copy_entries}
    copied = [e for e in copy_entries if e.rel not in refused]
    linked = [k for k in (link_map or {}) if k not in refused]
    refused_link_bytes = sum(
        _refused_rel_size(k, size_by_rel, link_map) or 0
        for k in (link_map or {}) if k in refused)
    write_log_file(args.log_file, {
        "source": source, "destination": destination, "mode": mode,
        "dry_run": True,
        "total_files": total_files,
        "copied": len(copied), "linked": len(linked),
        "refused": len(refused), "refused_paths": sorted(refused)[:100],
        "skipped": skipped_count, "errors": 0,
        "total_bytes": total_bytes,
        "bytes_written": sum(e.size for e in copied),
        "bytes_refused": sum(
            _refused_rel_size(r, size_by_rel, link_map) or 0 for r in refused),
        "dedup_saved": saved_bytes - refused_link_bytes,
        "elapsed_sec": 0, "avg_speed_bps": 0, "hash_algo": _hash_name,
    })


def _planned_local_refusals(dst_root, copy_entries, link_map, trusted_source):
    """Which rels the LOCAL destination policy will refuse — asked of
    _dest_policy itself, so the plan and the run answer with one function."""
    return {rel for rel in ([e.rel for e in copy_entries] + list(link_map or {}))
            if _dest_policy(dst_root, rel,
                            trusted_source=trusted_source)[0] is None}


def _local_dedup_db_path(dst):
    """Where a LOCAL destination's dedup DB lives — same place as the block-order
    copy: `.blitcp_dedup.db` at the destination drive/mount root (fallback:
    inside the destination dir if the root isn't writable). So pull (R2L) shares
    the on-disk location convention with L2L, and the DB travels with the drive."""
    try:
        dst_root = _fs_realpath(dst)
        mount = _find_mount_point(dst_root)
        if mount == os.sep or not _dir_really_writable(mount):
            return _migrate_local_sidecar(dst_root, DEDUP_DB_NAME,
                                          LEGACY_DEDUP_DB_NAME)
        return _migrate_local_sidecar(mount, DEDUP_DB_NAME,
                                      LEGACY_DEDUP_DB_NAME)
    except Exception:
        return os.path.join(_fs_realpath(dst), DEDUP_DB_NAME)


def _local_listing(dst):
    """{relpath: (size, mtime)} for every file under a local directory."""
    res = {}
    for r, _d, fs in os.walk(dst):
        for f in fs:
            ap = os.path.join(r, f)
            rel = os.path.relpath(ap, dst).replace(os.sep, "/")
            try:
                st = os.stat(ap)
                res[rel] = (st.st_size, st.st_mtime)
            except OSError:
                pass
    return res


def _local_link_caps(dest):
    caps = {"hardlink": False, "symlink": False}
    try:
        os.makedirs(dest, exist_ok=True)
    except OSError:
        return caps
    a = os.path.join(dest, ".fc_a")
    b = os.path.join(dest, ".fc_h")
    s = os.path.join(dest, ".fc_s")
    try:
        open(a, "w").close()
        try:
            os.link(a, b)
            caps["hardlink"] = True
        except OSError:
            pass
        try:
            os.symlink(a, s)
            caps["symlink"] = True
        except OSError:
            pass
    except OSError:
        pass
    finally:
        for p in (a, b, s):
            try:
                os.remove(p)
            except OSError:
                pass
    return caps


SMALL_FILE_THRESHOLD = 1024 * 1024     # < 1 MB → bundled together


def _batch_rels(rels, size_of, max_bytes=TAR_CHUNK_SIZE, max_files=10000):
    """Split relpaths into ~max_bytes (default 100 MB) tar batches for the SSH
    transport. Small files (< 1 MB) are bundled together FIRST (so thousands of
    tiny files travel as one big tar instead of one-at-a-time), then the large
    files follow (a file ≥ max_bytes is its own batch). Per-batch streaming lets
    the file counter advance and a re-run resume at batch granularity."""
    smalls = [r for r in rels if size_of(r) < SMALL_FILE_THRESHOLD]
    larges = [r for r in rels if size_of(r) >= SMALL_FILE_THRESHOLD]

    def _pack(items):
        out, cur, cur_size = [], [], 0
        for r in items:
            sz = size_of(r)
            if cur and (cur_size + sz > max_bytes or len(cur) >= max_files):
                out.append(cur)
                cur, cur_size = [], 0
            cur.append(r)
            cur_size += sz
        if cur:
            out.append(cur)
        return out

    return _pack(smalls) + _pack(larges)


def _fc_config_dir():
    if _system == "Windows":
        base = os.environ.get("APPDATA") or os.path.expanduser("~")
    else:
        base = os.environ.get("XDG_CONFIG_HOME") or os.path.join(
            os.path.expanduser("~"), ".config")
    # An existing fast_copy config dir is renamed in place on first touch so
    # SSH dedup caches (and anything else stored here) survive the rename.
    old = os.path.join(base, "fast_copy")
    new = os.path.join(base, "blitcp")
    if os.path.isdir(old) and not os.path.isdir(new):
        try:
            os.replace(old, new)
        except OSError:
            return old
    return new


class SshDedupCache:
    """Persistent, per-destination hash cache for SSH transfers, kept LOCALLY
    (no DB needed on the remote). Maps a destination file's content hash → its
    path, so a new file matching one ALREADY on the destination is linked
    instead of re-copied. Cached hashes are reused while a file's size+mtime are
    unchanged, so repeat runs only hash genuinely new remote files."""

    def __init__(self, host, dest_path, db_path=None):
        def _default_path():
            # remote destinations → keep the DB locally (no SQLite needed on the NAS)
            d = os.path.join(_fc_config_dir(), "dedup")
            try:
                os.makedirs(d, exist_ok=True)
            except OSError:
                pass
            key = hashlib.sha1(("%s\x00%s" % (host, dest_path)).encode("utf-8")).hexdigest()[:16]
            return os.path.join(d, "ssh-%s.db" % key)

        candidates = [db_path] if db_path else []
        candidates.append(_default_path())
        last_err = None
        for i, path in enumerate(candidates):
            try:
                self.path = path
                self.conn = sqlite3.connect(self.path)
                self.conn.execute("CREATE TABLE IF NOT EXISTS dest "
                                  "(rel TEXT PRIMARY KEY, size INTEGER, mtime REAL, hash TEXT)")
                self.conn.commit()
                return
            except sqlite3.Error as e:
                # An explicit mount-root path can be unwritable (the Windows
                # C:\ ACL case) — fall back to the per-user config-dir DB
                # instead of killing the transfer over a cache.
                last_err = e
                if i + 1 < len(candidates):
                    print(f"  {C.YELLOW}Note: dedup cache not usable at "
                          f"{path} ({str(e).splitlines()[0]}) — using the "
                          f"per-user cache dir.{C.RESET}")
        raise OSError(f"dedup cache could not be opened: "
                      f"{str(last_err).splitlines()[0]}")

    def build_index(self, listing, cand_sizes, hash_fn):
        """Return {hash: rel} for destination files whose size is a dedup
        candidate. Reuses cached hashes for unchanged files; hashes only new
        ones via hash_fn(rels)->{rel:hash}. Prunes vanished files."""
        cached = {r[0]: (r[1], r[2], r[3])
                  for r in self.conn.execute("SELECT rel,size,mtime,hash FROM dest")}
        index, need = {}, []
        for rel, (sz, mt) in listing.items():
            if sz not in cand_sizes:
                continue
            c = cached.get(rel)         # (size, mtime, hash)
            if c and c[0] == sz and c[2] and (mt == 0.0 or c[1] == 0.0 or abs(c[1] - mt) <= 2):
                index.setdefault(c[2], rel)
            else:
                need.append(rel)
        if need:
            for rel, h in (hash_fn(need) or {}).items():
                if h:
                    index.setdefault(h, rel)
                    sz, mt = listing[rel]
                    self.conn.execute("INSERT OR REPLACE INTO dest VALUES (?,?,?,?)",
                                      (rel, sz, mt, h))
            self.conn.commit()
        gone = [r for r in cached if r not in listing]
        if gone:
            self.conn.executemany("DELETE FROM dest WHERE rel=?", [(r,) for r in gone])
            self.conn.commit()
            print(f"  Cleaned {C.BOLD}{len(gone)}{C.RESET} stale dedup-DB "
                  f"entr{'y' if len(gone) == 1 else 'ies'} (deleted from destination)")
        return index

    def record(self, rel, size, mtime, h):
        self.conn.execute("INSERT OR REPLACE INTO dest VALUES (?,?,?,?)",
                          (rel, size, mtime, h))

    def close(self):
        try:
            self.conn.commit()
            self.conn.close()
        except Exception:
            pass


def _ssh_dedup_plan(rels, size_of, hash_many, rmap, can_link, algo,
                    cache_factory, dest_hash_fn):
    """Shared dedup planner for push/r2r. Returns (copy_rels, links, saved,
    cache, copy_hashes). Dedups within the transfer AND against files already on
    the destination (via a local hash cache). hash_many(rels)->{rel:hash} hashes
    the SOURCE candidates in one batch."""
    links, saved, cache, copy_hashes = [], 0, None, {}
    if not algo:
        return rels, links, saved, cache, copy_hashes
    # Always open the cache so the DB is created and PRUNED every run (build_index
    # drops entries for files no longer on the destination → self-cleanup).
    cache = cache_factory()
    ssize = {}
    for r in rels:
        ssize[size_of(r)] = ssize.get(size_of(r), 0) + 1
    dest_sizes = set(sz for sz, _m in rmap.values())
    cand = (set(s for s in ssize if (ssize[s] > 1 or s in dest_sizes) and s > 0)
            if (can_link and rels) else set())
    dest_index = cache.build_index(rmap, cand, dest_hash_fn)   # also prunes
    if not cand:
        return rels, links, saved, cache, copy_hashes
    cand_rels = [r for r in rels if size_of(r) in cand]
    shashes = hash_many(cand_rels) or {}
    seen = dict(dest_index)
    copy_rels = []
    for r in rels:
        if size_of(r) in cand:
            h = shashes.get(r)
            if h and h in seen:
                links.append((r, seen[h]))
                saved += size_of(r)
            else:
                if h:
                    seen[h] = r
                    copy_hashes[r] = h
                copy_rels.append(r)
        else:
            copy_rels.append(r)
    return copy_rels, links, saved, cache, copy_hashes


def _ssh_push_smart(dst_remote, dst, local_srcs, args, start):
    """local → remote with incremental skip, dedup (links honor the remote FS,
    incl. files already on the destination via a cached hash DB), and post-copy
    verify — all over plain SSH (no SFTP)."""
    dcli = _tar_ssh_connect(dst_remote, args.ssh_key, _resolved_dst_pw(args), args.compress)

    def _run_dst(cmd):
        _o, _e, _rc = _ssh_run(dcli, cmd)
        return _o, _rc

    # Before _ssh_exec_caps, which runs `mkdir -p <dst> && cd <dst> && : >
    # .fc_a` to probe link support — a write through the symlink under
    # question, made before anyone asked the question.
    _dst_escape = _remote_dest_path_escape(
        _shell_abs_probe(_run_dst), dst, _shell_remote_cwd(_run_dst, dst))
    caps = _ssh_exec_caps(dcli, dst) if not _dst_escape else {
        "hash": None, "halgo": None, "hashes": {}, "hardlink": False,
        "symlink": False, "find_printf": False}
    algo = caps["halgo"] or "sha256"
    link_kind = "hardlink" if caps["hardlink"] else ("symlink" if caps["symlink"] else "none")
    banner("SSH (no SFTP) — local → remote  [dedup · incremental · verify]")
    print(f"  dest FS links: {link_kind} · hash: {caps['hash'] or 'none'}")

    banner("Phase 1 — Scanning source")
    # 1) enumerate local files.
    # A SINGLE directory source copies its CONTENTS; several sources keep their
    # basenames so they cannot collide; a file always keeps its own name. This
    # is what the SFTP, L2L and cloud paths already do — this transport nested
    # every directory under <basename>/ unconditionally, so the same command
    # landed files in a different place depending on the transport. That was
    # survivable while --ssh-no-sftp was typed by hand; it is not, now that a
    # server without the SFTP subsystem selects this path automatically.
    # (The pull direction was fixed the same way in 876bcff.)
    _multi_src = len(local_srcs or []) > 1
    files, ap_by_rel, size_by_rel = [], {}, {}
    for s in (local_srcs or []):
        s = os.path.abspath(s)
        if not os.path.exists(s):
            print(f"{C.RED}Error: source not found: {s}{C.RESET}")
            dcli.close()
            return 1
        base = os.path.basename(s.rstrip("/\\")) or s
        _pfx = (base + "/") if _multi_src else ""
        if os.path.isfile(s):
            st = os.stat(s)
            files.append((base, st.st_size, st.st_mtime))
            ap_by_rel[base], size_by_rel[base] = s, st.st_size
        else:
            for r, _d, fs in os.walk(s):
                # Consistency with every other mode: prune the default
                # node_modules exclusion (unless --include-node-modules).
                if not getattr(args, 'include_node_modules', False):
                    _d[:] = [d for d in _d if d not in DEFAULT_DIR_EXCLUDES]
                for f in fs:
                    ap = os.path.join(r, f)
                    rel = _pfx + os.path.relpath(ap, s).replace(os.sep, "/")
                    try:
                        st = os.stat(ap)
                    except OSError:
                        continue
                    files.append((rel, st.st_size, st.st_mtime))
                    ap_by_rel[rel], size_by_rel[rel] = ap, st.st_size

    mt_by_rel = {rel: mt for rel, sz, mt in files}
    print(f"  Found {C.BOLD}{len(files)}{C.RESET} local files  "
          f"({fmt_size(sum(size_by_rel.values()))})")

    # destination listing (used for both incremental and dedup-against-existing)
    rmap = _ssh_remote_listing(dcli, dst, caps)

    # incremental: skip files already present with matching size (+mtime)
    skipped = []
    rels = [f[0] for f in files]
    if not args.overwrite:
        keep = []
        for rel in rels:
            r = rmap.get(rel)
            if r and r[0] == size_by_rel[rel] and (r[1] == 0.0 or abs(r[1] - mt_by_rel[rel]) <= 2):
                skipped.append(rel)
            else:
                keep.append(rel)
        rels = keep
    # Same reason as the pull: the record's byte closure is checked against
    # per-file entries, so an unchanged file has to name its own bytes.
    for _rel in skipped:
        _log("skipped", _rel, size_by_rel[_rel], reason="unchanged")

    # ── Phase 2 — Deduplication (within transfer + against files on the dest) ──
    banner("Phase 2 — Deduplication")
    can_link = caps["hardlink"] or caps["symlink"]
    cache = copy_hashes = None
    links, saved = [], 0
    if not args.no_dedup:
        rels, links, saved, cache, copy_hashes = _ssh_dedup_plan(
            rels, lambda r: size_by_rel[r],
            lambda rl: {r: _hash_local_file(ap_by_rel[r], algo) for r in rl},
            rmap, can_link, algo if caps["hash"] else None,
            lambda: SshDedupCache(dst_remote.host, dst),
            lambda rl: _ssh_remote_hashes(dcli, dst, rl, caps))
    print(f"  Unique files:    {C.BOLD}{len(rels)}{C.RESET}")
    print(f"  Duplicates:      {C.BOLD}{len(links)}{C.RESET}  (dest FS: {link_kind})")
    print(f"  Space saved:     {C.BOLD}{fmt_size(saved)}{C.RESET}")
    if skipped:
        print(f"  Already present: {C.BOLD}{len(skipped)}{C.RESET} (skipped)")

    if args.dry_run:
        if cache:
            cache.close()
        print(f"\n  {C.YELLOW}(dry run — would copy {len(rels)}, link {len(links)}, "
              f"skip {len(skipped)}){C.RESET}")
        dcli.close()
        return 0

    # ── Destination-path policy on the far side ──
    # The same question the SFTP push asks, over the only channel this
    # transport has, and with the same answer: a remote destination is strict.
    # The destination path itself leading elsewhere was already decided above,
    # before anything could be created.
    _all_rels = list(rels) + [d for d, _t in links]
    if _dst_escape:
        _dst_refused = set(_all_rels)
        _dst_found = [{"rel": "", "target": _dst_escape[1],
                       "count": len(_dst_refused)}]
    else:
        _dst_refused, _dst_found = _remote_dest_refusals(
            dst, _all_rels,
            *_shell_dest_probe(_run_dst, dst, _dest_dir_ladder(_all_rels)))
    _record_remote_refusals(dst, _dst_refused, _dst_found,
                            lambda rel: size_by_rel.get(rel, 0))
    send_rels = [r for r in rels if r not in _dst_refused]
    send_links = [(d, t) for d, t in links if d not in _dst_refused]

    total = sum(size_by_rel[r] for r in send_rels) or 1

    # ── Phase 3 — Space check (default; override with --force) ──
    banner("Phase 3 — Space check")
    if send_rels and not _check_space_remote(dcli, dst, sum(size_by_rel[r] for r in send_rels), args.force):
        if cache:
            cache.close()
        dcli.close()
        return 1

    # ── Phase 4 — Local-to-remote copy ──
    # Initialised before the branch, so an empty transfer cannot reach the
    # summary with it unbound.
    _failed_adds = []
    banner("Phase 4 — Local-to-remote copy")
    print(f"  Strategy: tar stream for {len(send_rels)} files ({fmt_size(total)})\n")
    if send_rels:
        q = shlex.quote(dst)
        di, do, de = dcli.exec_command("mkdir -p %s && cd %s && tar xpf -" % (q, q))
        writer = _TarWriteCounter(di, total, len(send_rels), start)
        with tarfile.open(fileobj=writer, mode="w|") as tf:
            for i, rel in enumerate(send_rels):
                try:
                    tf.add(ap_by_rel[rel], arcname=rel, recursive=False)
                    _log("copied", rel, size_by_rel[rel], method="tar_stream")
                except OSError as e:
                    # It used to be `pass`: the file was left out of the
                    # archive, counted as copied, and the run exited 0. A
                    # source this process could not read is a file the user
                    # asked for and did not get, and it has to reach the
                    # summary, the record and the exit code like any other.
                    _failed_adds.append(rel)
                    _log("error", rel, size_by_rel[rel], error=str(e),
                         source_read=_benign_source_error(e, ap_by_rel[rel]))
                writer.files_done = i + 1
        di.channel.shutdown_write()
        rc = do.channel.recv_exit_status()
        if rc:
            print(f"{C.RED}Error: "
                  f"{de.read().decode('utf-8','replace').strip() or 'remote tar failed'}{C.RESET}")
            dcli.close()
            return 1

    # 5) create dedup links on the remote, honoring its FS capability
    if send_links:
        cmds = []
        for dup, target in send_links:
            dd = posixpath.dirname(dup)
            if dd:
                cmds.append("mkdir -p " + shlex.quote(dd))
            if caps["hardlink"]:
                cmds.append("ln -f %s %s" % (shlex.quote(target), shlex.quote(dup)))
            else:
                rt = posixpath.relpath(target, dd or ".")
                cmds.append("ln -sf %s %s" % (shlex.quote(rt), shlex.quote(dup)))
        _o, _e, rc = _ssh_run(dcli, "cd %s && " % shlex.quote(dst) + " && ".join(cmds))
        if rc:
            print(f"  {C.YELLOW}Warning: some dedup links could not be created{C.RESET}")

    # 6) verify copied + linked files by hashing both sides
    verified = True
    vhashes = {}
    if not args.no_verify and caps["hash"]:
        check = list(send_rels) + [d for d, _t in send_links]
        banner("Verifying")
        rh = _ssh_remote_hashes(dcli, dst, check, caps)
        bad = 0
        for k, rel in enumerate(check):
            lh = _hash_local_file(ap_by_rel[rel], algo) if rel in ap_by_rel else None
            if lh:
                vhashes[rel] = lh                     # reuse for the dedup DB
            if lh and rh.get(rel) and lh != rh[rel]:
                bad += 1
                print("  " + C.RED + "✗ " + _tr("verify mismatch: {name}").format(name=rel) + C.RESET)
            if (k + 1) % 16 == 0 or k + 1 == len(check):
                _verify_emit(k + 1, len(check))
        verified = (bad == 0)
        if verified:
            print(f"  {C.GREEN}✓ Verified {len(check)} file(s){C.RESET}")

    # 7) record EVERY copied file in the dedup DB (complete index of the dest),
    #    reusing the verify hashes; the next run dedups against all of it.
    if cache is None and not args.no_dedup and caps["hash"]:
        cache = SshDedupCache(dst_remote.host, dst)
    if cache is not None:
        all_h = dict(copy_hashes or {})
        all_h.update(vhashes)
        for rel in send_rels:
            h = all_h.get(rel) or (_hash_local_file(ap_by_rel[rel], algo)
                                   if rel in ap_by_rel else None)
            if h:
                cache.record(rel, size_by_rel[rel], mt_by_rel[rel], h)
        cache.close()

    _tar_emit(total, total, len(send_rels) + len(send_links), len(files),
              start, final=True)
    src_disp = (os.path.abspath(local_srcs[0]) if local_srcs and len(local_srcs) == 1
                else f"{len(local_srcs or [])} sources")
    _elapsed = time.time() - start
    _refused_now = set(_REFUSED_PATHS)
    _failed = set(_failed_adds)
    _sent = [r for r in send_rels if r not in _failed]
    _ssh_done_summary(
        src_disp, f"{dst_remote.user}@{dst_remote.host}:{dst}", len(files),
        sum(size_by_rel[r] for r in _sent), _elapsed, "uploaded",
        copied=len(_sent), linked=len(send_links), skipped=len(skipped),
        saved=saved,
        verified=(verified if (not args.no_verify and caps["hash"]) else None),
        failed=len(_failed))
    _ssh_record(
        args, src_disp, f"{dst_remote.user}@{dst_remote.host}:{dst}",
        "local_to_remote", total_files=len(files),
        total_bytes=sum(size_by_rel.values()),
        copied=len(_sent), linked=len(send_links), skipped=len(skipped),
        errors=len(_failed),
        bytes_written=sum(size_by_rel[r] for r in rels
                          if r not in _refused_now),
        bytes_refused=sum(size_by_rel.get(r, 0) for r in _refused_now),
        dedup_saved=saved - sum(size_by_rel.get(d, 0) for d, _t in links
                                if d in _refused_now),
        elapsed=_elapsed, algo=(algo if caps["hash"] else None))
    dcli.close()
    # A refused file is one the user asked for and did not get, so it fails
    # the run on its own — the same rule the pull already applies.
    return 0 if (verified and not _failed and not _REFUSED_PATHS) else 1


def _ssh_pull_smart(src_remote, dst, args, start):
    """remote → local with incremental skip, dedup (links honor the LOCAL dest
    FS), and verify — all over plain SSH (no SFTP)."""
    scli = _tar_ssh_connect(src_remote, args.src_key, _resolved_src_pw(args), args.compress)
    rpath = src_remote.path.rstrip("/") or "/"
    pdir = posixpath.dirname(rpath) or "/"
    base = posixpath.basename(rpath) or rpath
    caps = _ssh_exec_caps(scli, "/tmp")          # source-side hash/find caps
    lcaps = _local_link_caps(dst)                 # dest FS = local
    algo = caps["halgo"] or "sha256"
    link_kind = "hardlink" if lcaps["hardlink"] else ("symlink" if lcaps["symlink"] else "none")
    banner("SSH (no SFTP) — remote → local  [dedup · incremental · verify]")
    print(f"  dest FS links: {link_kind} · hash: {caps['hash'] or 'none'}")

    banner("Phase 1 — Scanning source")
    # A directory source copies its CONTENTS (rels relative to the dir, root =
    # the dir itself); a single-file source keeps its name under the parent.
    # This mirrors the SFTP and L2L paths — the trailing slash is irrelevant and
    # we never nest under <base>/ (which the old code always did, landing files
    # at dst/<base>/… inconsistently with every other transport).
    src_files = _ssh_remote_listing(scli, rpath, caps)
    if src_files:
        parent = rpath                            # directory → copy contents
    else:
        parent = pdir                             # single file (or empty/missing)
        src_files = {rel: v for rel, v in _ssh_remote_listing(scli, pdir, caps).items()
                     if rel == base}
    if not src_files:
        print(f"{C.RED}Error: nothing to copy at {src_remote.host}:{rpath} "
              f"(empty, missing, or not a directory).{C.RESET}")
        scli.close()
        return 1
    _scan_bytes = sum(v[0] for v in src_files.values())
    print(f"  Found {C.BOLD}{len(src_files)}{C.RESET} files on remote  "
          f"({fmt_size(_scan_bytes)})")

    # incremental: skip files already present locally with matching size (+mtime)
    skipped = set()
    if not args.overwrite:
        for rel, (sz, mt) in src_files.items():
            lp = os.path.join(dst, rel.replace("/", os.sep))
            if os.path.isfile(lp):
                try:
                    lst = os.stat(lp)
                    if lst.st_size == sz and (mt == 0.0 or abs(lst.st_mtime - mt) <= 2):
                        skipped.add(rel)
                except OSError:
                    pass
    # An unchanged file is a bucket in the record like any other, and its
    # bytes have to be nameable: the record's byte closure is checked against
    # the per-file entries, not against a count. Every other transport logs
    # these; this one counted them and said nothing.
    for _rel in skipped:
        _log("skipped", _rel, src_files[_rel][0], reason="unchanged")
    rels = [r for r in src_files if r not in skipped]

    # ── Phase 2 — Deduplication (within transfer + against existing LOCAL dest,
    #    via the cached hash DB). Hash on the remote source; link on the local FS.
    banner("Phase 2 — Deduplication")
    can_link = lcaps["hardlink"] or lcaps["symlink"]
    cache = ddb = None
    copy_hashes = {}
    links, saved = [], 0          # links: (dup_rel, ABSOLUTE target path)
    # When the remote hash equals the local hash algo (xxh128 via xxh128sum), share
    # the exact same DedupDB/dest_files index as L2L; otherwise fall back to the
    # local sha256 cache (separate state).
    shared = bool(caps["hash"]) and caps["halgo"] == _hash_name
    if not args.no_dedup and caps["hash"]:
        local_dest = _local_listing(dst)
        if shared and can_link:
            try:
                ddb = DedupDB(os.path.abspath(dst))
            except Exception:
                ddb = None
        if ddb is not None:
            ncleaned = ddb.prune_dest(local_dest.keys())     # self-cleanup
            if ncleaned:
                print(f"  Cleaned {C.BOLD}{ncleaned}{C.RESET} stale dedup-DB "
                      f"entr{'y' if ncleaned == 1 else 'ies'} (deleted from destination)")
            # candidate if its size collides within the source OR matches ANY file
            # already recorded on the drive (the shared DB spans all folders)
            known_sizes = set(sz for sz, _m in local_dest.values()) | ddb.dest_sizes()
            bysize = {}
            for r in rels:
                bysize.setdefault(src_files[r][0], []).append(r)
            cand = [r for r in rels if src_files[r][0] > 0
                    and (len(bysize[src_files[r][0]]) > 1 or src_files[r][0] in known_sizes)]
            shashes = _ssh_remote_hashes(scli, parent, cand, caps)
            seen, drop = {}, set()
            for r in cand:
                h = shashes.get(r)
                if not h:
                    continue
                # Content-verified target (guards the stale-hash hole: never
                # link to a drive file whose bytes changed since indexing).
                abs_t = ddb.safe_link_target(h, src_files[r][0])
                if abs_t:
                    links.append((r, abs_t)); drop.add(r); saved += src_files[r][0]
                elif h in seen:
                    # seen[h] is a name the REMOTE chose. The other branch's
                    # target comes from ddb.safe_link_target(), which resolves
                    # through safe_full_path(), lstats, requires a regular
                    # file of the right size and re-hashes the contents — so
                    # that one arrives already checked. This one does not, and
                    # it becomes the source argument of os.link().
                    _lt = _safe_pull_link_dest(dst, seen[h])
                    if _lt is None:
                        print(f"\n  {C.RED}Refusing unsafe link target: "
                              f"{seen[h]}{C.RESET}")
                        _log("error", r, 0, error="unsafe link target")
                    else:
                        links.append((r, _lt))
                        drop.add(r); saved += src_files[r][0]
                else:
                    seen[h] = r; copy_hashes[r] = h
            rels = [r for r in rels if r not in drop]
        else:
            rels, links2, saved, cache, copy_hashes = _ssh_dedup_plan(
                rels, lambda r: src_files[r][0],
                lambda rl: _ssh_remote_hashes(scli, parent, rl, caps),
                local_dest, can_link, algo,
                lambda: SshDedupCache("local", dst, db_path=_local_dedup_db_path(dst)),
                lambda rl: {r: _hash_local_file(os.path.join(dst, r.replace("/", os.sep)), algo)
                            for r in rl})
            links = [(d, os.path.join(dst, t.replace("/", os.sep))) for d, t in links2]
    print(f"  Unique files:    {C.BOLD}{len(rels)}{C.RESET}")
    print(f"  Duplicates:      {C.BOLD}{len(links)}{C.RESET}  "
          f"(dest FS: {link_kind})")
    print(f"  Space saved:     {C.BOLD}{fmt_size(saved)}{C.RESET}")
    if skipped:
        print(f"  Already present: {C.BOLD}{len(skipped)}{C.RESET} (skipped)")

    if args.dry_run:
        print(f"\n  {C.YELLOW}(dry run — would copy {len(rels)}, link {len(links)}, "
              f"skip {len(skipped)}){C.RESET}")
        scli.close()
        return 0

    os.makedirs(dst, exist_ok=True)
    total = sum(src_files[r][0] for r in rels) or 1

    # ── Phase 3 — Space check (default; override with --force) ──
    banner("Phase 3 — Space check")
    if rels and not _check_space_local(dst, sum(src_files[r][0] for r in rels), args.force):
        scli.close()
        return 1

    # ── Phase 4 — Remote-to-local copy ──
    # Initialised here, not inside `if rels:`, so an empty transfer cannot
    # reach the exit test with these unbound.
    delivered, rejected, link_errors, linked_ok = 0, 0, 0, 0
    banner("Phase 4 — Remote-to-local copy")
    # Said once, before anything is written. Discovering a symlinked
    # destination directory one refused file at a time is a flood, not a
    # diagnosis, and the fix — point the destination at the real path — is
    # something the user can only act on before the run, not after it.
    # Remote-chosen names: the extractor below runs _safe_tar_extract with
    # trusted_source=False, so the preflight asks the untrusted question too.
    warn_symlinked_dest_dirs(dst, list(rels) + [d for d, _t in links],
                             trusted_source=False)
    print(f"  Strategy: tar stream for {len(rels)} files ({fmt_size(total)})\n")
    if rels:
        so, se = _ssh_tar_send(scli, parent, rels)
        reader = _TarReadCounter(so, total, len(rels), start)
        delivered, rejected = _tar_extract_stream(reader, dst)
        rc = so.channel.recv_exit_status()
        if rc:
            print(f"{C.RED}Error: "
                  f"{se.read().decode('utf-8','replace').strip() or 'remote tar failed'}{C.RESET}")
            scli.close()
            return 1

    # A member the extractor refused is a file the user asked for and did not
    # get. It has to survive to the exit code and the summary on its own,
    # because verification — the only other thing that can fail this run — does
    # not run at all under --no-verify or against a remote with no hash tool.
    if rejected:
        print(f"\n  {C.RED}"
              + _tr("{n} file(s) were refused and not written").format(n=rejected)
              + f"{C.RESET}")
    if delivered + rejected and delivered < len(rels):
        _log("error", "(batch)", 0,
             error="%d of %d requested files were not delivered"
                   % (len(rels) - delivered, len(rels)))

    # local dedup links honoring the local FS (target is an ABSOLUTE path)
    _abs_dst = os.path.abspath(dst)          # loop-invariant; resolved once
    for dup, tp in links:
        # BOTH sides are checked. dup is a REMOTE-supplied name and the loop
        # removes whatever is at the joined path before linking, so unchecked
        # it is a delete at an attacker-chosen location. tp has the same
        # provenance in the same-run case — it is built from seen[h], another
        # name the remote chose — and os.link() would then hardlink an
        # attacker-named path into the destination, or os.symlink() point at
        # it. create_links() validates both for exactly this reason; this loop
        # validated only the destination and was missed.
        dp = _safe_pull_link_dest(dst, dup)
        if dp is None:
            # A refusal, not a link error — same split as create_links():
            # link_errors is for links that were ATTEMPTED and failed (EXDEV,
            # EPERM). Reporting a refusal as an error is how the summary lost
            # track of which files were policy-refused and which broke.
            print(f"\n  {C.RED}Refusing unsafe link path: {dup}{C.RESET}")
            _note_refusal(dup)
            _log("refused", dup, 0,
                 error="refused: link path resolves outside the destination")
            continue
        # Both provenances are already checked by the time they get here — the
        # remote-named one above, the cross-run one by safe_link_target(). This
        # is the second line, and it needs no knowledge of which is which: a
        # target inside the destination must still pass the path check, and one
        # outside it must be a real, non-symlink regular file, which is exactly
        # what safe_link_target() guarantees and nothing else can produce.
        if os.path.abspath(tp).startswith(_abs_dst + os.sep):
            safe_tp = _safe_pull_link_dest(dst, os.path.relpath(tp, dst))
        else:
            try:
                _st = os.lstat(tp)
                safe_tp = tp if stat.S_ISREG(_st.st_mode) else None
            except OSError:
                safe_tp = None
        if safe_tp is None:
            # Named by the file the user does not get — the duplicate — for the
            # same reason create_links() does: recording the canonical name
            # would count a file that WAS written as one that was not.
            print(f"\n  {C.RED}Refusing unsafe link target: {tp}{C.RESET}")
            _note_refusal(dup)
            _log("refused", dup, 0,
                 error="refused: link target resolves outside the destination")
            continue
        try:
            os.makedirs(os.path.dirname(dp), exist_ok=True)
            if os.path.lexists(dp):
                os.remove(dp)
            if lcaps["hardlink"]:
                os.link(safe_tp, dp)
            else:
                os.symlink(os.path.relpath(safe_tp, os.path.dirname(dp)), dp)
            linked_ok += 1
        except OSError as e:
            # A link that could not be made is a file the user did not get.
            link_errors += 1
            _log("error", dup, 0, error="link failed: %s" % e)

    # verify: hash local copies against remote hashes
    verified = True
    vhashes = {}
    if not args.no_verify and caps["hash"]:
        check = list(rels) + [d for d, _t in links]
        banner("Verifying")
        rh = _ssh_remote_hashes(scli, parent, check, caps)
        bad = 0
        for k, rel in enumerate(check):
            lp = os.path.join(dst, rel.replace("/", os.sep))
            try:
                lh = _hash_local_file(lp, algo)
            except OSError:
                lh = None
            if lh:
                vhashes[rel] = lh
            if lh and rh.get(rel) and lh != rh[rel]:
                bad += 1
                print("  " + C.RED + "✗ " + _tr("verify mismatch: {name}").format(name=rel) + C.RESET)
            if (k + 1) % 16 == 0 or k + 1 == len(check):
                _verify_emit(k + 1, len(check))
        verified = (bad == 0)
        if verified:
            print(f"  {C.GREEN}✓ Verified {len(check)} file(s){C.RESET}")

    # record EVERY copied file in the dedup DB (complete dest index, xxh128)
    all_h = dict(copy_hashes or {})
    all_h.update(vhashes)

    def _rel_hash(rel):
        lp = os.path.join(dst, rel.replace("/", os.sep))
        return all_h.get(rel) or (_hash_local_file(lp, algo)
                                  if os.path.isfile(lp) else None)

    if ddb is not None:
        rows = []
        for rel in rels:
            h = _rel_hash(rel)
            if not h:
                continue
            try:
                mt = os.lstat(os.path.join(
                    dst, rel.replace("/", os.sep))).st_mtime_ns
            except OSError:
                mt = None
            rows.append((rel, src_files[rel][0], h, mt))
        if rows:
            ddb.store_dest_batch(rows)         # shared dest_files index with L2L
        ddb.close()
    else:
        if cache is None and not args.no_dedup and caps["hash"]:
            cache = SshDedupCache("local", dst, db_path=_local_dedup_db_path(dst))
        if cache is not None:
            for rel in rels:
                h = _rel_hash(rel)
                if h:
                    cache.record(rel, src_files[rel][0], src_files[rel][1], h)
            cache.close()

    _tar_emit(total, total, len(rels) + len(links), len(src_files), start, final=True)
    # Report what landed, not what was asked for. The fifth bucket: files that
    # were attempted and did not arrive. `rejected` members and refused link
    # names are NOT in here — they are in _REFUSED_PATHS, which the summary
    # reads directly — so the two cannot double-count the same file.
    _undelivered = max(0, len(rels) - delivered - rejected)
    _elapsed = time.time() - start
    _ssh_done_summary(
        f"{src_remote.user}@{src_remote.host}:{rpath}", os.path.abspath(dst),
        len(src_files), sum(src_files[r][0] for r in rels), _elapsed,
        "downloaded", copied=delivered, linked=linked_ok, skipped=len(skipped),
        saved=saved, verified=(verified if (not args.no_verify and caps["hash"]) else None),
        failed=link_errors + _undelivered)
    # The same five buckets over BYTES, and they close for the same reason the
    # file counts do: a refused link's bytes move out of "saved by dedup" and
    # into "refused" instead of being counted in both, which is the convention
    # _print_files_summary settled on for the local flow.
    _refused_now = set(_REFUSED_PATHS)
    _sz = lambda r: src_files.get(r, (0, 0))[0]
    _refused_link_bytes = sum(_sz(d) for d, _t in links if d in _refused_now)
    _ssh_record(
        args, f"{src_remote.user}@{src_remote.host}:{rpath}",
        os.path.abspath(dst), "remote_to_local",
        total_files=len(src_files),
        total_bytes=sum(v[0] for v in src_files.values()),
        copied=delivered, linked=linked_ok, skipped=len(skipped),
        errors=link_errors + _undelivered,
        bytes_written=sum(_sz(r) for r in rels if r not in _refused_now),
        bytes_refused=sum(_sz(r) for r in _refused_now),
        dedup_saved=saved - _refused_link_bytes,
        elapsed=_elapsed, algo=(algo if caps["hash"] else None))
    scli.close()
    # Three independent ways this run can have failed, and only one of them is
    # verification. A refused member and a link that could not be made are
    # both "the user did not get what they asked for", and both used to exit 0.
    # Refusals are read from the shared list rather than from `rejected`: the
    # link loop's refusals never reached that counter, so a run whose only
    # refusal was an unsafe link name exited 0.
    if _REFUSED_PATHS or link_errors or _undelivered or not verified:
        return 1
    return 0


def _ssh_r2r_smart(src_remote, dst_remote, dst, args, start):
    """remote → remote with incremental skip, dedup (links honor the DESTINATION
    remote's FS) and verify (both remotes hashed) — all over plain SSH."""
    scli = _tar_ssh_connect(src_remote, args.src_key, _resolved_src_pw(args), args.compress)
    dcli = _tar_ssh_connect(dst_remote, args.ssh_key, _resolved_dst_pw(args), args.compress)
    rpath = src_remote.path.rstrip("/") or "/"
    parent = posixpath.dirname(rpath) or "/"
    base = posixpath.basename(rpath) or rpath
    def _run_dst(cmd):
        _o, _e, _rc = _ssh_run(dcli, cmd)
        return _o, _rc

    # Before _ssh_exec_caps touches the destination: its link probe creates
    # the directory and writes into it, which is a write through the symlink
    # under question.
    _dst_escape = _remote_dest_path_escape(
        _shell_abs_probe(_run_dst), dst, _shell_remote_cwd(_run_dst, dst))
    scaps = _ssh_exec_caps(scli, "/tmp")        # source: hash/find
    dcaps = (_ssh_exec_caps(dcli, dst) if not _dst_escape else
             {"hash": None, "halgo": None, "hashes": {}, "hardlink": False,
              "symlink": False, "find_printf": False})
    # a hash algorithm both ends share (needed for dedup + verify)
    algo = _common_hash_algo(scaps, dcaps)
    if algo:
        # Pin each side to the AGREED algorithm — its own favourite may be a
        # different one, and the two digests would never compare equal.
        scaps["hash"], scaps["halgo"] = scaps["hashes"][algo], algo
        dcaps["hash"], dcaps["halgo"] = dcaps["hashes"][algo], algo
    link_kind = "hardlink" if dcaps["hardlink"] else ("symlink" if dcaps["symlink"] else "none")
    # Say what this run will ACTUALLY do. The feature list used to be a fixed
    # string, so a run with no shared hash tool still advertised "dedup ·
    # verify" and then quietly did neither.
    feats = ["incremental"] + (["dedup", "verify"] if algo else [])
    banner("SSH (no SFTP) — remote → remote  [" + " · ".join(feats) + "]")
    print(f"  dest FS links: {link_kind} · hash: {algo or 'none'}")
    if not algo:
        s_have = ", ".join(sorted(scaps.get("hashes") or {})) or "none"
        d_have = ", ".join(sorted(dcaps.get("hashes") or {})) or "none"
        print(f"  {C.YELLOW}Warning: no hash tool common to both ends "
              f"(source has: {s_have}; destination has: {d_have}) — "
              f"deduplication AND verification are OFF for this transfer. "
              f"Install xxhsum or coreutils on the end that is missing "
              f"one.{C.RESET}")

    banner("Phase 1 — Scanning source")
    smap = _ssh_remote_listing(scli, parent, scaps)
    src_files = {rel: v for rel, v in smap.items()
                 if rel == base or rel.startswith(base + "/")}
    if not src_files:
        print(f"{C.RED}Error: nothing to copy at {src_remote.host}:{rpath}.{C.RESET}")
        scli.close()
        dcli.close()
        return 1
    print(f"  Found {C.BOLD}{len(src_files)}{C.RESET} files on source  "
          f"({fmt_size(sum(v[0] for v in src_files.values()))})")

    # destination listing (incremental + dedup-against-existing)
    dmap = _ssh_remote_listing(dcli, dst, dcaps)

    # incremental against the destination
    skipped = set()
    if not args.overwrite:
        for rel, (sz, mt) in src_files.items():
            d = dmap.get(rel)
            if d and d[0] == sz and (mt == 0.0 or d[1] == 0.0 or abs(d[1] - mt) <= 2):
                skipped.add(rel)
    # Same reason as the other two SSH-only directions: the record's bytes are
    # closed against the per-file entries, so an unchanged file names its own.
    for _rel in skipped:
        _log("skipped", _rel, src_files[_rel][0], reason="unchanged")
    rels = [r for r in src_files if r not in skipped]

    # ── Phase 2 — Deduplication (hash on source; link on dest per its FS) ──
    banner("Phase 2 — Deduplication")
    can_link = dcaps["hardlink"] or dcaps["symlink"]
    cache = copy_hashes = None
    links, saved = [], 0
    if not args.no_dedup:
        rels, links, saved, cache, copy_hashes = _ssh_dedup_plan(
            rels, lambda r: src_files[r][0],
            lambda rl: _ssh_remote_hashes(scli, parent, rl, scaps),
            dmap, can_link, algo,
            lambda: SshDedupCache(dst_remote.host, dst),
            lambda rl: _ssh_remote_hashes(dcli, dst, rl, dcaps))
    print(f"  Unique files:    {C.BOLD}{len(rels)}{C.RESET}")
    print(f"  Duplicates:      {C.BOLD}{len(links)}{C.RESET}  (dest FS: {link_kind})")
    print(f"  Space saved:     {C.BOLD}{fmt_size(saved)}{C.RESET}")
    if skipped:
        print(f"  Already present: {C.BOLD}{len(skipped)}{C.RESET} (skipped)")

    if args.dry_run:
        if cache:
            cache.close()
        print(f"\n  {C.YELLOW}(dry run — would copy {len(rels)}, link {len(links)}, "
              f"skip {len(skipped)}){C.RESET}")
        scli.close()
        dcli.close()
        return 0

    # ── Destination-path policy on the far side ──
    # The names come from a remote SOURCE, so they are untrusted whatever this
    # process's privilege is — the same answer a pull gets. The destination
    # path itself was decided above, before anything could be created.
    _all_rels = list(rels) + [d for d, _t in links]
    if _dst_escape:
        _dst_refused = set(_all_rels)
        _dst_found = [{"rel": "", "target": _dst_escape[1],
                       "count": len(_dst_refused)}]
    else:
        _dst_refused, _dst_found = _remote_dest_refusals(
            dst, _all_rels,
            *_shell_dest_probe(_run_dst, dst, _dest_dir_ladder(_all_rels)))
    _record_remote_refusals(dst, _dst_refused, _dst_found,
                            lambda rel: src_files.get(rel, (0, 0))[0])
    send_rels = [r for r in rels if r not in _dst_refused]
    send_links = [(d, t) for d, t in links if d not in _dst_refused]

    # ── Phase 3 — Space check (default; override with --force) ──
    banner("Phase 3 — Space check")
    if send_rels and not _check_space_remote(
            dcli, dst, sum(src_files[r][0] for r in send_rels), args.force):
        if cache:
            cache.close()
        scli.close()
        dcli.close()
        return 1

    # ── Phase 4 — Remote-to-remote copy (in tar chunks) ──
    banner("Phase 4 — Remote-to-remote copy")
    total = sum(src_files[r][0] for r in send_rels) or 1
    done_bytes = done_files = last = 0
    chunk_mb = max(1, getattr(args, "chunk_size", 100))
    chunk_bytes = chunk_mb * 1024 * 1024
    batches = _batch_rels(send_rels, lambda r: src_files[r][0],
                          max_bytes=chunk_bytes)
    print(f"  Strategy: tar stream for {len(send_rels)} files ({fmt_size(total)}) "
          f"in {len(batches)} chunk(s) of ~{chunk_mb} MB\n")
    for bi, batch in enumerate(batches):
        so, se = _ssh_tar_send(scli, parent, batch)
        di, do, de = dcli.exec_command(
            "mkdir -p %s && cd %s && tar xpf -" % (shlex.quote(dst), shlex.quote(dst)))
        while True:
            b = so.read(131072)
            if not b:
                break
            di.channel.sendall(b)
            done_bytes += len(b)
            if done_bytes - last >= 2 * 1024 * 1024:
                last = done_bytes
                _tar_emit(done_bytes, total, done_files, len(send_rels), start)
        di.channel.shutdown_write()
        rcs, rcd = so.channel.recv_exit_status(), do.channel.recv_exit_status()
        if rcs or rcd:
            err = (se.read() + de.read()).decode("utf-8", "replace").strip()
            print(f"{C.RED}Error: {err or 'remote tar failed'}{C.RESET}")
            scli.close()
            dcli.close()
            return 1
        done_files += len(batch)
        _tar_emit(done_bytes, total, done_files, len(send_rels), start)
        print(f"  chunk {bi + 1}/{len(batches)} done "
              f"({done_files}/{len(rels)} files, {fmt_size(done_bytes)})")

    # dedup links on the destination remote, honoring its FS
    if send_links:
        cmds = []
        for dup, target in send_links:
            dd = posixpath.dirname(dup)
            if dd:
                cmds.append("mkdir -p " + shlex.quote(dd))
            if dcaps["hardlink"]:
                cmds.append("ln -f %s %s" % (shlex.quote(target), shlex.quote(dup)))
            else:
                rt = posixpath.relpath(target, dd or ".")
                cmds.append("ln -sf %s %s" % (shlex.quote(rt), shlex.quote(dup)))
        _o, _e, rc = _ssh_run(dcli, "cd %s && " % shlex.quote(dst) + " && ".join(cmds))
        if rc:
            print(f"  {C.YELLOW}Warning: some dedup links could not be created{C.RESET}")

    # verify: hash the same files on BOTH remotes and compare
    verified = True
    vhashes = {}
    if not args.no_verify and algo:
        check = list(send_rels) + [d for d, _t in send_links]
        banner("Verifying")
        sh = _ssh_remote_hashes(scli, parent, check, scaps)
        dh = _ssh_remote_hashes(dcli, dst, check, dcaps)
        vhashes = dict(sh)                            # source == dest content
        bad = 0
        for k, rel in enumerate(check):
            if sh.get(rel) and dh.get(rel) and sh[rel] != dh[rel]:
                bad += 1
                print("  " + C.RED + "✗ " + _tr("verify mismatch: {name}").format(name=rel) + C.RESET)
            if (k + 1) % 16 == 0 or k + 1 == len(check):
                _verify_emit(k + 1, len(check))
        verified = (bad == 0)
        if verified:
            print(f"  {C.GREEN}✓ Verified {len(check)} file(s){C.RESET}")

    # record EVERY copied file in the dedup DB (complete index of the dest)
    if cache is None and not args.no_dedup and algo:
        cache = SshDedupCache(dst_remote.host, dst)
    if cache is not None:
        all_h = dict(copy_hashes or {})
        all_h.update(vhashes)
        for rel in send_rels:
            h = all_h.get(rel)
            if h:
                cache.record(rel, src_files[rel][0], src_files[rel][1], h)
        cache.close()

    _tar_emit(total, total, len(send_rels) + len(send_links), len(src_files),
              start, final=True)
    _elapsed = time.time() - start
    _refused_now = set(_REFUSED_PATHS)
    _sz = lambda r: src_files.get(r, (0, 0))[0]
    _ssh_done_summary(
        f"{src_remote.user}@{src_remote.host}:{rpath}",
        f"{dst_remote.user}@{dst_remote.host}:{dst}", len(src_files),
        sum(_sz(r) for r in send_rels), _elapsed, "transferred",
        copied=len(send_rels), linked=len(send_links), skipped=len(skipped),
        saved=saved,
        verified=(verified if (not args.no_verify and algo) else None))
    _ssh_record(
        args, f"{src_remote.user}@{src_remote.host}:{rpath}",
        f"{dst_remote.user}@{dst_remote.host}:{dst}", "remote_to_remote",
        total_files=len(src_files),
        total_bytes=sum(v[0] for v in src_files.values()),
        copied=len(send_rels), linked=len(send_links), skipped=len(skipped),
        errors=0,
        bytes_written=sum(_sz(r) for r in rels if r not in _refused_now),
        bytes_refused=sum(_sz(r) for r in _refused_now),
        dedup_saved=saved - sum(_sz(d) for d, _t in links
                                if d in _refused_now),
        elapsed=_elapsed, algo=algo)
    scli.close()
    dcli.close()
    return 0 if (verified and not _REFUSED_PATHS) else 1


def copy_via_tar_ssh(src_remote, dst_remote, dst, local_srcs, args):
    """SSH-only copy via tar over the exec channel (no SFTP). Returns exit code.
    Handles remote→local (pull), local→remote (push), remote→remote (r2r)."""
    if not _load_paramiko():
        print(f"{C.RED}Error: SSH transfers require paramiko.{C.RESET}")
        return 1
    start = time.time()

    try:
        if src_remote and dst_remote:
            return _ssh_r2r_smart(src_remote, dst_remote, dst, args, start)
        elif src_remote:
            return _ssh_pull_smart(src_remote, dst, args, start)
        elif dst_remote:
            return _ssh_push_smart(dst_remote, dst, local_srcs, args, start)
        print(f"{C.RED}Error: --ssh-no-sftp needs a remote source or destination.{C.RESET}")
        return 1
    except Exception as e:
        msg = _fmt_exc(e)
        print(f"{C.RED}Error: {msg}{C.RESET}")
        return 1


# ════════════════════════════════════════════════════════════════════════════
# MAIN
# ════════════════════════════════════════════════════════════════════════════
def main():
    # Capture the creds passphrase out of the environment before we spawn any
    # child process (chattr/setfacl/getfacl/ACL helpers), so the secret is never
    # inherited into their environments. See _scrub_passphrase_env.
    _scrub_passphrase_env()
    # Reset per-run copy-error state. _COPY_ERRORS is a module global; if this
    # process runs more than one copy (e.g. the GUI reuses the interpreter), a
    # stale "permission denied" entry from a prior run could make verify report
    # a genuinely corrupt file as "source skipped" (exit 3) instead of a real
    # copy failure (exit 2). Start each run with a clean slate.
    _COPY_ERRORS.clear()
    _QUIET_STATS.clear()
    # Same reason, same place: the refusal list decides the exit code and the
    # summary's breakdown, so a second run in the same interpreter inheriting
    # the first one's refusals reports files it copied fine as refused and
    # exits 1. Every flow — local, pull, push, relay, cloud, http — is entered
    # through here, so one reset covers all of them and none can drift.
    # The resolved-root cache goes with it: it is keyed by the destination
    # string, and a second run against a recreated path must resolve it again.
    _reset_refused_paths()
    _REAL_ROOT_CACHE.clear()
    parser = argparse.ArgumentParser(
        prog="blitcp",
        description=_tr("Block-order fast copy with dedup — reads files in physical "
                        "disk order, deduplicates identical files. Copies between "
                        "local paths, SSH hosts (user@host:/path), and cloud object "
                        "storage (s3:// / az:// / gs://)."),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=_tr(textwrap.dedent("""\
            subcommands:
              creds <sub>      Manage saved cloud/SSH connection profiles in the
                               credentials file: add, list, edit, remove, test,
                               encrypt/decrypt, lock. Run 'blitcp creds' for help.
              ls <target>      List a cloud location (saved connection name or
                               s3:// / az:// / gs:// URL) or a remote SSH directory
                               (saved ssh connection or user@host:/path, via SFTP).
                               Alias: list-objects. Run 'blitcp ls -h' for help.

            examples:
              blitcp /data /media/usb/data           local  → local
              blitcp /data user@host:/backup         local  → remote (SSH)
              blitcp user@host:/data /local/backup   remote → local
              blitcp /data s3://bucket/backup        local  → cloud
              blitcp creds add aws-dev               save a connection profile
              blitcp ls aws-dev                      list a saved cloud connection
              blitcp ls user@host:/var/log           list a remote SSH directory
            """)),
    )
    # Consumed by the pre-scan in _resolve_lang() before this parser exists;
    # declared here so argparse accepts it and --help documents it.
    parser.add_argument("--lang", metavar="LANG", default=FC_LANG,
                        help=_tr("Message language: {langs}. Overrides "
                                 "BLITCP_LANG and the system locale. "
                                 "Machine output (--log-file) stays English."
                                 ).format(langs=", ".join(I18N_LANGS)) +
                             " (default: %(default)s)")
    parser.add_argument("paths", nargs="*", metavar="SOURCE ... DESTINATION",
                        help=_tr("One or more sources, followed by the destination. A source can be a folder, file, or glob pattern (e.g. *.zip). Multiple sources are copied side-by-side under destination, preserving their basenames (cp -r style). Glob in the basename also works for SSH sources, e.g. user@host:/data/*.tar.gz"))

    copy_grp = parser.add_argument_group(_tr("copy options"))
    copy_grp.add_argument("--buffer", type=int, default=DEFAULT_BUFFER_MB,
                        help=_tr("Buffer size in MB (default: {n})").format(n=DEFAULT_BUFFER_MB))
    copy_grp.add_argument("--threads", type=int, default=DEFAULT_THREADS,
                        help=_tr("Threads for hashing/layout (default: {n})").format(n=DEFAULT_THREADS))
    copy_grp.add_argument("--small-files", choices=["parallel", "stream"],
                        default="parallel",
                        help=_tr("Small-file engine for local copies: "
                                 "'parallel' = worker pool (threads x4, "
                                 "default), 'stream' = single-threaded tar "
                                 "block-stream"))
    copy_grp.add_argument("--cloud-concurrency", type=int,
                        default=DEFAULT_CLOUD_CONCURRENCY,
                        help=_tr("Concurrent uploads/downloads for object storage "
                                "(s3/az/gs). Small-file transfers are latency-bound, "
                                "so this defaults higher than --threads "
                                "(default: {n})").format(n=DEFAULT_CLOUD_CONCURRENCY))
    copy_grp.add_argument("--relay-spool-mb", type=int, default=64,
                        metavar="N",
                        help=_tr("Per-object memory buffer for streaming relays "
                                 "(MB); a single object larger than this spills "
                                 "to a temp file (0 = always spill; default: 64)"))
    copy_grp.add_argument("--dry-run", action="store_true",
                        help=_tr("Show copy plan without copying"))
    copy_grp.add_argument("-v", "--verbose", action="store_true",
                        help=_tr("Verbose output (full FS detection details, etc.)"))
    copy_grp.add_argument("-q", "--quiet", action="store_true",
                        help=_tr("Script mode: no progress bar or banners, one "
                                 "final OK/FAILED line, errors on stderr. The "
                                 "exit code stays the contract (0 ok, 1 corrupt, "
                                 "2 error, 3 source files skipped)."))
    copy_grp.add_argument("-p", "--progress", action="store_true",
                        help=_tr("Quiet, but keep the copy progress bar. Implies "
                                 "--quiet: banners and phase output stay "
                                 "suppressed, the bar and the final OK/FAILED "
                                 "line are all you get."))
    copy_grp.add_argument("--no-verify", action="store_true",
                        help=_tr("Skip post-copy verification"))
    copy_grp.add_argument("--trust-remote-modes", action="store_true",
                        dest="trust_remote_modes",
                        help=_tr("Keep the group/world write bits a remote "
                                 "source sends. Off by default: a pulled file "
                                 "that was 0664 lands 0644, so a machine you "
                                 "do not control cannot decide that what it "
                                 "sends is group-writable on yours. setuid and "
                                 "setgid are stripped either way."))
    copy_grp.add_argument("--log-file", default=None,
                        help=_tr("Write structured JSON log to file"))
    copy_grp.add_argument("--no-dedup", action="store_true",
                        help=_tr("Disable deduplication"))
    copy_grp.add_argument("--dedup-in-sync-folder", action="store_true",
                        dest="dedup_in_sync_folder",
                        help=_tr("Keep hard-link deduplication even when the destination "
                                 "is inside a cloud-synced folder (OneDrive, Dropbox, "
                                 "Google Drive). Off by default: the sync client uploads "
                                 "every path anyway, so links save no remote space, and "
                                 "the shared inode means editing one copy rewrites the "
                                 "other. Windows only; no other platform is affected."))
    copy_grp.add_argument("--hash", choices=["auto", "xxh128", "sha256"],
                        default="auto",
                        help=_tr("Hash algorithm for dedup/verify. auto (default): xxh128 if installed, else sha256. xxh128: force xxh128 (10x faster, non-cryptographic). sha256: force sha256 (cryptographic; collision-resistant)."))
    copy_grp.add_argument("--force", action="store_true",
                        help=_tr("Skip space check, copy even if not enough space"))
    copy_grp.add_argument("--overwrite", action="store_true",
                        help=_tr("Overwrite all files, skip identical-file detection"))
    copy_grp.add_argument("--exclude", action="append", default=[], metavar="PATTERN",
                        help=_tr("Exclude files/dirs by name or glob (e.g. .venv, *.bat, .git*). Matching directories are pruned. Repeatable."))
    copy_grp.add_argument("--include-node-modules", action="store_true",
                        help=_tr("node_modules is excluded by default from BOTH the copy and --index-existing (huge, regenerable, and full of tiny identical files). Pass this to include it."))
    copy_grp.add_argument("--no-cache", action="store_true",
                        help=_tr("Disable persistent hash cache (cross-run dedup database)"))
    copy_grp.add_argument("--dedup-existing", action="store_true",
                        dest="dedup_existing", default=False,
                        help=_tr("While hashing the drive under --index-existing, reclaim space from files ALREADY on the drive that share content: reflink duplicates together via FIDEDUPERANGE (kernel-verified, CoW). Separate from copy-time dedup. Linux/btrfs/XFS only."))
    copy_grp.add_argument("--index-existing", action="append", default=[],
                        metavar="PATH", dest="index_existing",
                        help=_tr("Scan PATH and register files by size in the dedup index. During sync, size-matched files are lazily hashed and reflinkd instead of copied if content matches. Also widens link scope drive-wide: without this flag a copy only links onto content inside its own destination, so a second backup never shares storage with an older one. PATH must be on the same filesystem as the destination. Repeatable for multiple paths."))
    copy_grp.add_argument("--ssh-no-sftp", action="store_true", dest="ssh_no_sftp",
                        help=_tr("Transfer over plain SSH using tar (no SFTP subsystem). For servers with SSH enabled but SFTP disabled (e.g. some NAS). Supports dedup/incremental/verify."))
    copy_grp.add_argument("--sftp-only", action="store_true", dest="sftp_only",
                        help=_tr("Transfer over pure SFTP — never run commands on the server. For SFTP-only endpoints (managed gateways, restricted accounts) that close the exec channel. Incremental and verify work; dedup links and remote space check are skipped."))
    copy_grp.add_argument("--chunk-size", type=int, default=100, metavar="MB",
                        dest="chunk_size",
                        help=_tr("SSH (--ssh-no-sftp) tar batch size in MB (default: 100). Bigger = fewer round-trips; smaller = finer resume granularity. This is NOT --buffer (that's the block-copy I/O buffer)."))
    copy_grp.add_argument("--use-sudo", action="store_true",
                        help=_tr("Re-exec self under sudo if not already root. sudo will prompt for the password on the terminal. Useful when source or destination needs root (e.g. /var/lib/longhorn/replicas). Linux/macOS only."))
    copy_grp.add_argument("--preserve", default=None, metavar="TOKENS",
                        help=_tr("Comma-separated metadata kinds to preserve on the destination: mode,times (default), owner, xattr, acl. Special tokens: all, none. Examples: --preserve=owner,xattr  --preserve=all. Under --use-sudo, --preserve=all is implicit unless you pass --preserve explicitly. Destination filesystems that can't store some metadata (FAT32 for xattrs, etc.) drop those attributes; a one-line summary reports what was preserved vs dropped."))
    copy_grp.add_argument("--progress-json", action="store_true",
                        help=argparse.SUPPRESS)

    ssh_grp = parser.add_argument_group(_tr("ssh options (remote source / destination)"))
    ssh_grp.add_argument("--ssh-dst-port", "--ssh-port", type=int, default=22,
                        dest="ssh_port",
                        help=_tr("SSH port for remote destination (default: 22)"))
    ssh_grp.add_argument("--ssh-dst-key", "--ssh-key", default=None,
                        dest="ssh_key",
                        help=_tr("Path to SSH private key for remote destination"))
    ssh_grp.add_argument("--ssh-dst-password", "--ssh-password", action="store_true",
                        dest="ssh_password",
                        help=_tr("Prompt for SSH password for remote destination"))
    ssh_grp.add_argument("--ssh-dst-password-env", default=None, metavar="VAR",
                        dest="ssh_password_env", help=argparse.SUPPRESS)
    ssh_grp.add_argument("--ssh-strict-host-key-checking", action="store_true",
                        dest="ssh_strict_host_keys",
                        help=_tr("Reject SSH host keys not already in known_hosts instead of the interactive trust-on-first-use prompt. Use for CI/automated runs to prevent first-connection MITM."))
    ssh_grp.add_argument("-z", "--compress", action="store_true",
                        help=_tr("Enable SSH compression (good for slow links)"))
    ssh_grp.add_argument("--ssh-src-port", "--src-port", type=int, default=22,
                        dest="src_port",
                        help=_tr("SSH port for remote source (default: 22)"))
    ssh_grp.add_argument("--ssh-src-key", "--src-key", default=None,
                        dest="src_key",
                        help=_tr("Path to SSH private key for remote source"))
    ssh_grp.add_argument("--ssh-src-password", "--src-password", action="store_true",
                        dest="src_password",
                        help=_tr("Prompt for SSH password for remote source"))
    ssh_grp.add_argument("--ssh-src-password-env", default=None, metavar="VAR",
                        dest="src_password_env", help=argparse.SUPPRESS)

    cloud_grp = parser.add_argument_group(
        "cloud / object storage options (s3:// az:// gs://)")
    cloud_grp.add_argument("--endpoint-url", default=None,
                        help=_tr("Custom S3-compatible endpoint (MinIO, Cloudflare R2, Wasabi, Backblaze B2)."))
    cloud_grp.add_argument("--s3-region", default=None,
                        help=_tr("AWS region for s3:// (default: us-east-1)"))
    cloud_grp.add_argument("--s3-profile", default=None,
                        help=_tr("AWS named profile from ~/.aws/credentials"))
    cloud_grp.add_argument("--az-connection-string", default=None,
                        help=_tr("Azure Blob connection string (or env AZURE_STORAGE_CONNECTION_STRING)"))
    cloud_grp.add_argument("--az-account", default=None,
                        help=_tr("Azure storage account name (with --az-key)"))
    cloud_grp.add_argument("--az-key", default=None,
                        help=_tr("Azure storage account key. WARNING: a key passed on the command line is visible to other users via `ps` and is saved in shell history. Prefer a saved connection (blitcp creds add) or the AZURE_STORAGE_CONNECTION_STRING env var."))
    cloud_grp.add_argument("--gcs-project", default=None,
                        help=_tr("Google Cloud project for gs://"))
    cloud_grp.add_argument("--gcs-credentials", default=None,
                        help=_tr("Path to a GCS service-account JSON key file"))
    cloud_grp.add_argument("--smb-user", default=None,
                        help=_tr("Username for smb:// / UNC shares (overrides any user in the URL)"))
    cloud_grp.add_argument("--smb-domain", default=None,
                        help=_tr("Windows/AD domain for SMB authentication"))
    cloud_grp.add_argument("--smb-port", type=int, default=None,
                        help=_tr("SMB port (default: 445)"))
    cloud_grp.add_argument("--smb-password", action="store_true",
                        help=_tr("Prompt for the SMB password"))
    cloud_grp.add_argument("--smb-password-env", default=None, metavar="VAR",
                        help=argparse.SUPPRESS)
    cloud_grp.add_argument("--smb-no-encrypt", action="store_true",
                        help=_tr("Disable SMB3 transport encryption (on by default)"))
    cloud_grp.add_argument("--http-user", default=None,
                        help=_tr("Username for http(s):// sources (HTTP Basic auth)"))
    cloud_grp.add_argument("--http-password", action="store_true",
                        help=_tr("Prompt for the http(s) source password"))
    cloud_grp.add_argument("--http-password-env", default=None, metavar="VAR",
                        help=argparse.SUPPRESS)
    cloud_grp.add_argument("--http-header-env", default=None, metavar="VAR",
                        help=argparse.SUPPRESS)
    cloud_grp.add_argument("--http-header", action="append", default=None,
                        metavar="'Name: value'",
                        help=_tr("Extra HTTP header for http(s):// sources, repeatable — e.g. \"Authorization: Bearer TOKEN\" or \"Cookie: session=…\" for downloads behind a login or terms page"))
    cloud_grp.add_argument("--cookies", default=None, metavar="FILE",
                        help=_tr("Netscape/Mozilla cookies.txt file for http(s):// sources — reuse a browser login you already have (what a \"cookies.txt\" browser extension exports, same format as curl -b / wget --load-cookies)"))
    cloud_grp.add_argument("--cookies-from-browser", default=None, metavar="BROWSER",
                        help=_tr("Read the LIVE login session for an http(s):// source straight from your browser: chrome, chromium, firefox, edge, brave, opera, safari (or 'browser' to try all). Needs the browser-cookie3 package."))
    cloud_grp.add_argument("--credentials-file", default=None, metavar="PATH",
                        help=_tr("Named-connection file for cloud credentials. Reference a connection by name (e.g. aws-dev, aws-dev:folder) or in a URL as s3://name@bucket/key. Defaults to credentials.json next to blitcp (override with this flag or $BLITCP_CREDENTIALS). Manage it with: blitcp creds add/list/edit/remove/test."))

    info_grp = parser.add_argument_group(_tr("info & self-update"))
    info_grp.add_argument("--version", "-V", action="store_true",
                        help=_tr("Show version and exit"))
    info_grp.add_argument("--check-update", action="store_true",
                        help=_tr("Show available updates and release notes"))
    info_grp.add_argument("--update", nargs="?", const=True, default=False,
                        metavar="VERSION",
                        help=_tr("Download and install latest (or a specific version)"))
    args = parser.parse_args()

    if args.progress_json:
        global PROGRESS_JSON
        PROGRESS_JSON = True

    # --quiet last: it silences the progress stream, so it must win over
    # --progress-json if a caller somehow asks for both. --progress is the
    # same mode with the bar left on, so it implies --quiet rather than
    # being a separate one.
    if args.quiet or args.progress:
        _quiet_enable(keep_progress=args.progress)

    # Before anything happens, not after the summary: see the docstring.
    _maybe_ask_update_consent()

    if getattr(args, "ssh_strict_host_keys", False):
        global _strict_host_keys
        _strict_host_keys = True

    # Split positional paths into (sources..., destination). When 2+ positionals
    # are given, the last one is the destination and any earlier ones are
    # sources — matches `cp src1 src2 ... dst/` semantics.
    args.extra_sources = []
    if len(args.paths) >= 2:
        args.destination = args.paths[-1]
        args.source = args.paths[0]
        args.extra_sources = args.paths[1:-1]
    elif len(args.paths) == 1:
        args.source = args.paths[0]
        args.destination = None
    else:
        args.source = None
        args.destination = None

    # Windows cmd.exe/MSVCRT quirk: a trailing `\"` in a quoted path like
    # "\\host\share\" escapes the closing quote, leaving a literal `"` at
    # the end of the argument. `"` is never valid in a Windows path, so
    # strip it to recover the intended path.
    if _system == "Windows":
        if args.source and args.source.endswith('"'):
            args.source = args.source.rstrip('"')
        if args.destination and args.destination.endswith('"'):
            args.destination = args.destination.rstrip('"')
        args.extra_sources = [
            s.rstrip('"') if s.endswith('"') else s for s in args.extra_sources
        ]

    # These flags are handled in __main__ before main() is called,
    # but if someone somehow reaches here, handle gracefully
    if args.version or args.check_update or args.update:
        parser.exit(0)

    if not args.source or not args.destination:
        parser.error("the following arguments are required: source, destination")

    # Apply hash algorithm selection BEFORE any hashing happens.
    # Must come before dedup, verify, or cache lookups.
    _set_hash_algo(args.hash)

    # ── Named-connection endpoints (profiles) ─────────────────────────
    # Expand `name` / `name:path` endpoints that match a saved connection
    # (cloud or ssh) into their concrete form, and pull any SSH credentials
    # from the profile — before cloud/SSH routing below sees the paths.
    apply_named_endpoints(args)

    # ── Plain HTTP(S) source routing ──────────────────────────────────
    # Per-file recording is switched on HERE, above the routing below, and not
    # after it: the cloud, SMB and HTTP transfers return from inside that
    # routing, so they ran with logging still off and every record they wrote
    # carried an empty `files` list. The counts were there; which file was
    # copied and which was skipped could not be read back from any of them.
    global _log_enabled
    if args.log_file:
        _log_enabled = True
    # When running under sudo, always capture per-file entries so we can
    # write the hidden audit file at the end of the copy.
    if _is_under_sudo():
        _log_enabled = True

    # A bare https://host/dir/file URL as the SOURCE streams that one file to
    # an SSH or SMB destination through this machine — the same relay shape as
    # R2R (in-memory chunks, nothing lands on the local disk). Intercepted
    # BEFORE cloud/SMB routing and parse_remote_path: the latter would misread
    # https://host as an SSH host named 'https'.
    if is_http_url(args.source) or is_http_url(args.destination):
        sys.exit(run_http_transfer(args))

    # ── Object storage routing (v4.0.0) ───────────────────────────────
    # If either endpoint is a cloud URL (s3:// / az:// / gs://) or an SMB/CIFS
    # location (smb:// or a UNC \\host\share), hand off to the object-storage
    # backends. SMB is intercepted HERE, before parse_remote_path below, which
    # would otherwise misread smb://host as an SSH host. The local/SSH engine
    # handles only plain filesystem and SSH paths.
    if (is_cloud_path(args.source) or is_cloud_path(args.destination)
            or _route_as_smb(args.source, args)
            or _route_as_smb(args.destination, args)):
        run_cloud_transfer(args)
        return

    # ── --preserve resolution ────────────────────────────────────────
    # Default: mode + times (matches v3.1.x). When --use-sudo and no
    # explicit --preserve, promote to 'all' since /etc backups without
    # ownership are usually useless. When user passed --preserve, honor
    # exactly what they asked.
    try:
        if args.preserve is None:
            if _is_under_sudo() or args.use_sudo:
                spec = PreserveSpec.from_tokens("all")
            else:
                spec = PreserveSpec()  # mode + times
        else:
            spec = PreserveSpec.from_tokens(args.preserve)
    except ValueError as e:
        parser.error(str(e))
    _set_preserve_spec(spec)
    _set_trust_remote_modes(getattr(args, "trust_remote_modes", False))

    src_arg = args.source
    buf_size = args.buffer * 1024 * 1024

    # ── Detect remote source and destination ──────────────────────────
    src_remote = parse_remote_path(src_arg)
    dst_remote = parse_remote_path(args.destination)

    # Check paramiko is installed if SSH is needed
    if (src_remote or dst_remote) and not _load_paramiko():
        print(f"\n  {C.RED}Error: SSH transfers require paramiko.{C.RESET}")
        print(f"  Install it with: {C.BOLD}python -m pip install paramiko{C.RESET}\n")
        sys.exit(1)

    # --preserve scope: owner/xattr/ACL now round-trip across L2L, L2R,
    # R2L, and R2R. Remote operations require python3 on the relevant
    # endpoint; at copy time we emit a clear message if it's missing.

    # One-time warning if xxhash is not installed
    if _hash_name != "xxh128":
        print(f"  {C.YELLOW}Note: xxhash not installed — using SHA-256 (slower).{C.RESET}")
        print(f"  {C.DIM}Install for ~10x faster hashing: python -m pip install xxhash{C.RESET}")

    if src_remote:
        src_remote = src_remote._replace(port=args.src_port)
    if dst_remote:
        dst_remote = dst_remote._replace(port=args.ssh_port)

    # Validate SSH key paths early
    for label, keypath in [("--ssh-key", args.ssh_key), ("--src-key", args.src_key)]:
        if keypath and not os.path.isfile(keypath):
            print(f"{C.RED}Error: {label} file not found: {keypath}{C.RESET}")
            sys.exit(1)

    # Keep 'remote' alias for backward compat with existing local→remote code
    remote = dst_remote

    if dst_remote:
        dst = dst_remote.path
    else:
        dst = os.path.abspath(args.destination)

    # ── Resolve source ───────────────────────────────────────────────
    src_mode = None  # "dir", "file", "glob", "multi", "remote", or "remote_glob"
    glob_files = []
    multi_sources = []  # absolute paths, set when src_mode == "multi"
    remote_glob_pattern = None  # set when src_mode == "remote_glob"

    if args.extra_sources and src_remote:
        print(f"{C.RED}Error: multi-source mode does not support SSH sources "
              f"(got remote source with {len(args.extra_sources)} additional path"
              f"{'s' if len(args.extra_sources) != 1 else ''}){C.RESET}")
        sys.exit(1)

    if args.extra_sources:
        # Multi-source: shell-expanded glob (e.g. `pvc-*`) or N explicit paths
        # on the command line. Each source becomes its own subtree under
        # destination, preserving its basename (cp -r style).
        all_src = [src_arg] + args.extra_sources
        for s in all_src:
            if parse_remote_path(s):
                print(f"{C.RED}Error: multi-source mode does not support SSH sources "
                      f"(got '{s}'){C.RESET}")
                sys.exit(1)
            if not os.path.exists(s):
                print(f"{C.RED}Error: source not found: {s}{C.RESET}")
                sys.exit(1)
        multi_sources = [os.path.abspath(s) for s in all_src]
        src_mode = "multi"
        src = os.path.commonpath(multi_sources)
        if not os.path.isdir(src):
            src = os.path.dirname(src)
        _shown = ", ".join(os.path.basename(p.rstrip(os.sep))
                           for p in multi_sources[:2])
        if len(multi_sources) > 2:
            _shown += f", +{len(multi_sources) - 2} more"
        src_display = f"{len(multi_sources)} sources ({_shown}) under {src}"
    elif src_remote:
        # Detect a glob pattern in the basename — the only place we support
        # it. A glob in a middle component (e.g. /foo/*/bar) would require
        # a recursive remote walk, which is out of scope here.
        rpath = src_remote.path
        rbase = posixpath.basename(rpath)
        rparent = posixpath.dirname(rpath)
        _glob_chars = set("*?[")
        if any(c in rbase for c in _glob_chars):
            if any(c in rparent for c in _glob_chars):
                print(f"{C.RED}Error: glob characters are only supported in the "
                      f"final path component for remote sources.{C.RESET}")
                sys.exit(1)
            src = rparent if rparent else "."
            src_mode = "remote_glob"
            remote_glob_pattern = rbase
            src_display = f"{src_remote.user}@{src_remote.host}:{rpath}"
        else:
            src = rpath
            src_mode = "remote"
            src_display = f"{src_remote.user}@{src_remote.host}:{src}"
    else:
        src = os.path.abspath(src_arg)
        if os.path.isdir(src):
            src_mode = "dir"
        elif os.path.isfile(src):
            src_mode = "file"
        else:
            # Try glob expansion (handles wildcards like *.zip)
            glob_files = sorted(globmod.glob(src_arg))
            if not glob_files:
                glob_files = sorted(globmod.glob(src))
            glob_files = [f for f in glob_files if os.path.isfile(f)]
            if glob_files:
                src_mode = "glob"
            else:
                print(f"{C.RED}Error: Source '{src_arg}' — no matching files or directory found{C.RESET}")
                sys.exit(1)

        if src_mode == "glob":
            src_display = src_arg
            src = os.path.commonpath([os.path.abspath(f) for f in glob_files])
            if os.path.isfile(src):
                src = os.path.dirname(src)
        elif src_mode == "file":
            src_display = src
        else:
            src_display = src

    # Detect destination filesystem early so we can fold the strategy
    # into the Dedup banner line and use it for Phase 2/3.
    fs_info = None
    fs_error = None
    if not dst_remote:
        try:
            fs_info = detect_capabilities(
                dst,
                dedup_in_sync_folder=getattr(args, "dedup_in_sync_folder", False))
        except Exception as e:
            fs_error = str(e)
        # Probe destination for extended-metadata support upfront if the
        # user asked for xattr or ACL preservation, so we can warn early
        # and fall back gracefully on unsupported filesystems (FAT32, etc).
        if _preserve_spec.xattr:
            _probe_dst_xattr_support(dst)
        if _preserve_spec.acl:
            _probe_dst_acl_support(dst)

    banner("FAST BLOCK-ORDER COPY")
    print(f"  Source:      {C.BOLD}{src_display}{C.RESET}")
    if src_mode == "remote":
        print(f"               {C.DIM}(SSH remote, port {src_remote.port}){C.RESET}")
    elif src_mode == "remote_glob":
        print(f"               {C.DIM}(SSH remote glob, port {src_remote.port}){C.RESET}")
    elif src_mode == "glob":
        print(f"               {C.DIM}{len(glob_files)} files matched{C.RESET}")
    elif src_mode == "multi":
        print(f"               {C.DIM}{len(multi_sources)} sources "
              f"(cp -r style){C.RESET}")
    elif src_mode == "file":
        print(f"               {C.DIM}(single file){C.RESET}")
    if dst_remote:
        print(f"  Destination: {C.BOLD}{dst_remote.user}@{dst_remote.host}:{dst}{C.RESET}")
        print(f"               {C.DIM}(SSH remote, port {dst_remote.port}){C.RESET}")
    else:
        print(f"  Destination: {C.BOLD}{dst}{C.RESET}")
        _stype = _classify_storage(dst)
        if _stype != "unknown":
            _slabel = {"hdd": "HDD (rotating)", "ssd": "SSD / flash",
                       "network": "network (SMB / NFS / SSHFS)",
                       "other": "memory / other"}.get(_stype, _stype)
            print(f"               {C.DIM}disk: {_slabel}{C.RESET}")
    if src_remote and dst_remote:
        print(f"  Mode:        {C.CYAN}remote → remote (relay through local){C.RESET}")
    elif src_remote:
        print(f"  Mode:        {C.CYAN}remote → local{C.RESET}")
    elif dst_remote:
        print(f"  Mode:        {C.CYAN}local → remote{C.RESET}")
    print(f"  Buffer:      {args.buffer} MB")
    # Said out loud, like --no-verify is: a run where the remote decides the
    # permission bits should not look like a run where it does not.
    if getattr(args, "trust_remote_modes", False):
        print(f"  Modes:       {C.YELLOW}"
              + _tr("permission bits taken from the remote "
                    "(--trust-remote-modes)") + f"{C.RESET}")
    # Dedup line: fold FS strategy in parens when detected
    if args.no_dedup:
        print(f"  Dedup:       disabled")
    elif fs_info is not None:
        print(f"  Dedup:       enabled ({C.CYAN}{fs_info.strategy}{C.RESET})")
        # A strategy weaker than the filesystem allows is a decision the user
        # did not make, so it is said out loud rather than left to --verbose.
        if fs_info.strategy_note:
            print(f"               {C.YELLOW}{fs_info.strategy_note}{C.RESET}")
    else:
        print(f"  Dedup:       enabled")
    # Hash algorithm + source (auto vs forced). Non-cryptographic xxh128
    # is marked so users understand the trust boundary.
    if not args.no_dedup:
        if _hash_name == "xxh128":
            _hash_note = (f"{C.DIM}(non-cryptographic; "
                          f"{'default' if _hash_source == 'auto' else 'forced'}){C.RESET}")
        else:  # sha256
            _hash_note = (f"{C.DIM}(cryptographic; "
                          f"{'fallback' if _hash_source == 'auto' else 'forced'}){C.RESET}")
        print(f"  Hash:        {C.BOLD}{_hash_name}{C.RESET} {_hash_note}")
    if not src_remote and not dst_remote:
        print(f"  Hash cache:  {'disabled' if args.no_cache else 'enabled'}")
    print(f"  Overwrite:   {'always' if args.overwrite else 'skip identical'}")
    # Show Preserve only when more than the default mode+times is requested,
    # so the banner stays quiet for typical copies.
    _spec_on = [k for k in PreserveSpec.KINDS if getattr(_preserve_spec, k)]
    _spec_extended = [k for k in ("owner", "xattr", "acl") if getattr(_preserve_spec, k)]
    if _spec_extended:
        _spec_note = ""
        if _preserve_spec.xattr and _preserve_dst_caps["xattr"] is False:
            _spec_note = f" {C.YELLOW}(dst FS does not support xattrs){C.RESET}"
        if _preserve_spec.acl and _preserve_dst_caps["acl"] is False:
            _spec_note += f" {C.YELLOW}(dst FS does not support ACLs){C.RESET}"
        print(f"  Preserve:    {C.BOLD}{','.join(_spec_on)}{C.RESET}{_spec_note}")
    if (src_remote or dst_remote) and args.compress:
        print(f"  Compression: {C.GREEN}enabled{C.RESET}")
    print(f"  Platform:    {_system}")

    # Verbose: full FS capability breakdown (with -v / --verbose)
    if getattr(args, "verbose", False) and fs_info is not None:
        caps = fs_info.capabilities
        print(f"  FS:          {C.BOLD}{fs_info.fs_type}{C.RESET} → "
              f"{C.CYAN}{fs_info.strategy}{C.RESET}")
        print(f"               {C.DIM}hardlink={'y' if caps.hardlink else 'n'} "
              f"symlink={'y' if caps.symlink else 'n'} "
              f"reflink={'y' if caps.reflink else 'n'} "
              f"case={'sens' if caps.case_sensitive else 'insens'}{C.RESET}")
        print(f"               {C.DIM}detect={fs_info.detection_ms:.1f}ms "
              f"probe={fs_info.probe_ms:.1f}ms "
              f"({len(fs_info.probes_run)} probe"
              f"{'s' if len(fs_info.probes_run) != 1 else ''}){C.RESET}")
    elif fs_error:
        print(f"  FS:          {C.YELLOW}detection failed: {fs_error}{C.RESET}")

    print()

    if getattr(args, "_saved_protocol_note", None) and (src_remote or dst_remote):
        print(f"  {C.DIM}SSH transport: {args._saved_protocol_note}{C.RESET}")

    # ── SFTP-only sanity checks (pure SFTP, no remote shell) ────────────
    if getattr(args, "sftp_only", False):
        if getattr(args, "ssh_no_sftp", False):
            print(f"{C.RED}Error: --sftp-only and --ssh-no-sftp are mutually exclusive.{C.RESET}")
            sys.exit(1)
        if not (src_remote or dst_remote):
            print(f"{C.RED}Error: --sftp-only needs a remote source or destination.{C.RESET}")
            sys.exit(1)
        if src_remote and dst_remote:
            print(f"{C.RED}Error: --sftp-only does not support remote-to-remote copies.{C.RESET}")
            sys.exit(1)

    # ── Auto-detect a server with SSH on and SFTP off ──────────────────
    # The transport is chosen here, but the first SFTP call happens after the
    # scan — so a server without the subsystem used to die mid-run. One probe
    # now picks the tar-over-exec transport for the whole copy instead.
    # --sftp-only is an explicit choice and is never overridden: it is
    # reported as a failure, because quietly opening a shell on a host the
    # user restricted to SFTP is the one thing that flag exists to prevent.
    if ((src_remote or dst_remote)
            and not getattr(args, "ssh_no_sftp", False)
            and not getattr(args, "sftp_only", False)):
        _probe_spec = src_remote or dst_remote
        if src_remote:
            _probe_key = args.src_key
            _probe_pw = _resolved_src_pw(args)
            if not _probe_pw and args.src_password:
                _probe_pw = getpass.getpass(
                    f"Password for {src_remote.user}@{src_remote.host}: ")
                args._resolved_src_password = _probe_pw   # never ask twice
        else:
            _probe_key = args.ssh_key
            _probe_pw = _resolved_dst_pw(args)
            if not _probe_pw and getattr(args, "ssh_password", False):
                _probe_pw = getpass.getpass(
                    f"Password for {dst_remote.user}@{dst_remote.host}: ")
                args._resolved_dst_password = _probe_pw
        _ok, _perr = _sftp_subsystem_ok(_probe_spec, _probe_key, _probe_pw,
                                        args.compress)
        if not _ok:
            # Silent, like the shell fallback in _ssh_ls: each SSH-only path
            # banners itself as "SSH (no SFTP)", so the transport is already
            # visible without a warning on every run.
            args.ssh_no_sftp = True

    # ── SSH-only (no SFTP) fast path: tar over the exec channel ─────────
    if getattr(args, "ssh_no_sftp", False) and (src_remote or dst_remote):
        _tar_local_srcs = None
        if not src_remote:
            _tar_local_srcs = (multi_sources if args.extra_sources else [src_arg])
        sys.exit(copy_via_tar_ssh(src_remote, dst_remote, dst, _tar_local_srcs, args))

    # ── Connect to remote source if needed ─────────────────────────────
    src_ssh = None
    if src_remote:
        banner("SSH — Connecting to source")
        src_password = None
        if args.src_password_env:
            src_password = os.environ.get(args.src_password_env)
        elif args.src_password:
            src_password = getpass.getpass(f"Password for {src_remote.user}@{src_remote.host}: ")
        elif getattr(args, "_resolved_src_password", None):
            src_password = args._resolved_src_password
        src_ssh = SSHConnection(src_remote, port=src_remote.port, key_path=args.src_key,
                                password=src_password, compress=args.compress,
                                sftp_only=getattr(args, "sftp_only", False),
                                ).connect()
        print(f"  {C.GREEN}Connected to {src_remote.user}@{src_remote.host}:{src_remote.port}{C.RESET}")
        if src_ssh.sftp_only:
            print(f"  {C.DIM}SFTP-only mode — no commands are run on the server{C.RESET}")
        else:
            caps = [k for k, v in src_ssh.caps.items() if v]
            print(f"  {C.DIM}Remote tools: {', '.join(caps) or 'none detected'}{C.RESET}")

    # ── Phase 1: Scan ─────────────────────────────────────────────────
    banner("Phase 1 — Scanning source")

    if src_mode == "remote":
        entries, errors = scan_remote_source(
            src_ssh, src, args.exclude,
            include_node_modules=args.include_node_modules)
        # If the remote source was a single file (not a directory), the find
        # command returns rel="." because relpath(file, file) == ".".
        # Fix rel to the basename and adjust src to the parent directory,
        # mirroring the local "file" mode logic, so that tar cd works.
        if len(entries) == 1 and entries[0].rel == ".":
            fname = posixpath.basename(src)
            entries[0] = entries[0]._replace(rel=fname)
            src = posixpath.dirname(src)
    elif src_mode == "remote_glob":
        # Expand the basename glob via SFTP listdir + fnmatch. src is already
        # the parent directory; remote_glob_pattern is the basename pattern.
        sftp = src_ssh.open_sftp()
        try:
            attrs = sftp.listdir_attr(src)
        except IOError as e:
            print(f"\n  {C.RED}Error: cannot list remote directory "
                  f"{src!r}: {e}{C.RESET}")
            src_ssh.close()
            sys.exit(1)
        matched = [a for a in attrs
                   if fnmatch.fnmatch(a.filename, remote_glob_pattern)
                   and not stat.S_ISDIR(a.st_mode or 0)]
        # Honor --exclude on basename
        if args.exclude:
            matched = [a for a in matched
                       if not any(fnmatch.fnmatch(a.filename, p)
                                  for p in args.exclude)]
        if not matched:
            print(f"\n  {C.RED}Error: no remote files matched "
                  f"{remote_glob_pattern!r} in {src}{C.RESET}")
            src_ssh.close()
            sys.exit(1)
        entries = []
        errors = []
        for a in matched:
            entries.append(FileEntry(
                src=posixpath.join(src, a.filename),
                rel=a.filename,
                size=a.st_size or 0,
                physical_offset=0,
                content_hash=None,
            ))
        print(f"  {C.GREEN}Found {len(entries)} file(s){C.RESET} "
              f"matching {C.BOLD}{remote_glob_pattern}{C.RESET} in {src}")
    elif src_mode == "file":
        fname = os.path.basename(src)
        st = os.stat(src)
        entries = [FileEntry(src=src, rel=fname, size=st.st_size,
                             physical_offset=0, content_hash=None,
                             alloc_size=_detect_sparse_alloc(st))]
        errors = []
        print(f"  {C.GREEN}Found 1 file{C.RESET} ({fmt_size(st.st_size)})")
        src = os.path.dirname(src)
    elif src_mode == "glob":
        entries = []
        errors = []
        for fpath in glob_files:
            abs_f = os.path.abspath(fpath)
            try:
                rel = os.path.relpath(abs_f, src)
            except ValueError as e:
                # Glob match on a different mount than the source (junction /
                # device redirect, e.g. \\.\nul) — skip, don't crash the scan.
                errors.append((abs_f, f"cross-mount path skipped ({e})"))
                continue
            try:
                st = os.stat(abs_f)
                entries.append(FileEntry(src=abs_f, rel=rel, size=st.st_size,
                                         physical_offset=0, content_hash=None,
                                         alloc_size=_detect_sparse_alloc(st)))
            except OSError as e:
                errors.append((abs_f, str(e)))
        print(f"  {C.GREEN}Found {len(entries)} files{C.RESET}")
    elif src_mode == "multi":
        # cp -r src1 src2 ... dst/  → each source preserves its basename
        # under destination. Directories are walked; files are added directly.
        entries = []
        errors = []
        for s in multi_sources:
            base = os.path.basename(s.rstrip(os.sep)) or s
            if os.path.isfile(s):
                try:
                    st = os.stat(s)
                    alloc = _detect_sparse_alloc(st)
                    entries.append(FileEntry(src=s, rel=base, size=st.st_size,
                                             physical_offset=0, content_hash=None,
                                             alloc_size=alloc))
                except OSError as e:
                    errors.append((s, str(e)))
            elif os.path.isdir(s):
                sub_entries, sub_errors = scan_source(
                    s, dst if not dst_remote else None, args.exclude,
                    include_node_modules=args.include_node_modules
                )
                for e in sub_entries:
                    new_rel = f"{base}/{e.rel}" if e.rel and e.rel != "." else base
                    entries.append(e._replace(rel=new_rel))
                errors.extend(sub_errors)
        print(f"  {C.GREEN}Found {len(entries)} files{C.RESET} "
              f"across {len(multi_sources)} sources")
    else:
        entries, errors = scan_source(
            src, dst if not dst_remote else None, args.exclude,
            include_node_modules=args.include_node_modules)

    if not entries:
        print(f"  {C.YELLOW}No files found.{C.RESET}")
        if src_ssh:
            src_ssh.close()
        sys.exit(0)

    # ── Single-file destination rename ───────────────────────────────
    # When copying a single file, allow the destination to be a file path
    # (like cp/scp): blitcp host:file.tar.gz /local/renamed.tar.gz
    # Detect this when the destination looks like a file (has a dot-extension
    # in the basename, or already exists as a file) and is not an existing
    # directory.  Adjust dst to parent dir and rename the entry.
    # For remote sources, we track the rename separately (via case_renames)
    # because entry.rel must stay as the original filename for tar to find it.
    _dst_file_rename = None  # (new_rel, old_rel) if file-destination detected
    if len(entries) == 1 and (src_mode in ("file", "remote", "remote_glob") or
                              (src_mode == "glob" and len(glob_files) == 1)):
        _detected = False
        if dst_remote:
            dst_base = posixpath.basename(dst)
            dst_parent = posixpath.dirname(dst)
            # Use splitext to require a real extension — avoids false positives
            # on hidden dirs like .outputs, .config (no extension after the dot).
            _, ext = posixpath.splitext(dst_base)
            if dst_parent and ext and not dst.endswith("/"):
                _detected = True
                dst = dst_parent
        else:
            if not os.path.isdir(dst) and not dst.endswith(("/", os.sep)):
                dst_base = os.path.basename(dst)
                dst_parent = os.path.dirname(dst)
                _, ext = os.path.splitext(dst_base)
                is_file_target = os.path.isfile(dst) or bool(ext)
                if is_file_target and dst_parent:
                    _detected = True
                    dst = dst_parent

        if _detected:
            old_rel = entries[0].rel
            if src_remote:
                # For remote sources, keep entry.rel as-is (tar needs it).
                # The rename is applied via case_renames during extraction.
                _dst_file_rename = (dst_base, old_rel)
            else:
                # For local sources, we can rename entry.rel directly since
                # the file is read by its absolute src path, not rel.
                entries[0] = entries[0]._replace(rel=dst_base)
            print(f"  {C.DIM}Destination is a file path — "
                  f"saving as {dst_base}{C.RESET}")

    total_size = sum(e.size for e in entries)
    total_files = len(entries)
    avg_size = total_size / total_files if total_files else 0
    print(f"  Total: {C.BOLD}{fmt_size(total_size)}{C.RESET} in "
          f"{C.BOLD}{total_files}{C.RESET} files  "
          f"(avg {fmt_size(avg_size)}/file)")

    # Sparse-file summary: surface VM-image / sparse-replica savings up front
    # so the user understands why "Data to write" is much smaller than "Total".
    sparse_entries = [e for e in entries if e.alloc_size is not None]
    if sparse_entries:
        sparse_logical = sum(e.size for e in sparse_entries)
        sparse_alloc = sum(e.alloc_size for e in sparse_entries)
        print(f"  Sparse: {C.BOLD}{len(sparse_entries)}{C.RESET} sparse files — "
              f"{fmt_size(sparse_logical)} logical, "
              f"{C.GREEN}{fmt_size(sparse_alloc)}{C.RESET} on disk "
              f"({fmt_size(sparse_logical - sparse_alloc)} skippable as holes)")

    # ── Phase 2: Deduplication ───────────────────────────────────────
    # Opening the hash cache is itself a write, so a preview must not do it:
    # this created the destination and a ~36 KB SQLite file inside it, which
    # made `blitcp src /typo/path --dry-run` leave the typo behind as a real
    # directory. It stayed invisible because DedupDB prefers the mount root
    # and only falls back to the destination — wherever /tmp is its own mount
    # the file landed in /tmp, outside everything a test thought to look at,
    # and only on a machine with /tmp on / did it appear where it could be
    # caught. Skipping the cache costs a preview nothing: it is the path
    # `--dry-run --no-cache` already takes, and the file counts are identical.
    dedup_db = None
    if (not src_remote and not dst_remote and not args.no_dedup
            and not args.no_cache and not getattr(args, 'dry_run', False)):
        _makedirs_or_die(dst)
        try:
            dedup_db = DedupDB(dst)
        except Exception as e:
            print(f"  {C.YELLOW}Warning: could not open hash cache: {e}{C.RESET}")

    if dedup_db and getattr(args, 'index_existing', []):
        banner("Phase 1b — Indexing existing files")
        if getattr(args, 'dry_run', False):
            # A --dry-run is a pure preview: no DB writes, no whole-drive hashing,
            # and above all no FIDEDUPERANGE extent mutations from --dedup-existing.
            print(f"  {C.DIM}--dry-run: skipping (no hashing / DB writes / "
                  f"in-place dedup during a preview){C.RESET}")
        else:
            # Indexing a path outside the destination is only useful if we may
            # then link onto it, so this flag is what widens the scope.
            dedup_db.link_scope_drive_wide = True
            for idx_path in args.index_existing:
                dedup_db.index_existing(
                    os.path.abspath(idx_path), threads=args.threads,
                    include_node_modules=args.include_node_modules,
                    dedup_inplace=getattr(args, 'dedup_existing', False))

    link_map = {}
    saved_bytes = 0
    copy_entries = entries

    # Use the fs_info detected earlier (before the banner) to decide the
    # dedup strategy. On link-capable filesystems (ext4, btrfs, XFS, NTFS,
    # APFS, ReFS, etc.) dedup saves both bandwidth and disk. On
    # link-incapable filesystems (FAT32, exFAT) dedup saves only bandwidth
    # because each duplicate is materialized as a full copy.
    fs_strategy = fs_info.strategy if fs_info is not None else None

    if not args.no_dedup:
        banner("Phase 2 — Deduplication")
        if src_remote:
            copy_entries, link_map, saved_bytes = deduplicate_remote_source(
                entries, src_ssh, src, args.threads, fs_strategy=fs_strategy)
        else:
            # Remote destinations keep the full pre-hash: the manifest they
            # write is the incremental hash cache for every future run, so
            # missing hashes there would trade one read now for re-hashing
            # (or re-downloading, on SFTP-only) later. Local destinations
            # never consume the hashes post-copy → selective pre-hash.
            copy_entries, link_map, saved_bytes = deduplicate(
                entries, args.threads, dedup_db, fs_strategy=fs_strategy,
                dedup_inplace=getattr(args, 'dedup_existing', False),
                dry_run=getattr(args, 'dry_run', False),
                selective=not dst_remote)

    # SFTP-only destination: links need a shell on the server, so duplicates
    # can't be materialized as links — put them back and upload them in full.
    if getattr(args, "sftp_only", False) and dst_remote and link_map:
        print(f"  {C.YELLOW}" + _tr("SFTP-only: {n} duplicates will be uploaded in full (links need a shell)").format(n=len(link_map)) + C.RESET)
        uniq_rels = {e.rel for e in copy_entries}
        canon_hash = {e.rel: e.content_hash for e in copy_entries}
        for e in entries:
            tgt = link_map.get(e.rel)
            if tgt is not None and e.rel not in uniq_rels:
                h = canon_hash.get(tgt) if isinstance(tgt, str) else None
                copy_entries.append(e._replace(content_hash=h))
        link_map = {}
        saved_bytes = 0

    unique_size = sum(e.size for e in copy_entries)

    # ── Case-conflict resolution for local destinations ─────────────
    case_renames = {}
    if not dst_remote:
        copy_entries, link_map, case_renames = resolve_case_conflicts(
            copy_entries, link_map, dst)

    # Inject file-destination rename for remote-source copies.
    # case_renames maps {original_rel: new_rel} — _stream_tar_batch_from_remote
    # uses this to fetch by original name and extract as new name.
    # For R2R: tar pipe has no rename mechanism, so rename after copy.
    if _dst_file_rename is not None:
        new_rel, old_rel = _dst_file_rename
        if src_remote and not dst_remote:
            # R2L: inject into case_renames (original → new) and update
            # entry.rel to new name for verify/incremental checks.
            case_renames[old_rel] = new_rel
            for i, e in enumerate(copy_entries):
                if e.rel == old_rel:
                    copy_entries[i] = e._replace(rel=new_rel)
                    break
        elif src_remote and dst_remote:
            # R2R: can't rename during tar pipe — will rename after copy.
            # _dst_file_rename stays set; handled after copy_hybrid_r2r.
            pass

    # ══════════════════════════════════════════════════════════════════
    # REMOTE → REMOTE FLOW
    # ══════════════════════════════════════════════════════════════════
    if src_remote and dst_remote:
        dst_ssh = None
        try:
            # ── Connect to destination ───────────────────────────────
            banner("SSH — Connecting to destination")
            dst_password = None
            if args.ssh_password_env:
                dst_password = os.environ.get(args.ssh_password_env)
            elif args.ssh_password:
                dst_password = getpass.getpass(f"Password for {dst_remote.user}@{dst_remote.host}: ")
            elif getattr(args, "_resolved_dst_password", None):
                dst_password = args._resolved_dst_password
            dst_ssh = SSHConnection(dst_remote, port=dst_remote.port, key_path=args.ssh_key,
                                    password=dst_password, compress=args.compress,
                                    ).connect()
            print(f"  {C.GREEN}Connected to {dst_remote.user}@{dst_remote.host}:{dst_remote.port}{C.RESET}")
            caps = [k for k, v in dst_ssh.caps.items() if v]
            print(f"  {C.DIM}Remote tools: {', '.join(caps) or 'none detected'}{C.RESET}")

            # Asked before ensure_remote_root for the same reason as the push
            # path: that call creates the destination and writes a probe into
            # it, which is a write through the symlink under question.
            _dst_escape = _remote_dest_path_escape(
                _sftp_abs_probe(dst_ssh), dst, _sftp_remote_cwd(dst_ssh))

            # Same pre-flight as the push path: relaying gigabytes between two
            # servers only to find the far end unwritable is the worst place
            # to learn it.
            if not args.dry_run and not _dst_escape:
                _dst_problem = ensure_remote_root(dst_ssh, dst)
                if _dst_problem:
                    print(f"\n  {C.RED}Error: cannot use destination "
                          f"{dst}: {_dst_problem}{C.RESET}")
                    dst_ssh.close()
                    sys.exit(1)

            # ── Phase 2b: Incremental check against remote dest ──────
            skipped_count = 0
            skipped_bytes = 0

            if not args.overwrite:
                banner("Phase 2b — Remote incremental check")
                try:
                    copy_entries, link_map, skipped_count, skipped_bytes = \
                        filter_unchanged_remote(copy_entries, link_map, dst_ssh, dst,
                                                src_ssh=src_ssh, src_root=src)
                    unique_size = sum(e.size for e in copy_entries)
                except Exception as e:
                    print(f"  {C.YELLOW}Incremental check failed ({e}) — copying all files{C.RESET}")
                    # Reconnect destination in case the channel died
                    try:
                        dst_ssh.close()
                    except Exception:
                        pass
                    dst_ssh = SSHConnection(dst_remote, port=dst_remote.port, key_path=args.ssh_key,
                                            password=dst_password, compress=args.compress,
                                            ).connect()

                if not copy_entries and not link_map:
                    banner("DONE — Nothing to copy")
                    print(f"  All {skipped_count} files are already up to date on remote.")
                    if args.log_file:
                        write_log_file(args.log_file, {
                            "source": f"{src_remote.user}@{src_remote.host}:{src}",
                            "destination": f"{dst_remote.user}@{dst_remote.host}:{dst}",
                            "mode": "remote_to_remote", "total_files": total_files,
                            "copied": 0, "linked": 0, "skipped": skipped_count,
                            "errors": 0, "total_bytes": total_size, "bytes_written": 0,
                            "dedup_saved": saved_bytes, "elapsed_sec": 0,
                            "avg_speed_bps": 0, "hash_algo": _hash_name,
                        })
                    print()
                    src_ssh.close()
                    dst_ssh.close()
                    sys.exit(0)

            # ── Phase 3: Space check on dest ─────────────────────────
            banner("Phase 3 — Space check (remote destination)")
            # Destination-path policy on the far side. The names come from a
            # remote SOURCE here, so they are untrusted whatever the local
            # process's privilege is — the same answer _dest_policy gives a
            # pull.
            _report_entries, _report_links = copy_entries, link_map
            if _dst_escape:
                _dst_refused = set([e.rel for e in copy_entries]
                                   + list(link_map or {}))
                _dst_found = [{"rel": "", "target": _dst_escape[1],
                               "count": len(_dst_refused)}]
            else:
                _is_link, _realpath = _sftp_dest_probe(dst_ssh, dst)
                _dst_refused, _dst_found = _remote_dest_refusals(
                    dst, [e.rel for e in copy_entries] + list(link_map or {}),
                    _is_link, _realpath)
            copy_entries, link_map = _refuse_remote_dest(
                dst, copy_entries, link_map, _dst_refused, _dst_found)
            unique_size = sum(e.size for e in copy_entries)
            required = unique_size
            print(f"  Data to write: {C.BOLD}{fmt_size(required)}{C.RESET}"
                  + (f" (after dedup saved {fmt_size(saved_bytes)})" if saved_bytes > 0 else ""))

            if not check_remote_space(dst_ssh, dst, required, args.force, entries=copy_entries):
                src_ssh.close()
                dst_ssh.close()
                sys.exit(1)

            if args.dry_run:
                small, large = split_by_size(copy_entries)
                small_sz = sum(e.size for e in small)
                large_sz = sum(e.size for e in large)
                print(f"\n  {C.YELLOW}DRY RUN — Copy strategy:{C.RESET}\n")
                print(f"    Small files (<1MB): {C.BOLD}{len(small)}{C.RESET} files, "
                      f"{C.BOLD}{fmt_size(small_sz)}{C.RESET} → tar pipe relay")
                print(f"    Large files (≥1MB): {C.BOLD}{len(large)}{C.RESET} files, "
                      f"{C.BOLD}{fmt_size(large_sz)}{C.RESET} → SFTP relay")
                if link_map:
                    print(f"\n  Plus {len(link_map)} duplicate files to be linked on remote")
                print(f"\n  Unique data: {fmt_size(unique_size)}")
                _plan_record(
                    args, f"{src_remote.user}@{src_remote.host}:{src}",
                    f"{dst_remote.user}@{dst_remote.host}:{dst}",
                    "remote_to_remote", total_files, _report_entries,
                    _report_links, skipped_count, total_size, saved_bytes,
                    skipped_bytes, refused=_dst_refused)
                src_ssh.close()
                dst_ssh.close()
                sys.exit(0)

            # ── Phase 5: Remote-to-remote copy ───────────────────────
            banner("Phase 5 — Remote-to-remote copy (relay)")

            # Check if buffer fits in available RAM
            try:
                import psutil
                avail = psutil.virtual_memory().available
            except ImportError:
                avail = None
                if _system == "Linux":
                    try:
                        with open("/proc/meminfo") as f:
                            for line in f:
                                if line.startswith("MemAvailable:"):
                                    avail = int(line.split()[1]) * 1024
                                    break
                    except (OSError, ValueError):
                        pass
                elif _system == "Darwin":
                    try:
                        import subprocess
                        # Get actual page size (4KB Intel, 16KB Apple Silicon)
                        page_size = int(subprocess.check_output(
                            ["sysctl", "-n", "hw.pagesize"], text=True, timeout=5
                        ).strip())
                        out = subprocess.check_output(
                            ["vm_stat"], text=True, timeout=5
                        )
                        free_pages = 0
                        for line in out.splitlines():
                            if "Pages free:" in line or "Pages speculative:" in line:
                                free_pages += int(line.split()[-1].rstrip("."))
                        avail = free_pages * page_size
                    except Exception:
                        pass
                elif _system == "Windows":
                    try:
                        import ctypes
                        class MEMORYSTATUSEX(ctypes.Structure):
                            _fields_ = [
                                ("dwLength", ctypes.c_ulong),
                                ("dwMemoryLoad", ctypes.c_ulong),
                                ("ullTotalPhys", ctypes.c_ulonglong),
                                ("ullAvailPhys", ctypes.c_ulonglong),
                                ("ullTotalPageFile", ctypes.c_ulonglong),
                                ("ullAvailPageFile", ctypes.c_ulonglong),
                                ("ullTotalVirtual", ctypes.c_ulonglong),
                                ("ullAvailVirtual", ctypes.c_ulonglong),
                                ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                            ]
                        mem_stat = MEMORYSTATUSEX()
                        mem_stat.dwLength = ctypes.sizeof(mem_stat)
                        ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(mem_stat))
                        avail = mem_stat.ullAvailPhys
                    except Exception:
                        pass

            if avail is not None:
                # Reserve 128MB headroom for Python/paramiko/OS
                headroom = 128 * 1024 * 1024
                safe = avail - headroom
                if buf_size > safe:
                    old_mb = buf_size // (1024 * 1024)
                    new_size = max(1 * 1024 * 1024, safe)  # floor at 1MB
                    new_mb = new_size // (1024 * 1024)
                    print(f"  {C.YELLOW}Warning: --buffer {old_mb}MB exceeds available RAM "
                          f"({fmt_size(avail)} free){C.RESET}")
                    print(f"  {C.YELLOW}Reducing buffer to {new_mb}MB to avoid MemoryError{C.RESET}")
                    buf_size = new_size
                    if buf_size < 1 * 1024 * 1024:
                        print(f"  {C.RED}Error: Not enough free RAM for even a 1MB buffer "
                              f"({fmt_size(avail)} available){C.RESET}")
                        src_ssh.close()
                        dst_ssh.close()
                        sys.exit(1)

            t0 = time.time()
            # A refused destination is not created, not written into, and gets
            # no manifest: the mkdir, the sidecar and the verify pass would
            # each go through the symlink that was just refused.
            if _dst_escape:
                print(f"  {C.RED}"
                      + _tr("Nothing was written: the destination path leads "
                            "outside itself.") + f"{C.RESET}")
            else:
                dst_ssh.exec_cmd(f"mkdir -p {shlex.quote(dst)}")

                progress = Progress(unique_size, len(copy_entries))
                copy_hybrid_r2r(copy_entries, src_ssh, dst_ssh, src, dst,
                                progress, buf_size)
                progress.finish()

            # R2R extended-metadata: collect xattr/ACL/owner from src remote
            # via the existing collector, then apply to dst remote via the
            # same script L2R uses. Both endpoints need python3.
            if _preserve_spec.any_extended() and not _dst_escape:
                want_o = _preserve_spec.owner
                want_x = _preserve_spec.xattr
                want_a = _preserve_spec.acl
                if not (src_ssh.caps.get("python3") and dst_ssh.caps.get("python3")):
                    print(f"  {C.YELLOW}Skipping R2R owner/xattr/ACL transfer "
                          f"— one of the remotes lacks python3.{C.RESET}")
                else:
                    print(f"  {C.DIM}Collecting + applying remote metadata "
                          f"for {len(copy_entries)} files...{C.RESET}",
                          end="", flush=True)
                    rel_paths = [e.rel for e in copy_entries]
                    meta = _remote_collect_metadata(src_ssh, src, rel_paths,
                                                    want_x, want_a,
                                                    want_owner=want_o)
                    _apply_collected_metadata_to_remote(
                        dst_ssh, dst, meta, want_o, want_x, want_a)
                    print(f"\r  {C.GREEN}R2R metadata: collected {len(meta)} "
                          f"records, applied to destination                    "
                          f"{C.RESET}")

            # Post-copy rename for R2R file-destination
            if _dst_file_rename is not None and copy_entries:
                new_rel, old_rel = _dst_file_rename
                old_path = posixpath.join(dst, old_rel)
                new_path = posixpath.join(dst, new_rel)
                _, mv_err, mv_rc = dst_ssh.exec_cmd(
                    f"mv {shlex.quote(old_path)} {shlex.quote(new_path)}")
                if mv_rc != 0:
                    print(f"  {C.YELLOW}Warning: rename failed on destination: "
                          f"{mv_err.strip()}{C.RESET}")
                else:
                    # Update entry.rel so verify sees the new name
                    for i, e in enumerate(copy_entries):
                        if e.rel == old_rel:
                            copy_entries[i] = e._replace(rel=new_rel)
                            break

            # Create links on dest
            if link_map:
                create_links_remote(dst_ssh, link_map, dst)

            elapsed = time.time() - t0
            speed = (unique_size / elapsed
                     if (elapsed > 0 and not _dst_escape) else 0)

            _verify_status = "ok"
            if not _dst_escape:
                # Save manifest on dest
                save_remote_manifest(dst_ssh, dst, copy_entries, link_map)

                # Verify on dest (exit deferred to after summary + --log write)
                if not args.no_verify:
                    _verify_status = verify_copy_remote(dst_ssh, copy_entries,
                                                        link_map, dst)

            # Summary
            banner("DONE")
            print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{src_remote.user}@{src_remote.host}:{src}{C.RESET}")
            print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dst_remote.user}@{dst_remote.host}:{dst}{C.RESET}")
            # Before the destination policy filtered them: the refused files
            # are part of what this run was asked to move.
            _totals = _print_files_summary(
                total_files, _report_entries, _report_links,
                skipped_count=skipped_count,
                forecast=sum(e["count"] for e in _dst_found),
                byte_totals=(total_size, saved_bytes, skipped_bytes))
            if _REFUSED_PATHS:
                _n = len(_REFUSED_PATHS)
                print("  " + C.RED
                      + _tr("{n} file(s) were refused and not written:").format(n=_n)
                      + C.RESET)
                for _rel in sorted(_REFUSED_PATHS)[:10]:
                    print(f"    {C.DIM}{_rel}{C.RESET}")
                if _n > 10:
                    print("    " + C.DIM
                          + _tr("... and {m} more").format(m=_n - 10) + C.RESET)
            if skipped_count:
                print(f"  Skipped: {C.BOLD}{skipped_count}{C.RESET} unchanged files "
                      f"({C.GREEN}{fmt_size(skipped_bytes)}{C.RESET})")
            print(f"  Data:    {C.BOLD}{fmt_size(_totals.bytes_written)}{C.RESET} relayed"
                  + (f" ({fmt_size(saved_bytes)} saved by dedup)" if saved_bytes > 0 else ""))
            print(f"  {_pad(_tr('Time:'), 11)}{C.BOLD}{fmt_time(elapsed)}{C.RESET}")
            print(f"  {_pad(_tr('Speed:'), 11)}{C.GREEN}{C.BOLD}{fmt_speed(speed)}{C.RESET}")
            _print_preserve_summary()
            _record = {
                "source": f"{src_remote.user}@{src_remote.host}:{src}",
                "destination": f"{dst_remote.user}@{dst_remote.host}:{dst}",
                "mode": "remote_to_remote",
                "total_files": total_files, "copied": _totals.copied,
                "linked": _totals.linked, "refused": _totals.refused,
                "refused_paths": sorted(_REFUSED_PATHS)[:100],
                "skipped": skipped_count,
                "errors": sum(1 for e in _log_entries if e["action"] == "error"),
                "total_bytes": total_size,
                "bytes_written": _totals.bytes_written,
                "bytes_refused": _totals.bytes_refused,
                "dedup_saved": _totals.bytes_deduped,
                "elapsed_sec": round(elapsed, 2),
                "avg_speed_bps": round(speed), "hash_algo": _hash_name,
            }
            write_sudo_audit(_record["source"], _record["destination"], _record)
            if args.log_file:
                write_log_file(args.log_file, _record)
            print()
            _exit_for_verify(_verify_status)   # exit AFTER summary/log were written

        except KeyboardInterrupt:
            print(f"\n  {C.YELLOW}Interrupted.{C.RESET}")
            sys.exit(130)
        except (OSError, IOError) as e:
            print(f"\n{C.RED}Error: {_fmt_exc(e)}{C.RESET}")
            sys.exit(1)
        except Exception as e:
            ename = type(e).__name__
            if "Authentication" in ename:
                print(f"\n{C.RED}Error: SSH authentication failed{C.RESET}")
            elif "SSH" in ename or "Socket" in ename or "paramiko" in type(e).__module__:
                print(f"\n{C.RED}Error: SSH connection failed: {_fmt_exc(e)}{C.RESET}")
            elif "ConnectionReset" in ename or "BrokenPipe" in ename:
                print(f"\n{C.RED}Error: Connection lost: {_fmt_exc(e)}{C.RESET}")
            else:
                raise
            sys.exit(1)
        finally:
            if src_ssh:
                src_ssh.close()
            if dst_ssh:
                dst_ssh.close()

        sys.exit(0)

    # ══════════════════════════════════════════════════════════════════
    # REMOTE → LOCAL FLOW
    # ══════════════════════════════════════════════════════════════════
    if src_remote and not dst_remote:
        try:
            # ── Phase 2b: Incremental check against local dest ───────
            skipped_count = 0
            skipped_bytes = 0

            if not args.overwrite and os.path.isdir(dst):
                banner("Phase 2b — Incremental check")
                copy_entries, link_map, skipped_count, skipped_bytes = \
                    filter_unchanged_remote_to_local(
                        copy_entries, link_map, src_ssh, src, dst, args.threads
                    )
                unique_size = sum(e.size for e in copy_entries)

                if not copy_entries and not link_map:
                    banner("DONE — Nothing to copy")
                    print(f"  All {skipped_count} files are already up to date.")
                    if args.log_file:
                        write_log_file(args.log_file, {
                            "source": f"{src_remote.user}@{src_remote.host}:{src}",
                            "destination": dst, "mode": "remote_to_local",
                            "total_files": total_files, "copied": 0, "linked": 0,
                            "skipped": skipped_count, "errors": 0,
                            "total_bytes": total_size, "bytes_written": 0,
                            "dedup_saved": saved_bytes, "elapsed_sec": 0,
                            "avg_speed_bps": 0, "hash_algo": _hash_name,
                        })
                    print()
                    src_ssh.close()
                    sys.exit(0)

            # ── Phase 3: Space check (local) ─────────────────────────
            banner("Phase 3 — Space check")
            required = unique_size
            # If the destination filesystem can't dedup via links (FAT32,
            # exFAT, etc.), each duplicate will be materialized as a full
            # copy. We need space for the FULL undeduplicated size.
            if fs_strategy == "none" and saved_bytes > 0:
                full_size = unique_size + saved_bytes
                print(f"  Data to write: {C.BOLD}{fmt_size(full_size)}{C.RESET}")
                print(f"  {C.YELLOW}⚠ Filesystem does not support links — "
                      f"dedup saves {fmt_size(saved_bytes)} on the wire only."
                      f"{C.RESET}")
                print(f"  {C.YELLOW}  Each duplicate becomes a full copy on "
                      f"disk; total disk usage will be "
                      f"{fmt_size(full_size)}.{C.RESET}")
                required = full_size
            else:
                print(f"  Data to write: {C.BOLD}{fmt_size(required)}{C.RESET}"
                      + (f" (after dedup saved {fmt_size(saved_bytes)})"
                         if saved_bytes > 0 else ""))

            if not check_destination_space(dst, required, args.force,
                                           create=not args.dry_run):
                src_ssh.close()
                sys.exit(1)

            if args.dry_run:
                small, large = split_by_size(copy_entries)
                small_sz = sum(e.size for e in small)
                large_sz = sum(e.size for e in large)
                print(f"\n  {C.YELLOW}DRY RUN — Copy strategy:{C.RESET}\n")
                print(f"    Small files (<1MB): {C.BOLD}{len(small)}{C.RESET} files, "
                      f"{C.BOLD}{fmt_size(small_sz)}{C.RESET} → tar stream from remote")
                print(f"    Large files (≥1MB): {C.BOLD}{len(large)}{C.RESET} files, "
                      f"{C.BOLD}{fmt_size(large_sz)}{C.RESET} → SFTP download")
                if link_map:
                    print(f"\n  Plus {len(link_map)} duplicate files to be linked")
                print(f"\n  Unique data: {fmt_size(unique_size)}")
                # The names are the remote's, so the plan asks the untrusted
                # question — the same one the extractor will ask.
                _plan_record(
                    args, f"{src_remote.user}@{src_remote.host}:{src}", dst,
                    "remote_to_local", total_files, copy_entries, link_map,
                    skipped_count, total_size, saved_bytes, skipped_bytes,
                    refused=_planned_local_refusals(dst, copy_entries,
                                                    link_map, False))
                src_ssh.close()
                sys.exit(0)

            # ── Phase 5: Download from remote ────────────────────────
            banner("Phase 5 — Remote-to-local copy")
            os.makedirs(dst, exist_ok=True)

            progress = Progress(unique_size, len(copy_entries))
            t0 = time.time()
            copy_hybrid_remote_to_local(copy_entries, src_ssh, src, dst, progress, buf_size,
                                        case_renames=case_renames)
            progress.finish()

            # R2L extended-metadata preservation (xattr/ACL). Owner already
            # rode through tar headers via filter='tar' in _safe_tar_extract.
            # We collect xattrs/ACLs from the remote side via a single batched
            # python3 script and apply them locally.
            if _preserve_spec.xattr or _preserve_spec.acl:
                want_x = _preserve_spec.xattr and _preserve_dst_caps["xattr"] is not False
                want_a = _preserve_spec.acl and _preserve_dst_caps["acl"] is not False
                if want_x or want_a:
                    if not src_ssh.caps.get("python3"):
                        print(f"  {C.YELLOW}Skipping remote xattr/ACL "
                              f"collection — remote lacks python3.{C.RESET}")
                    else:
                        print(f"  {C.DIM}Collecting remote metadata for "
                              f"{len(copy_entries)} files...{C.RESET}",
                              end="", flush=True)
                        rel_paths = [e.rel for e in copy_entries]
                        meta = _remote_collect_metadata(src_ssh, src, rel_paths,
                                                        want_x, want_a)
                        _apply_remote_metadata_local(meta, dst, want_x, want_a)
                        # 'meta' may be {} when no files had any xattr/ACL —
                        # that's "nothing to preserve", not a failure.
                        if meta:
                            print(f"\r  {C.GREEN}Collected remote metadata "
                                  f"for {len(meta)} files                    "
                                  f"{C.RESET}")
                        else:
                            print(f"\r  {C.DIM}No remote xattrs/ACLs found "
                                  f"to preserve                    {C.RESET}")

            # Create links locally (reflink-aware when supported)
            if link_map:
                # Remote-to-local: the link_map keys are names the far side
                # chose, so the strict resolution check stays on.
                create_links(link_map, dst, fs_strategy=fs_strategy)

            # Restore directory metadata (mode/times/owner). The remote tar
            # carries FILE modes but recreates directories at the default umask,
            # and writing files into them clobbers their mtimes — so, like the
            # local flow's _apply_dir_metadata pass, collect the source dirs'
            # metadata from the remote and apply it after every file has landed.
            if (_preserve_spec.mode or _preserve_spec.times
                    or _preserve_spec.owner):
                rel_dirs = set()
                for _src in (list(copy_entries) if copy_entries else []):
                    _d = posixpath.dirname(_src.rel or "")
                    while _d and _d not in rel_dirs:
                        rel_dirs.add(_d)
                        _d = posixpath.dirname(_d)
                for _dup in (link_map or {}):
                    _d = posixpath.dirname(_dup or "")
                    while _d and _d not in rel_dirs:
                        rel_dirs.add(_d)
                        _d = posixpath.dirname(_d)
                if rel_dirs and src_ssh.caps.get("python3"):
                    _dirmeta = _remote_collect_dir_metadata(src_ssh, src, rel_dirs)
                    _apply_remote_dir_metadata_local(_dirmeta, dst)

            elapsed = time.time() - t0
            speed = unique_size / elapsed if elapsed > 0 else 0

            # Verify (defer the exit until after summary + --log write)
            _verify_status = "ok"
            if not args.no_verify:
                _verify_status = verify_copy(copy_entries, link_map, dst,
                                     threads=args.threads)

            # Summary
            banner("DONE")
            print(f"  {_pad(_tr('Source:'), 11)}{C.BOLD}{src_remote.user}@{src_remote.host}:{src}{C.RESET}")
            print(f"  {_pad(_tr('Dest:'), 11)}{C.BOLD}{dst}{C.RESET}")
            # A pull writes to a LOCAL destination through the same engines
            # and the same policy, so it refuses files the same way. It read
            # none of that: a pull that refused every file printed
            # "N copied" and a clean summary.
            _totals = _print_files_summary(
                total_files, copy_entries, link_map,
                skipped_count=skipped_count,
                byte_totals=(total_size, saved_bytes, skipped_bytes))
            if _REFUSED_PATHS:
                _n = len(_REFUSED_PATHS)
                print("  " + C.RED
                      + _tr("{n} file(s) were refused and not written:").format(n=_n)
                      + C.RESET)
                for _rel in sorted(_REFUSED_PATHS)[:10]:
                    print(f"    {C.DIM}{_rel}{C.RESET}")
                if _n > 10:
                    print("    " + C.DIM
                          + _tr("... and {m} more").format(m=_n - 10) + C.RESET)
            if skipped_count:
                print(f"  Skipped: {C.BOLD}{skipped_count}{C.RESET} unchanged files "
                      f"({C.GREEN}{fmt_size(skipped_bytes)}{C.RESET})")
            print(f"  Data:    {C.BOLD}{fmt_size(_totals.bytes_written)}{C.RESET} downloaded"
                  + (f" ({fmt_size(saved_bytes)} saved by dedup)" if saved_bytes > 0 else ""))
            print(f"  {_pad(_tr('Time:'), 11)}{C.BOLD}{fmt_time(elapsed)}{C.RESET}")
            print(f"  {_pad(_tr('Speed:'), 11)}{C.GREEN}{C.BOLD}{fmt_speed(speed)}{C.RESET}")
            _print_preserve_summary()
            _record = {
                "source": f"{src_remote.user}@{src_remote.host}:{src}",
                "destination": dst, "mode": "remote_to_local",
                "total_files": total_files, "copied": _totals.copied,
                "linked": _totals.linked, "refused": _totals.refused,
                "refused_paths": sorted(_REFUSED_PATHS)[:100],
                "skipped": skipped_count,
                "errors": sum(1 for e in _log_entries if e["action"] == "error"),
                "total_bytes": total_size,
                "bytes_written": _totals.bytes_written,
                "bytes_refused": _totals.bytes_refused,
                "dedup_saved": _totals.bytes_deduped,
                "elapsed_sec": round(elapsed, 2),
                "avg_speed_bps": round(speed), "hash_algo": _hash_name,
            }
            # An elevated PULL is root writing files whose names an untrusted
            # remote chose — the run with the strongest claim on an audit
            # trail, and the one that left none: write_sudo_audit had a single
            # call site, in the local flow. It gates on elevation itself, so
            # the call is unconditional here. BEFORE write_log_file, which
            # clears the per-file entries the record carries.
            write_sudo_audit(_record["source"], dst, _record)
            if args.log_file:
                write_log_file(args.log_file, _record)
            print()
            _exit_for_verify(_verify_status)   # exit AFTER summary/log were written

        except KeyboardInterrupt:
            print(f"\n  {C.YELLOW}Interrupted.{C.RESET}")
            sys.exit(130)
        except (OSError, IOError) as e:
            print(f"\n{C.RED}Error: {_fmt_exc(e)}{C.RESET}")
            sys.exit(1)
        except Exception as e:
            ename = type(e).__name__
            if "Authentication" in ename:
                print(f"\n{C.RED}Error: SSH authentication failed{C.RESET}")
            elif "SSH" in ename or "Socket" in ename or "paramiko" in type(e).__module__:
                print(f"\n{C.RED}Error: SSH connection failed: {_fmt_exc(e)}{C.RESET}")
            elif "ConnectionReset" in ename or "BrokenPipe" in ename:
                print(f"\n{C.RED}Error: Connection lost: {_fmt_exc(e)}{C.RESET}")
            else:
                raise
            sys.exit(1)
        finally:
            if src_ssh:
                src_ssh.close()

        sys.exit(0)

    # ══════════════════════════════════════════════════════════════════
    # LOCAL → REMOTE SSH FLOW
    # ══════════════════════════════════════════════════════════════════
    if remote:
        ssh = None
        try:
            # ── Connect ──────────────────────────────────────────────
            banner("SSH — Connecting")
            password = None
            if args.ssh_password_env:
                password = os.environ.get(args.ssh_password_env)
            elif args.ssh_password:
                password = getpass.getpass(f"Password for {remote.user}@{remote.host}: ")
            elif getattr(args, "_resolved_dst_password", None):
                password = args._resolved_dst_password
            ssh = SSHConnection(remote, port=remote.port, key_path=args.ssh_key,
                                password=password, compress=args.compress,
                                sftp_only=getattr(args, "sftp_only", False),
                                ).connect()
            print(f"  {C.GREEN}Connected to {remote.user}@{remote.host}:{remote.port}{C.RESET}")
            if ssh.sftp_only:
                print(f"  {C.DIM}SFTP-only mode — no commands are run on the server{C.RESET}")
            else:
                caps = [k for k, v in ssh.caps.items() if v]
                print(f"  {C.DIM}Remote tools: {', '.join(caps) or 'none detected'}{C.RESET}")

            # Before ensure_remote_root, and that ordering is the point: it
            # runs `mkdir -p` and a write probe, so asking afterwards would
            # already have created — and briefly written — through the very
            # symlink being asked about.
            _dst_escape = _remote_dest_path_escape(
                _sftp_abs_probe(ssh), dst, _sftp_remote_cwd(ssh))

            # Fail here, one second after connecting, rather than after
            # streaming into a destination that cannot exist.
            if not args.dry_run and not _dst_escape:
                _dst_problem = ensure_remote_root(ssh, dst)
                if _dst_problem:
                    print(f"\n  {C.RED}Error: cannot use destination "
                          f"{dst}: {_dst_problem}{C.RESET}")
                    ssh.close()
                    sys.exit(1)

            # ── Phase 2b: Remote incremental check ───────────────────
            skipped_count = 0
            skipped_bytes = 0

            if not args.overwrite:
                banner("Phase 2b — Remote incremental check")
                copy_entries, link_map, skipped_count, skipped_bytes = \
                    filter_unchanged_remote(copy_entries, link_map, ssh, dst)
                unique_size = sum(e.size for e in copy_entries)

                if not copy_entries and not link_map:
                    banner("DONE — Nothing to copy")
                    print(f"  All {skipped_count} files are already up to date on remote.")
                    if args.log_file:
                        write_log_file(args.log_file, {
                            "source": src_display,
                            "destination": f"{remote.user}@{remote.host}:{dst}",
                            "mode": "local_to_remote", "total_files": total_files,
                            "copied": 0, "linked": 0, "skipped": skipped_count,
                            "errors": 0, "total_bytes": total_size, "bytes_written": 0,
                            "dedup_saved": saved_bytes, "elapsed_sec": 0,
                            "avg_speed_bps": 0, "hash_algo": _hash_name,
                        })
                    print()
                    ssh.close()
                    sys.exit(0)

            # ── Phase 3: Remote space check ──────────────────────────
            banner("Phase 3 — Space check (remote)")
            # The destination-path policy, asked of the REMOTE destination —
            # before the space check, so the space required is the space the
            # run will actually use. The lists the engines get lose the
            # refused rels; _report_entries keeps them, because the summary
            # has to account for every file the run was asked to move.
            _report_entries, _report_links = copy_entries, link_map
            if _dst_escape:
                # The destination itself is the redirect, so every file in the
                # run is refused — there is no subset of this that is safe.
                _dst_refused = set([e.rel for e in copy_entries]
                                   + list(link_map or {}))
                _dst_found = [{"rel": "", "target": _dst_escape[1],
                               "count": len(_dst_refused)}]
            else:
                _is_link, _realpath = _sftp_dest_probe(ssh, dst)
                _dst_refused, _dst_found = _remote_dest_refusals(
                    dst, [e.rel for e in copy_entries] + list(link_map or {}),
                    _is_link, _realpath)
            copy_entries, link_map = _refuse_remote_dest(
                dst, copy_entries, link_map, _dst_refused, _dst_found)
            unique_size = sum(e.size for e in copy_entries)
            required = unique_size
            print(f"  Data to write: {C.BOLD}{fmt_size(required)}{C.RESET}"
                  + (f" (after dedup saved {fmt_size(saved_bytes)})" if saved_bytes > 0 else ""))

            if not check_remote_space(ssh, dst, required, args.force, entries=copy_entries):
                ssh.close()
                sys.exit(1)

            # ── Phase 4: Resolve physical layout (local source) ──────
            banner("Phase 4 — Mapping physical disk layout")
            copy_entries = resolve_physical_offsets(copy_entries, args.threads)

            if args.dry_run:
                small, large = split_by_size(copy_entries)
                small_sz = sum(e.size for e in small)
                large_sz = sum(e.size for e in large)
                print(f"\n  {C.YELLOW}DRY RUN — Copy strategy:{C.RESET}\n")
                if ssh.sftp_only:
                    print(f"    All files: {C.BOLD}{len(small) + len(large)}{C.RESET} files, "
                          f"{C.BOLD}{fmt_size(small_sz + large_sz)}{C.RESET} → SFTP pipelined (SFTP-only mode)")
                else:
                    print(f"    Small files (<1MB): {C.BOLD}{len(small)}{C.RESET} files, "
                          f"{C.BOLD}{fmt_size(small_sz)}{C.RESET} → tar stream over SSH")
                    print(f"    Large files (≥1MB): {C.BOLD}{len(large)}{C.RESET} files, "
                          f"{C.BOLD}{fmt_size(large_sz)}{C.RESET} → SFTP pipelined")
                if link_map:
                    print(f"\n  Plus {len(link_map)} duplicate files to be linked on remote")
                print(f"\n  Unique data: {fmt_size(unique_size)}")
                _plan_record(
                    args, src_display,
                    f"{remote.user}@{remote.host}:{dst}", "local_to_remote",
                    total_files, _report_entries, _report_links, skipped_count,
                    total_size, saved_bytes, skipped_bytes,
                    refused=_dst_refused)
                ssh.close()
                sys.exit(0)

            # ── Phase 5: Remote copy ─────────────────────────────────
            banner("Phase 5 — Remote copy")
            t0 = time.time()
            # A refused destination is not copied into and is not CREATED
            # either: the mkdir, the manifest sidecar and the verify pass all
            # write, and every one of them would write through the symlink
            # that was just refused. Refusing the files and then leaving a
            # manifest next to them is not a refusal.
            if _dst_escape:
                print(f"  {C.RED}"
                      + _tr("Nothing was written: the destination path leads "
                            "outside itself.") + f"{C.RESET}")
                elapsed = time.time() - t0
                speed = 0
            else:
                if ssh.sftp_only:
                    _sftp_mkdir_p(ssh.open_sftp(), dst)
                else:
                    ssh.exec_cmd(f"mkdir -p {shlex.quote(dst)}")

                progress = Progress(unique_size, len(copy_entries))
                copy_hybrid_remote(copy_entries, ssh, dst, progress, buf_size)
                progress.finish()

            # L2R extended-metadata preservation (owner/xattr/ACL). Mode and
            # mtime ride through tar headers already; owner/xattr/ACL need
            # a separate push step because the tar producer strips them or
            # the tar format doesn't carry them. We collect locally and
            # ship a serialized payload to a python3 helper on the remote.
            _verify_status = "ok"
            if not _dst_escape:
                if (_preserve_spec.owner or _preserve_spec.xattr
                        or _preserve_spec.acl):
                    want_o = _preserve_spec.owner
                    want_x = _preserve_spec.xattr
                    want_a = _preserve_spec.acl
                    if not ssh.caps.get("python3"):
                        print(f"  {C.YELLOW}Skipping remote owner/xattr/ACL "
                              f"apply — remote lacks python3.{C.RESET}")
                    else:
                        print(f"  {C.DIM}Applying remote metadata for "
                              f"{len(copy_entries)} files...{C.RESET}",
                              end="", flush=True)
                        _push_metadata_to_remote(ssh, dst, copy_entries, src,
                                                 want_o, want_x, want_a)
                        print(f"\r  {C.GREEN}Applied remote metadata for "
                              f"{len(copy_entries)} files                    "
                              f"{C.RESET}")

                # Create links on remote
                if link_map:
                    create_links_remote(ssh, link_map, dst)

                elapsed = time.time() - t0
                speed = unique_size / elapsed if elapsed > 0 else 0

                # ── Save manifest on remote ──────────────────────────
                save_remote_manifest(ssh, dst, copy_entries, link_map)

                # ── Verify on remote (exit deferred to after summary/log) ─
                if not args.no_verify:
                    _verify_status = verify_copy_remote(ssh, copy_entries,
                                                        link_map, dst)

            # ── Summary ──────────────────────────────────────────────
            banner("DONE")
            print(f"  Remote:  {C.BOLD}{remote.user}@{remote.host}:{dst}{C.RESET}")
            # The lists BEFORE the destination policy dropped what it refused:
            # a refused file is one the run was asked to move, so the buckets
            # cannot close without it.
            _totals = _print_files_summary(
                total_files, _report_entries, _report_links,
                skipped_count=skipped_count,
                forecast=sum(e["count"] for e in _dst_found),
                byte_totals=(total_size, saved_bytes, skipped_bytes))
            if _REFUSED_PATHS:
                _n = len(_REFUSED_PATHS)
                print("  " + C.RED
                      + _tr("{n} file(s) were refused and not written:").format(n=_n)
                      + C.RESET)
                for _rel in sorted(_REFUSED_PATHS)[:10]:
                    print(f"    {C.DIM}{_rel}{C.RESET}")
                if _n > 10:
                    print("    " + C.DIM
                          + _tr("... and {m} more").format(m=_n - 10) + C.RESET)
            if skipped_count:
                print(f"  Skipped: {C.BOLD}{skipped_count}{C.RESET} unchanged files "
                      f"({C.GREEN}{fmt_size(skipped_bytes)}{C.RESET})")
            # A refusal is not a failure: nothing broke, a policy said no,
            # and it is already reported on its own line above. _COPY_ERRORS
            # holds both (verification reads it to explain a missing file), so
            # the refused ones come out here or every refusal is counted twice
            # under two different words.
            _failed_files = len([r for r in _COPY_ERRORS
                                 if r not in set(_REFUSED_PATHS)])
            if _failed_files:
                print(f"  {C.RED}Failed:  {C.BOLD}{_failed_files}{C.RESET}"
                      f"{C.RED} file{'' if _failed_files == 1 else 's'} did not "
                      f"reach the destination{C.RESET}")
            print(f"  Data:    {C.BOLD}{fmt_size(unique_size)}{C.RESET} sent"
                  + (f" ({fmt_size(saved_bytes)} saved by dedup)" if saved_bytes > 0 else ""))
            print(f"  {_pad(_tr('Time:'), 11)}{C.BOLD}{fmt_time(elapsed)}{C.RESET}")
            print(f"  {_pad(_tr('Speed:'), 11)}{C.GREEN}{C.BOLD}{fmt_speed(speed)}{C.RESET}")
            _print_preserve_summary()
            _record = {
                "source": src_display,
                "destination": f"{remote.user}@{remote.host}:{dst}",
                "mode": "local_to_remote",
                "total_files": total_files, "copied": _totals.copied,
                "linked": _totals.linked, "refused": _totals.refused,
                "refused_paths": sorted(_REFUSED_PATHS)[:100],
                "skipped": skipped_count,
                "errors": sum(1 for e in _log_entries if e["action"] == "error"),
                "total_bytes": total_size,
                "bytes_written": _totals.bytes_written,
                "bytes_refused": _totals.bytes_refused,
                "dedup_saved": _totals.bytes_deduped,
                "elapsed_sec": round(elapsed, 2),
                "avg_speed_bps": round(speed), "hash_algo": _hash_name,
            }
            # Elevation governs the LOCAL endpoint, which here is the SOURCE:
            # an elevated push is root reading files the invoking user cannot
            # and sending them off the machine. Same trail, same reason.
            write_sudo_audit(src_display, _record["destination"], _record)
            if args.log_file:
                write_log_file(args.log_file, _record)
            print()
            _exit_for_verify(_verify_status)   # exit AFTER summary/log were written

        except KeyboardInterrupt:
            print(f"\n  {C.YELLOW}Interrupted.{C.RESET}")
            sys.exit(130)
        except (OSError, IOError) as e:
            print(f"\n{C.RED}Error: {_fmt_exc(e)}{C.RESET}")
            sys.exit(1)
        except Exception as e:
            ename = type(e).__name__
            if "Authentication" in ename:
                print(f"\n{C.RED}Error: SSH authentication failed for "
                      f"{remote.user}@{remote.host}{C.RESET}")
            elif "SSH" in ename or "Socket" in ename or "paramiko" in type(e).__module__:
                print(f"\n{C.RED}Error: SSH connection failed: {_fmt_exc(e)}{C.RESET}")
            elif "ConnectionReset" in ename or "BrokenPipe" in ename:
                print(f"\n{C.RED}Error: Connection lost: {_fmt_exc(e)}{C.RESET}")
            else:
                raise
            sys.exit(1)
        finally:
            if ssh:
                ssh.close()

        sys.exit(0)

    # ══════════════════════════════════════════════════════════════════
    # LOCAL FLOW
    # ══════════════════════════════════════════════════════════════════
    try:
        _run_local_flow(args, dst, copy_entries, link_map, total_size, dedup_db,
                        total_files, unique_size, saved_bytes, buf_size,
                        fs_strategy)
    finally:
        if dedup_db:
            dedup_db.close()


def _run_local_flow(args, dst, copy_entries, link_map, total_bytes, dedup_db,
                    total_files, unique_size, saved_bytes, buf_size,
                    fs_strategy=None):
    # ── Phase 2b: Skip unchanged files ────────────────────────────────
    skipped_count = 0
    skipped_bytes = 0

    if not args.overwrite and os.path.isdir(dst):
        banner("Phase 2b — Incremental check")
        copy_entries, link_map, skipped_count, skipped_bytes = filter_unchanged(
            copy_entries, link_map, dst, args.threads
        )
        unique_size = sum(e.size for e in copy_entries)

        if not copy_entries and not link_map:
            banner("DONE — Nothing to copy")
            print(f"  All {skipped_count} files are already up to date.")
            if args.log_file:
                write_log_file(args.log_file, {
                    "source": args.source, "destination": dst,
                    "mode": "local_to_local", "total_files": total_files,
                    "copied": 0, "linked": 0, "skipped": skipped_count,
                    "errors": 0, "total_bytes": total_bytes,
                    "bytes_written": 0, "dedup_saved": saved_bytes,
                    "elapsed_sec": 0, "avg_speed_bps": 0, "hash_algo": _hash_name,
                })
            print()
            return

    # ── Phase 3: Space check ──────────────────────────────────────────
    banner("Phase 3 — Space check")
    # Files occupy whole blocks on the destination — the check must compare
    # ALLOCATED bytes against free space, not logical sizes, or many-small-
    # files jobs pass preflight and die mid-copy with a full disk.
    # Same reason the hash cache is skipped above: a preview creates nothing.
    # The check itself keeps its teeth — the destination's filesystem is the
    # one its nearest existing parent is on, so the numbers are the real ones.
    # Before the dry-run check, not after it: a dry run is exactly when someone
    # is verifying that the destination is set up the way they think, and it is
    # the cheapest moment to learn that a directory there is a symlink leading
    # out. It is a REPORT — the per-file check in _dest_policy is the
    # security boundary and runs regardless of what this printed.
    # Kept, not discarded: the number it reports is a prediction, and the DONE
    # summary compares it against what the run actually refused. Two numbers
    # from the same policy that disagree mean one of them is a lie, and until
    # now nothing looked.
    _refusal_forecast = sum(e["count"] for e in warn_symlinked_dest_dirs(
        dst, [e.rel for e in copy_entries] + list(link_map.keys())))

    if not args.dry_run:
        _makedirs_or_die(dst)
    block = _dest_block_size(_existing_ancestor(dst))
    ndirs = len({os.path.dirname(e.rel) for e in copy_entries
                 if os.path.dirname(e.rel)})
    # If the destination filesystem can't dedup via links (FAT32, exFAT,
    # etc.), each duplicate will be materialized as a full copy. We need
    # space for the FULL undeduplicated size.
    if fs_strategy == "none" and saved_bytes > 0:
        full_size = unique_size + saved_bytes
        fs_alloc = sum(_block_rounded(e.size, block) for e in copy_entries)
        # Duplicates: logical bytes + one block of round-up each (upper bound).
        fs_alloc += saved_bytes + len(link_map) * block
        print(f"  Data to write: {C.BOLD}{fmt_size(full_size)}{C.RESET}")
        print(f"  {C.YELLOW}⚠ Filesystem does not support links — "
              f"dedup saves {fmt_size(saved_bytes)} on the wire only."
              f"{C.RESET}")
        print(f"  {C.YELLOW}  Each duplicate becomes a full copy on disk; "
              f"total disk usage will be {fmt_size(full_size)}.{C.RESET}")
        logical = full_size
    else:
        # Sparse files (e.g. VM disk images): if the destination FS supports
        # holes (anything except FAT32/exFAT), only the allocated extents
        # take disk space — adjust the requirement so a 1.5 TB sparse image
        # holding 12 GB of real data doesn't reject a 500 GB destination.
        if _HAS_SEEK_HOLE and fs_strategy != "none":
            alloc_total = sum(_effective_alloc(e) for e in copy_entries)
            sparse_saved = unique_size - alloc_total
        else:
            alloc_total = unique_size
            sparse_saved = 0
        fs_alloc = sum(_block_rounded(_effective_alloc(e)
                                      if (_HAS_SEEK_HOLE and fs_strategy != "none")
                                      else e.size, block)
                       for e in copy_entries)
        logical = alloc_total
        msg = f"  Data to write: {C.BOLD}{fmt_size(logical)}{C.RESET}"
        notes = []
        if saved_bytes > 0:
            notes.append(f"dedup saved {fmt_size(saved_bytes)}")
        if sparse_saved > 0:
            notes.append(f"sparse holes skipped {fmt_size(sparse_saved)}")
        if notes:
            msg += " (after " + ", ".join(notes) + ")"
        print(msg)

    required = fs_alloc + _space_overhead_margin(fs_alloc, ndirs, block)
    if required > logical:
        print(f"  {C.DIM}On-disk requirement: {fmt_size(required)} "
              f"(+{fmt_size(required - logical)} block/metadata overhead, "
              f"{fmt_size(block)} blocks){C.RESET}")

    if not check_destination_space(dst, required, args.force,
                                   create=not args.dry_run):
        sys.exit(1)

    # ── Phase 4: Resolve physical layout ──────────────────────────────
    banner("Phase 4 — Mapping physical disk layout")
    copy_entries = resolve_physical_offsets(copy_entries, args.threads)

    if args.dry_run:
        small, large = split_by_size(copy_entries)
        small_sz = sum(e.size for e in small)
        large_sz = sum(e.size for e in large)
        print(f"\n  {C.YELLOW}DRY RUN — Copy strategy:{C.RESET}\n")
        print(f"    Small files (<1MB): {C.BOLD}{len(small)}{C.RESET} files, "
              f"{C.BOLD}{fmt_size(small_sz)}{C.RESET} → single block stream (tar)")
        print(f"    Large files (≥1MB): {C.BOLD}{len(large)}{C.RESET} files, "
              f"{C.BOLD}{fmt_size(large_sz)}{C.RESET} → individual copy")
        print(f"\n  {C.YELLOW}First 20 files in disk order:{C.RESET}\n")
        for i, e in enumerate(copy_entries[:20]):
            tag = "BLK" if e.size < SMALL_FILE_THRESHOLD else "IND"
            print(f"  {i+1:4d}. [{tag}] offset={e.physical_offset:>14d}  "
                  f"size={fmt_size(e.size):>10s}  {e.rel}")
        if len(copy_entries) > 20:
            print(f"  ... and {len(copy_entries) - 20} more files")
        if link_map:
            print(f"\n  Plus {len(link_map)} duplicate files to be linked")
        # Show the on-disk bytes that will actually be written, accounting
        # for sparse holes the sparse-aware copy will skip. Matches the
        # "Data to write" figure printed in Phase 3.
        if _HAS_SEEK_HOLE and fs_strategy != "none":
            alloc_total = sum(_effective_alloc(e) for e in copy_entries)
        else:
            alloc_total = unique_size
        print(f"\n  Data to write: {fmt_size(alloc_total)}"
              + (f"  {C.DIM}(logical {fmt_size(unique_size)}, "
                 f"sparse holes skipped {fmt_size(unique_size - alloc_total)})"
                 f"{C.RESET}" if alloc_total < unique_size else ""))
        _plan_record(args, args.source, dst, "local_to_local", total_files,
                     copy_entries, link_map, skipped_count, total_bytes,
                     saved_bytes, skipped_bytes,
                     refused=_planned_local_refusals(dst, copy_entries,
                                                     link_map, True))
        return

    # ── Phase 5: Block copy ─────────────────────────────────────────
    banner("Phase 5 — Block copy")
    # Arm the digest collector BEFORE any bytes move: the copy paths hash each
    # source file as it streams past, which is what makes Phase 6's content
    # check cost one destination read instead of re-reading both sides.
    if not args.no_verify:
        _SRC_DIGESTS.arm()
    else:
        _SRC_DIGESTS.disarm()
    os.makedirs(dst, exist_ok=True)

    progress = Progress(unique_size, len(copy_entries))
    t0 = time.time()
    # Skip the copy engine and its bar when there is nothing to copy — every
    # file deduped to a link, or nothing changed. Driving a progress bar to
    # "100%  0.0 B  avg 0.0 B/s  0 files" reads like something went wrong on
    # a run that did exactly what it should.
    if copy_entries:
        copy_hybrid(copy_entries, dst, progress, buf_size, fs_strategy=fs_strategy,
                    threads=args.threads, small_mode=args.small_files)
        progress.finish()
    else:
        _QUIET_STATS.update(files=0, bytes=0, elapsed=0.0)

    # Create links for duplicates
    if link_map:
        create_links(link_map, dst, fs_strategy=fs_strategy,
                     trusted_source=True)          # names from our own scan

    # Directory metadata (mode/times/owner/xattr/ACL) — must run after all
    # file writes, which clobber dir mtimes and land dirs at default modes.
    # Pass link_map so directories whose files were all deduplicated still get
    # their metadata mirrored (single-source layouts).
    _apply_dir_metadata(copy_entries, dst, link_map=link_map)

    # Stop the clock only once the data is durable — see _flush_destination.
    _flush_destination(dst)
    elapsed = time.time() - t0
    # Rate the bytes that were actually written. unique_size is the LOGICAL
    # total, so on a sparse tree it counts holes that never reached the disk:
    # a 1.2 GB logical / 193 MB real copy reported ~6x its true throughput.
    if _HAS_SEEK_HOLE and fs_strategy != "none":
        _written = sum(_effective_alloc(e) for e in copy_entries)
    else:
        _written = unique_size
    speed = _written / elapsed if elapsed > 0 else 0
    # Progress.finish() stopped its own clock before the flush, and --quiet
    # reports from there. Without this the same copy prints 0.6s quiet and
    # 2.4s verbose — the display flag must not change the measurement.
    _QUIET_STATS.update(bytes=_written, elapsed=elapsed)

    # ── Update dedup database with copied files ──────────────────────
    if dedup_db:
        dst_rows = []
        for e in copy_entries:
            if not e.content_hash:
                continue
            # Store the WRITTEN file's mtime so a later cross-run match can trust
            # the hash without re-reading it. Without this every repeated backup
            # re-hashes the whole matched dest tree — the exact cost the DB cache
            # exists to eliminate.
            try:
                mt = os.lstat(os.path.join(dst, e.rel)).st_mtime_ns
            except OSError:
                mt = None
            dst_rows.append((e.rel, e.size, e.content_hash, mt))
        if dst_rows:
            dedup_db.store_dest_batch(dst_rows)

    # ── Refusals ──────────────────────────────────────────────────────
    # The consumer for _REFUSED_PATHS. Every engine appends to it; before this
    # nothing read it, so a run where the destination policy refused every
    # file printed a success summary and exited 0. Verification cannot cover
    # this: it does not run under --no-verify, and a refused file is not a
    # corrupt one. Same shape as the pull path, which reports `rejected`
    # separately from `verified` for the same reason.
    if _REFUSED_PATHS:
        n = len(_REFUSED_PATHS)
        print("\n  " + C.RED
              + _tr("{n} file(s) were refused and not written:").format(n=n)
              + C.RESET)
        for rel in _REFUSED_PATHS[:10]:
            print(f"    {C.DIM}{rel}{C.RESET}")
        if n > 10:
            print("    " + C.DIM
                  + _tr("... and {m} more").format(m=n - 10) + C.RESET)

    # ── Verify ────────────────────────────────────────────────────────
    # Defer the exit until AFTER the summary + audit + --log file are written —
    # verification failure is exactly when the user wants that record. The exit
    # code distinguishes corruption (1) from source-unreadable-only (3).
    _verify_status = "ok"
    if not args.no_verify:
        banner("Phase 6 — Verification")
        _verify_status = verify_copy(copy_entries, link_map, dst,
                                     threads=args.threads)

    # ── Summary ───────────────────────────────────────────────────────
    banner("DONE")
    # A refused file was never written; counting it as copied — or as linked —
    # makes the summary claim work that did not happen. One reader for the
    # refusal list, and it checks its own arithmetic against the total and
    # against Phase 3's prediction.
    _totals = _print_files_summary(
        total_files, copy_entries, link_map, skipped_count=skipped_count,
        forecast=_refusal_forecast,
        byte_totals=(total_bytes, saved_bytes, skipped_bytes))
    if skipped_count:
        print(f"  Skipped: {C.BOLD}{skipped_count}{C.RESET} unchanged files "
              f"({C.GREEN}{fmt_size(skipped_bytes)}{C.RESET})")
    # Match Phase 3's "Data to write" — when sparse-aware copy elided holes,
    # report the actual on-disk byte count and keep the logical total in
    # parens so the savings are visible.
    # Refused files were never opened, so their bytes are not written bytes —
    # the same lie as counting them copied, in another unit.
    _refused_rels = set(_REFUSED_PATHS)
    if _HAS_SEEK_HOLE and fs_strategy != "none":
        alloc_total = sum(_effective_alloc(e) for e in copy_entries
                          if e.rel not in _refused_rels)
    else:
        alloc_total = _totals.bytes_written
    data_line = f"  Data:    {C.BOLD}{fmt_size(alloc_total)}{C.RESET} written"
    notes = []
    if _totals.bytes_refused:
        notes.append(f"{fmt_size(_totals.bytes_refused)} refused, not written")
    if _totals.bytes_deduped > 0:
        notes.append(f"{fmt_size(_totals.bytes_deduped)} saved by dedup")
    if alloc_total < _totals.bytes_written:
        notes.append(f"logical {fmt_size(_totals.bytes_written)}, sparse holes "
                     f"skipped {fmt_size(_totals.bytes_written - alloc_total)}")
    if notes:
        data_line += f"  {C.DIM}(" + ", ".join(notes) + f"){C.RESET}"
    print(data_line)
    print(f"  {_pad(_tr('Time:'), 11)}{C.BOLD}{fmt_time(elapsed)}{C.RESET}")
    print(f"  {_pad(_tr('Speed:'), 11)}{C.GREEN}{C.BOLD}{fmt_speed(speed)}{C.RESET}")
    _print_phase_timings()
    _print_preserve_summary()
    # Hidden audit file when running under sudo — written BEFORE write_log_file
    # since the latter clears _log_entries.
    # The record of a privileged copy, so it reports the run that happened:
    # the same (copied, linked, refused, bytes) the summary just printed, not
    # len() of the lists the run was asked to work from.
    write_sudo_audit(args.source, dst, {
        "mode": "local_to_local",
        "total_files": total_files, "copied": _totals.copied,
        "linked": _totals.linked, "refused": _totals.refused,
        "refused_paths": sorted(_REFUSED_PATHS)[:100],
        "skipped": skipped_count,
        "errors": sum(1 for e in _log_entries if e["action"] == "error"),
        "total_bytes": total_bytes, "bytes_written": _totals.bytes_written,
        "bytes_refused": _totals.bytes_refused,
        "dedup_saved": _totals.bytes_deduped, "elapsed_sec": round(elapsed, 2),
        "avg_speed_bps": round(speed), "hash_algo": _hash_name,
    })
    if args.log_file:
        write_log_file(args.log_file, {
            "source": args.source, "destination": dst,
            "mode": "local_to_local",
            "total_files": total_files, "copied": _totals.copied,
            "linked": _totals.linked, "refused": _totals.refused,
            "refused_paths": sorted(_REFUSED_PATHS)[:100],
            "skipped": skipped_count,
            "errors": sum(1 for e in _log_entries if e["action"] == "error"),
            "total_bytes": total_bytes,
            "bytes_written": _totals.bytes_written,
            "bytes_refused": _totals.bytes_refused,
            "dedup_saved": _totals.bytes_deduped,
            "elapsed_sec": round(elapsed, 2),
            "avg_speed_bps": round(speed), "hash_algo": _hash_name,
        })
    print()
    _exit_for_verify(_verify_status)   # exit AFTER summary/audit/log were written


def _group_writers_besides(gid, me_uid):
    """Names of users in group `gid` other than root and uid `me_uid`.

    Empty set = the group is effectively private, so group-write grants nobody
    new the ability to modify the file. None = the group could not be read
    (NIS/LDAP down, unknown gid), which must be treated as "unknown", not
    "safe". Counts BOTH kinds of membership: the group's own member list and
    every account whose PRIMARY group this is — the latter never appears in
    gr_mem and is exactly how a user-private group looks.
    """
    try:
        import grp
        import pwd
    except ImportError:                       # non-POSIX; caller is POSIX-only
        return None
    try:
        members = set(grp.getgrgid(gid).gr_mem)
    except (KeyError, OSError):
        return None
    try:
        for pw in pwd.getpwall():
            if pw.pw_gid == gid:
                members.add(pw.pw_name)
    except (OSError, KeyError):
        return None
    others = set()
    for name in members:
        try:
            uid = pwd.getpwnam(name).pw_uid
        except (KeyError, OSError):
            others.add(name)                  # unresolvable → treat as a risk
            continue
        if uid not in (0, me_uid):
            others.add(name)
    return others


def _reexec_under_sudo():
    """If --use-sudo is present and we're not already root, re-exec the whole
    command under sudo — so privileged subcommands work without the user typing
    `sudo …`: the copy path (preserve-all) and `creds lock/unlock`, which need
    root for chattr. Strips --use-sudo from the elevated argv so it doesn't
    loop. Returns (caller continues unprivileged) when no elevation is needed:
    flag absent, already root, or a platform without geteuid."""
    if "--use-sudo" not in sys.argv:
        return
    if not hasattr(os, "geteuid"):
        print(f"Error: --use-sudo is not supported on {_system}", file=sys.stderr)
        sys.exit(1)
    if os.geteuid() == 0:
        return  # already root — nothing to elevate
    # Before elevating, refuse if the script file, its directory, or the Python
    # interpreter could be modified by anyone other than the invoker or root —
    # otherwise a non-root attacker with write access to any of them would own
    # the resulting root process.
    def _check_safe_for_sudo(path, label):
        try:
            rp = _fs_realpath(path)
            st = os.stat(rp)
        except OSError as e:
            print(f"Error: --use-sudo: cannot stat {label} ({path}): {e}",
                  file=sys.stderr)
            sys.exit(1)
        me = os.geteuid()
        if st.st_uid not in (0, me):
            print(f"Error: --use-sudo: {label} {rp} is owned by uid={st.st_uid} "
                  f"(not root or invoking user uid={me}). Refusing to elevate.",
                  file=sys.stderr)
            sys.exit(1)
        if st.st_mode & stat.S_IWOTH:
            print(f"Error: --use-sudo: {label} {rp} is world writable "
                  f"(mode={oct(st.st_mode & 0o777)}). Fix: chmod go-w {rp}",
                  file=sys.stderr)
            sys.exit(1)
        if st.st_mode & stat.S_IWGRP:
            # Group-writable only matters if the group HAS somebody else in it.
            # Debian/Ubuntu/Kali give every user a private group and ship
            # umask 002, so a plain `cp` produces 0664 files whose group is the
            # user alone — refusing those made --use-sudo unusable out of the
            # box while protecting against nobody.
            others = _group_writers_besides(st.st_gid, me)
            if others is None:
                print(f"Error: --use-sudo: {label} {rp} is group writable "
                      f"(mode={oct(st.st_mode & 0o777)}) and its group "
                      f"(gid={st.st_gid}) could not be resolved, so who can "
                      f"modify it is unknown. Fix: chmod g-w {rp}",
                      file=sys.stderr)
                sys.exit(1)
            if others:
                shown = ", ".join(sorted(others)[:3])
                print(f"Error: --use-sudo: {label} {rp} is writable by group "
                      f"members other than you ({shown}), who could modify it "
                      f"before it runs as root. Fix: chmod g-w {rp}",
                      file=sys.stderr)
                sys.exit(1)
        return rp
    script_real = _check_safe_for_sudo(_get_self_path(), "script")
    _check_safe_for_sudo(os.path.dirname(script_real), "script directory")
    _check_safe_for_sudo(sys.executable, "Python interpreter")
    # $BLITCP_CREDENTIALS / $FAST_COPY_CREDENTIALS — the explicit override, and
    # the first entry in default_credentials_path()'s resolution order. It
    # points the vault ANYWHERE the caller likes, and after this re-exec ROOT is
    # the one who opens it: a vault someone else can rewrite hands the elevated
    # run a different SSH host, a different key path, a different bucket. Same
    # ownership/write test as the script itself, for whichever of the two names
    # is set. Only when the file is already there — naming a path that does not
    # exist yet is how a first run creates one, and the writer creates it 0600.
    for _cred_var in ("BLITCP_CREDENTIALS", "FAST_COPY_CREDENTIALS"):
        _cred_path = os.environ.get(_cred_var)
        if _cred_path and os.path.exists(_cred_path):
            _check_safe_for_sudo(_cred_path, f"credentials file (${_cred_var})")
    new_argv = [a for a in sys.argv if a != "--use-sudo"]
    # Without a terminal sudo cannot ask for a password at all ("a terminal is
    # required…"), which is why an elevated run launched from the GUI either
    # stalled or went looking for the terminal the GUI happened to be started
    # from. -A routes the prompt to $SUDO_ASKPASS instead; the GUI sets both.
    # Only when the variable is present, so a normal terminal run is unchanged.
    sudo_cmd = ["sudo"]
    if os.environ.get("SUDO_ASKPASS"):
        sudo_cmd.append("-A")
    # sudo resets the environment, so every secret this process was handed by
    # name — the GUI's http/ssh passwords, the credentials passphrase — is gone
    # in the elevated process unless it is named here. Losing one used to be
    # silent: the elevated run simply proceeded unauthenticated and failed
    # later with a 401 or a login page. Only vars actually present are listed,
    # so a plain terminal run still calls sudo with no extra flags.
    # Both eras of every name, exactly as the passphrase pair already does.
    # The credentials PATH is not a secret, but losing it is the same class of
    # silent failure: sudo wipes the override, root falls back to
    # default_credentials_path() — a different file, possibly the legacy one
    # beside the script — and the elevated run quietly uses connections the
    # caller never chose.
    carried = [v for v in ("FC_HTTP_PW", "FC_HTTP_HDR",
                           "FC_SSH_SRC_PW", "FC_SSH_DST_PW",
                           "BLITCP_CREDS_PASSPHRASE",
                           "FAST_COPY_CREDS_PASSPHRASE",
                           "BLITCP_CREDENTIALS",
                           "FAST_COPY_CREDENTIALS")
               if os.environ.get(v)]
    if carried:
        sudo_cmd.append("--preserve-env=" + ",".join(carried))
    try:
        os.execvp("sudo", sudo_cmd + [sys.executable] + new_argv)
    except (OSError, FileNotFoundError) as e:
        print(f"Error: cannot exec sudo: {e}", file=sys.stderr)
        sys.exit(1)


def cli_entry():
    """Full command-line entry point: the same dispatch as running blitcp
    directly — sudo re-exec, the creds/ls/deps subcommands, --version/
    --check-update/--update, then main(). Exposed as a function (not inline under
    __main__) so the GUI's `--fc-core` passthrough behaves exactly like the
    standalone CLI, not just the copy path."""
    # Elevate early (when --use-sudo is given) so it covers every subcommand,
    # including `creds lock/unlock` — must run before the creds dispatch below.
    _reexec_under_sudo()
    # `creds` manager subcommand — handled before argparse (it has its own args).
    if len(sys.argv) > 1 and sys.argv[1] == "creds":
        try:
            sys.exit(creds_manager(sys.argv[2:]))
        except KeyboardInterrupt:
            sys.stderr.write("\n  Interrupted.\n")
            sys.exit(130)
    if len(sys.argv) > 1 and sys.argv[1] in ("ls", "list-objects"):
        try:
            sys.exit(cloud_ls(sys.argv[2:]))
        except KeyboardInterrupt:
            sys.stderr.write("\n  Interrupted.\n")
            sys.exit(130)
    if len(sys.argv) > 1 and sys.argv[1] in ("deps", "check-deps", "doctor"):
        install = any(a in ("--install", "-i") for a in sys.argv[2:])
        try:
            sys.exit(check_dependencies(install=install))
        except KeyboardInterrupt:
            sys.stderr.write("\n  Interrupted.\n")
            sys.exit(130)
    # Handle --version, --check-update, --update before argparse requires positional args
    if "--version" in sys.argv or "-V" in sys.argv:
        # First line stays byte-identical — scripts parse it.
        print(f"blitcp v{__version__}")
        print(_tr("Support development: {url}").format(url=SUPPORT_URL + " · " + SUPPORT_URL_ALT))
        sys.exit(0)
    if "--check-update" in sys.argv:
        check_update_info()
        sys.exit(0)
    if "--update" in sys.argv:
        # Refuse self-update under sudo: a compromised release publisher would
        # otherwise install a trojan that runs as root the moment the user
        # invokes the next sudo run. Force the user to update as themselves
        # first, then re-elevate explicitly.
        if (hasattr(os, "geteuid") and os.geteuid() == 0) or os.environ.get("SUDO_USER"):
            print("Error: --update is not allowed under sudo. "
                  "Run as your normal user; the updated binary will only run "
                  "as root via a separate, deliberate sudo invocation.",
                  file=sys.stderr)
            sys.exit(1)
        # Windows: clean up .old file from previous update
        if _system == "Windows":
            try:
                old = _get_self_path() + ".old"
                if os.path.exists(old):
                    os.remove(old)
            except OSError:
                pass
        # Check for optional version argument: --update v2.4.1
        idx = sys.argv.index("--update")
        target_ver = None
        if idx + 1 < len(sys.argv) and not sys.argv[idx + 1].startswith("-"):
            target_ver = sys.argv[idx + 1]
        # Optional pinned SHA-256: --update-sha256 <hex>
        expected_sha = None
        if "--update-sha256" in sys.argv:
            sidx = sys.argv.index("--update-sha256")
            if sidx + 1 >= len(sys.argv):
                print("Error: --update-sha256 requires a hex value.", file=sys.stderr)
                sys.exit(1)
            expected_sha = sys.argv[sidx + 1].strip().lower()
            if len(expected_sha) != 64 or any(c not in "0123456789abcdef" for c in expected_sha):
                print("Error: --update-sha256 must be 64 hex characters.", file=sys.stderr)
                sys.exit(1)
        self_update(target_version=target_ver, expected_sha256=expected_sha)
        _post_update_dep_check()
        sys.exit(0)
    # --use-sudo elevation is handled at the top of __main__ (see
    # _reexec_under_sudo) so it also covers the `creds` subcommands.

    # Windows: clean up .old file from previous update on normal runs
    if _system == "Windows":
        try:
            old = _get_self_path() + ".old"
            if os.path.exists(old):
                os.remove(old)
        except OSError:
            pass
    try:
        main()
    except SystemExit as e:
        # main() exits through sys.exit() on every path that matters; the
        # quiet summary has to run for all of them, not just a clean return.
        code = 0 if e.code is None else e.code
        if code == 0:
            _maybe_auto_update_check()
        if not isinstance(code, int):
            # SystemExit("message") — Python prints the message and exits 1.
            # Left alone it would land BELOW our verdict; in quiet mode emit
            # the reason first, then the verdict, and exit 1 ourselves.
            if QUIET:
                sys.stderr.write(str(code).rstrip() + "\n")
                _quiet_finish(1, reason_shown=True)
                raise SystemExit(1)
            raise
        _quiet_finish(code)
        raise
    except KeyboardInterrupt:
        if QUIET:
            _quiet_finish(130)      # its own one-liner; no banner on top
        else:
            print(f"\n  {C.YELLOW}Interrupted.{C.RESET}")
        sys.exit(130)
    else:
        _quiet_finish(0)
        _maybe_auto_update_check()


if __name__ == "__main__":
    cli_entry()
